@Service
@Slf4j
public class DeviceFilterService {

    private final PinotDeviceRepository pinotDeviceRepository;
    private final OrganizationRepository organizationRepository;

    public DeviceFilterService(PinotDeviceRepository pinotDeviceRepository,
                              OrganizationRepository organizationRepository) {
        this.pinotDeviceRepository = pinotDeviceRepository;
        this.organizationRepository = organizationRepository;
    }

    public CompletableFuture<DeviceFilters> getDeviceFilters(DeviceFilterOptions filters) {
        List<String> statuses = filters != null && filters.getStatuses() != null ?
                filters.getStatuses().stream().map(Enum::name).toList() : emptyList();
        List<String> deviceTypes = filters != null && filters.getDeviceTypes() != null ?
                filters.getDeviceTypes().stream().map(Enum::name).toList() : emptyList();
        List<String> osTypes = filters != null ? filters.getOsTypes() : emptyList();
        List<String> organizationIds = filters != null ? filters.getOrganizationIds() : emptyList();
        List<String> tagNames = filters != null ? filters.getTagNames() : emptyList();

        CompletableFuture<Map<String, Integer>> statusesFuture = CompletableFuture.supplyAsync(() ->
                pinotDeviceRepository.getStatusFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
        CompletableFuture<Map<String, Integer>> deviceTypesFuture = CompletableFuture.supplyAsync(() ->
                pinotDeviceRepository.getDeviceTypeFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
        CompletableFuture<Map<String, Integer>> osTypesFuture = CompletableFuture.supplyAsync(() ->
                pinotDeviceRepository.getOsTypeFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
        CompletableFuture<Map<String, Integer>> organizationsFuture = CompletableFuture.supplyAsync(() ->
                pinotDeviceRepository.getOrganizationFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
        CompletableFuture<Map<String, Integer>> tagsFuture = CompletableFuture.supplyAsync(() ->
                pinotDeviceRepository.getTagFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
        CompletableFuture<Integer> filteredCountFuture = CompletableFuture.supplyAsync(() ->
                pinotDeviceRepository.getFilteredDeviceCount(statuses, deviceTypes, osTypes, organizationIds, tagNames));

        return CompletableFuture.allOf(
                        statusesFuture, deviceTypesFuture, osTypesFuture,
                        organizationsFuture, tagsFuture, filteredCountFuture)
                .thenApply(v -> DeviceFilters.builder()
                        .statuses(convertMapToFilterOptions(statusesFuture.join()))
                        .deviceTypes(convertMapToFilterOptions(deviceTypesFuture.join()))
                        .osTypes(convertMapToFilterOptions(osTypesFuture.join()))
                        .organizationIds(convertMapToOrganizationFilterOptions(organizationsFuture.join()))
                        .tags(convertMapToTagFilterOptions(tagsFuture.join()))
                        .filteredCount(filteredCountFuture.join())
                        .build()
                );
    }

    private List<DeviceFilterOption> convertMapToFilterOptions(Map<String, Integer> repositoryOptions) {
        if (repositoryOptions == null || repositoryOptions.isEmpty()) {
            return new ArrayList<>();
        }
        return repositoryOptions.entrySet().stream()
                .map(entry -> DeviceFilterOption.builder()
                        .value(entry.getKey())
                        .label(entry.getKey())
                        .count(entry.getValue())
                        .build())
                .collect(Collectors.toList());
    }

    private List<TagFilterOption> convertMapToTagFilterOptions(Map<String, Integer> repositoryOptions) {
        if (repositoryOptions == null || repositoryOptions.isEmpty()) {
            return new ArrayList<>();
        }
        return repositoryOptions.entrySet().stream()
                .map(entry -> TagFilterOption.builder()
                        .value(entry.getKey())
                        .label(entry.getKey())
                        .count(entry.getValue())
                        .build())
                .collect(Collectors.toList());
    }

    /**
     * Convert organization IDs map to filter options with organization names as labels.
     * 
     * Performance note:
     * - Only loads organizations that actually exist in the filter (typically 5-50 items)
     * - MongoDB index scan on organizationId: 1-5ms
     * - Simpler than Redis cache (no cache invalidation, no stale data, no extra dependency)
     * - Frontend already has Apollo Client cache for deviceFilters query
     */
    private List<DeviceFilterOption> convertMapToOrganizationFilterOptions(Map<String, Integer> repositoryOptions) {
        if (repositoryOptions == null || repositoryOptions.isEmpty()) {
            return new ArrayList<>();
        }

        // Get only the organization IDs that are present in filters (not all organizations)
        // Use Set directly from keySet() - no need to convert to ArrayList
        var organizationIds = repositoryOptions.keySet();

        // Batch load only needed organizations (1-5ms with MongoDB index)
        List<Organization> organizations = organizationRepository.findByOrganizationIdIn(organizationIds);

        // Create lookup map
        Map<String, String> organizationNames = organizations.stream()
                .collect(Collectors.toMap(
                        Organization::getOrganizationId,
                        Organization::getName
                ));

        // Build filter options with names as labels
        return repositoryOptions.entrySet().stream()
                .map(entry -> {
                    String organizationId = entry.getKey();
                    String organizationName = organizationNames.getOrDefault(organizationId, organizationId);

                    return DeviceFilterOption.builder()
                            .value(organizationId)
                            .label(organizationName)
                            .count(entry.getValue())
                            .build();
                })
                .collect(Collectors.toList());
    }

}

private List<DeviceFilterOption> convertMapToFilterOptions(Map<String, Integer> repositoryOptions) {
    if (repositoryOptions == null || repositoryOptions.isEmpty()) {
        return new ArrayList<>();
    }
    return repositoryOptions.entrySet().stream()
            .map(entry -> DeviceFilterOption.builder()
                    .value(entry.getKey())
                    .label(entry.getKey())
                    .count(entry.getValue())
                    .build())
            .collect(Collectors.toList());
}

private List<DeviceFilterOption> convertMapToOrganizationFilterOptions(Map<String, Integer> repositoryOptions) {
    if (repositoryOptions == null || repositoryOptions.isEmpty()) {
        return new ArrayList<>();
    }

    // Get only the organization IDs that are present in filters (not all organizations)
    // Use Set directly from keySet() - no need to convert to ArrayList
    var organizationIds = repositoryOptions.keySet();

    // Batch load only needed organizations (1-5ms with MongoDB index)
    List<Organization> organizations = organizationRepository.findByOrganizationIdIn(organizationIds);

    // Create lookup map
    Map<String, String> organizationNames = organizations.stream()
            .collect(Collectors.toMap(
                    Organization::getOrganizationId,
                    Organization::getName
            ));

    // Build filter options with names as labels
    return repositoryOptions.entrySet().stream()
            .map(entry -> {
                String organizationId = entry.getKey();
                String organizationName = organizationNames.getOrDefault(organizationId, organizationId);

                return DeviceFilterOption.builder()
                        .value(organizationId)
                        .label(organizationName)
                        .count(entry.getValue())
                        .build();
            })
            .collect(Collectors.toList());
}

private List<TagFilterOption> convertMapToTagFilterOptions(Map<String, Integer> repositoryOptions) {
    if (repositoryOptions == null || repositoryOptions.isEmpty()) {
        return new ArrayList<>();
    }
    return repositoryOptions.entrySet().stream()
            .map(entry -> TagFilterOption.builder()
                    .value(entry.getKey())
                    .label(entry.getKey())
                    .count(entry.getValue())
                    .build())
            .collect(Collectors.toList());
}

public CompletableFuture<DeviceFilters> getDeviceFilters(DeviceFilterOptions filters) {
    List<String> statuses = filters != null && filters.getStatuses() != null ?
            filters.getStatuses().stream().map(Enum::name).toList() : emptyList();
    List<String> deviceTypes = filters != null && filters.getDeviceTypes() != null ?
            filters.getDeviceTypes().stream().map(Enum::name).toList() : emptyList();
    List<String> osTypes = filters != null ? filters.getOsTypes() : emptyList();
    List<String> organizationIds = filters != null ? filters.getOrganizationIds() : emptyList();
    List<String> tagNames = filters != null ? filters.getTagNames() : emptyList();

    CompletableFuture<Map<String, Integer>> statusesFuture = CompletableFuture.supplyAsync(() ->
            pinotDeviceRepository.getStatusFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
    CompletableFuture<Map<String, Integer>> deviceTypesFuture = CompletableFuture.supplyAsync(() ->
            pinotDeviceRepository.getDeviceTypeFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
    CompletableFuture<Map<String, Integer>> osTypesFuture = CompletableFuture.supplyAsync(() ->
            pinotDeviceRepository.getOsTypeFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
    CompletableFuture<Map<String, Integer>> organizationsFuture = CompletableFuture.supplyAsync(() ->
            pinotDeviceRepository.getOrganizationFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
    CompletableFuture<Map<String, Integer>> tagsFuture = CompletableFuture.supplyAsync(() ->
            pinotDeviceRepository.getTagFilterOptions(statuses, deviceTypes, osTypes, organizationIds, tagNames));
    CompletableFuture<Integer> filteredCountFuture = CompletableFuture.supplyAsync(() ->
            pinotDeviceRepository.getFilteredDeviceCount(statuses, deviceTypes, osTypes, organizationIds, tagNames));

    return CompletableFuture.allOf(
                    statusesFuture, deviceTypesFuture, osTypesFuture,
                    organizationsFuture, tagsFuture, filteredCountFuture)
            .thenApply(v -> DeviceFilters.builder()
                    .statuses(convertMapToFilterOptions(statusesFuture.join()))
                    .deviceTypes(convertMapToFilterOptions(deviceTypesFuture.join()))
                    .osTypes(convertMapToFilterOptions(osTypesFuture.join()))
                    .organizationIds(convertMapToOrganizationFilterOptions(organizationsFuture.join()))
                    .tags(convertMapToTagFilterOptions(tagsFuture.join()))
                    .filteredCount(filteredCountFuture.join())
                    .build()
            );
}

@Service
@Slf4j
@Validated
@RequiredArgsConstructor
public class DeviceService {

    private static final String MACHINE_ID_FIELD = "machineId";

    private final MachineRepository machineRepository;
    private final TagRepository tagRepository;
    private final MachineTagRepository machineTagRepository;
    private final DeviceStatusProcessor deviceStatusProcessor;

    public Optional<Machine> findByMachineId(@NotBlank String machineId) {
        log.debug("Finding machine by ID: {}", machineId);
        Optional<Machine> result = machineRepository.findByMachineId(machineId);
        log.debug("Found machine: {}", result.isPresent());
        return result;
    }

    public CountedGenericQueryResult<Machine> queryDevices(DeviceFilterOptions filterOptions,
                                                  CursorPaginationCriteria paginationCriteria,
                                                  String search,
                                                  SortInput sort) {
        log.debug("Querying devices with filter: {}, pagination: {}, search: {}, sort: {}",
                filterOptions, paginationCriteria, search, sort);

        CursorPaginationCriteria normalizedPagination = paginationCriteria.normalize();
        Query query = buildDeviceQuery(filterOptions, search);

        String sortField = validateSortField(sort != null ? sort.getField() : null);
        SortDirection sortDirection = (sort != null && sort.getDirection() != null) ? 
            sort.getDirection() : SortDirection.DESC;

        List<Machine> pageItems = fetchPageItems(query, normalizedPagination, sortField, sortDirection);
        boolean hasNextPage = pageItems.size() == normalizedPagination.getLimit();

        CursorPageInfo pageInfo = buildPageInfo(pageItems, hasNextPage, normalizedPagination.hasCursor());

        return CountedGenericQueryResult.<Machine>builder()
                .items(pageItems)
                .pageInfo(pageInfo)
                .filteredCount(pageItems.size())
                .build();
    }

    private List<Machine> fetchPageItems(@NotNull Query query, CursorPaginationCriteria criteria,
                                          String sortField, SortDirection sortDirection) {
        List<Machine> machines = machineRepository.findMachinesWithCursor(
            query, criteria.getCursor(), criteria.getLimit() + 1, sortField, sortDirection.name());
        return machines.size() > criteria.getLimit() 
            ? machines.subList(0, criteria.getLimit())
            : machines;
    }

    private CursorPageInfo buildPageInfo(List<Machine> pageItems, boolean hasNextPage, boolean hasPreviousPage) {
        String startCursor = pageItems.isEmpty() ? null : pageItems.getFirst().getId();
        String endCursor = pageItems.isEmpty() ? null : pageItems.getLast().getId();

        return CursorPageInfo.builder()
                .hasNextPage(hasNextPage)
                .hasPreviousPage(hasPreviousPage)
                .startCursor(startCursor)
                .endCursor(endCursor)
                .build();
    }

    private Query buildDeviceQuery(DeviceFilterOptions filter, String search) {
        MachineQueryFilter queryFilter = mapToMachineQueryFilter(filter);
        Query query = machineRepository.buildDeviceQuery(queryFilter, search);

        if (filter != null && filter.getTagNames() != null && !filter.getTagNames().isEmpty()) {
            List<String> machineIds = resolveTagNamesToMachineIds(filter.getTagNames());
            if (!machineIds.isEmpty()) {
                query.addCriteria(Criteria.where(MACHINE_ID_FIELD).in(machineIds));
            } else {
                query.addCriteria(Criteria.where(MACHINE_ID_FIELD).exists(false));
            }
        }
        return query;
    }

    private List<String> resolveTagNamesToMachineIds(List<String> tagNames) {
        List<Tag> tags = tagRepository.findByNameIn(tagNames);
        List<String> tagIds = tags.stream()
                .map(Tag::getId)
                .collect(Collectors.toList());
        if (tagIds.isEmpty()) {
            return new ArrayList<>();
        }
        List<MachineTag> machineTags = machineTagRepository.findByTagIdIn(tagIds);
        return machineTags.stream()
                .map(MachineTag::getMachineId)
                .distinct()
                .collect(Collectors.toList());
    }

    private MachineQueryFilter mapToMachineQueryFilter(DeviceFilterOptions filter) {
        if (filter == null) {
            return new MachineQueryFilter();
        }
        MachineQueryFilter queryFilter = new MachineQueryFilter();
        queryFilter.setStatuses(filter.getStatuses() != null ?
                filter.getStatuses().stream().map(Enum::name).collect(Collectors.toList()) : null);
        queryFilter.setDeviceTypes(filter.getDeviceTypes() != null ?
                filter.getDeviceTypes().stream().map(Enum::name).collect(Collectors.toList()) : null);
        queryFilter.setOsTypes(filter.getOsTypes());
        queryFilter.setOrganizationIds(filter.getOrganizationIds());
        queryFilter.setTagNames(filter.getTagNames());
        return queryFilter;
    }

    public void softDeleteByMachineId(@NotBlank String machineId) {
        log.info("Soft deleting device with machineId={}", machineId);
        Machine machine = machineRepository.findByMachineId(machineId)
                .orElseThrow(() -> new DeviceNotFoundException("Device not found: " + machineId));

        if (machine.getStatus() != DeviceStatus.DELETED) {
            machine.setStatus(DeviceStatus.DELETED);
            machineRepository.save(machine);
            log.info("Device {} marked as DELETED", machineId);
        } else {
            log.warn("Device {} is already DELETED", machineId);
        }
    }

    public void updateStatusByMachineId(@NotBlank String machineId, @NotNull DeviceStatus status) {
        log.info("Updating device status. machineId={}, newStatus={}", machineId, status);
        Machine machine = machineRepository.findByMachineId(machineId)
                .orElseThrow(() -> new DeviceNotFoundException("Device not found: " + machineId));
        if (machine.getStatus() == status) {
            log.info("Device {} already has status {}", machineId, status);
            return;
        }
        machine.setStatus(status);
        machine.setUpdatedAt(now());
        machineRepository.save(machine);
        deviceStatusProcessor.postProcessStatusUpdated(machine);
        log.info("Device {} status updated to {}", machineId, status);
    }

    private String validateSortField(String field) {
        if (field == null || field.trim().isEmpty()) {
            return machineRepository.getDefaultSortField();
        }
        String trimmedField = field.trim();
        if (!machineRepository.isSortableField(trimmedField)) {
            log.warn("Invalid sort field requested for devices: {}, using default", field);
            return machineRepository.getDefaultSortField();
        }
        return trimmedField;
    }
}

