public ErrorResponse handleHttpRequestMethodNotSupported(HttpRequestMethodNotSupportedException ex) {
    log.error("Method not supported: ", ex);
    return new ErrorResponse("method_not_allowed", ex.getMessage());
}

@ExceptionHandler(IllegalArgumentException.class)
@ResponseStatus(BAD_REQUEST)
public ErrorResponse handleIllegalArgumentException(IllegalArgumentException ex) {
    log.error("Invalid request: ", ex);
    return new ErrorResponse("bad_request", ex.getMessage());
}

@ExceptionHandler(IllegalStateException.class)
@ResponseStatus(HttpStatus.CONFLICT)
public ErrorResponse handleIllegalState(IllegalStateException ex) {
    log.warn("Conflict: {}", ex.getMessage());
    return new ErrorResponse("CONFLICT", ex.getMessage());
}

@ExceptionHandler(MissingRequestHeaderException.class)
@ResponseStatus(BAD_REQUEST)
public ErrorResponse handleMissingRequestHeaderException(MissingRequestHeaderException ex) {
    log.error("Missing required header: ", ex);
    return new ErrorResponse("bad_request", "Required header '" + ex.getHeaderName() + "' is missing");
}

@ExceptionHandler(ResponseStatusException.class)
public ResponseEntity<ErrorResponse> handleResponseStatusException(ResponseStatusException ex) {
    log.warn("Response status exception: {} - {}", ex.getStatusCode(), ex.getReason());
    ErrorResponse errorResponse = new ErrorResponse("error", ex.getReason());
    return ResponseEntity.status(ex.getStatusCode()).body(errorResponse);
}

@ExceptionHandler(UserNotFoundException.class)
@ResponseStatus(NOT_FOUND)
public ErrorResponse handleUserNotFound(UserNotFoundException ex) {
    log.warn("User not found: {}", ex.getMessage());
    return new ErrorResponse("USER_NOT_FOUND", ex.getMessage());
}

@ExceptionHandler(OperationNotAllowedException.class)
@ResponseStatus(FORBIDDEN)
public ErrorResponse handleUserSelfDelete(OperationNotAllowedException ex) {
    log.warn("Conflict: {}", ex.getMessage());
    return new ErrorResponse("OPERATION_NOT_ALLOWED", ex.getMessage());
}

@ExceptionHandler(MethodArgumentNotValidException.class)
@ResponseStatus(BAD_REQUEST)
public ErrorResponse handleValidationException(MethodArgumentNotValidException ex) {
    String errorMessage = ex.getBindingResult().getFieldErrors().stream()
            .map(DefaultMessageSourceResolvable::getDefaultMessage)
            .collect(Collectors.joining(", "));

    log.error("Validation error: {}", errorMessage);
    return new ErrorResponse("bad_request", errorMessage);
}

@Component
@Slf4j
public class GraphQLExceptionHandler extends SimpleDataFetcherExceptionHandler {

    @Override
    public CompletableFuture<DataFetcherExceptionHandlerResult> handleException(
            DataFetcherExceptionHandlerParameters handlerParameters) {

        Throwable exception = handlerParameters.getException();
        log.error("GraphQL error occurred", exception);

        GraphQLError error;

        if (exception instanceof PinotQueryException) {
            error = GraphQLError.newError()
                    .message("Query failed. Please try again later.")
                    .extensions(java.util.Map.of(
                            "code", "PINOT_QUERY_ERROR",
                            "timestamp", System.currentTimeMillis()
                    ))
                    .build();
        } else if (exception instanceof DataAccessException) {
            error = GraphQLError.newError()
                    .message("Database operation failed. Please try again later.")
                    .extensions(java.util.Map.of(
                            "code", "DATABASE_ERROR",
                            "timestamp", System.currentTimeMillis()
                    ))
                    .build();
        } else if (exception instanceof IllegalArgumentException) {
            error = GraphQLError.newError()
                    .message(exception.getMessage())
                    .extensions(java.util.Map.of(
                            "code", "VALIDATION_ERROR",
                            "timestamp", System.currentTimeMillis()
                    ))
                    .build();
        } else if (exception instanceof RuntimeException) {
            error = GraphQLError.newError()
                    .message("An unexpected error occurred. Please try again later.")
                    .extensions(java.util.Map.of(
                            "code", "INTERNAL_ERROR",
                            "timestamp", System.currentTimeMillis()
                    ))
                    .build();
        } else {
            error = GraphQLError.newError()
                    .message("An unexpected error occurred. Please try again later.")
                    .extensions(java.util.Map.of(
                            "code", "UNKNOWN_ERROR",
                            "timestamp", System.currentTimeMillis()
                    ))
                    .build();
        }

        return CompletableFuture.completedFuture(
                DataFetcherExceptionHandlerResult.newResult()
                        .error(error)
                        .build()
        );
    }
}

