public record AuthenticationKeyPair(
        RSAPublicKey publicKey,
        RSAPrivateKey privateKey,
        String publicPem,
        String privatePem
) {
}

public interface AuthenticationKeyPairGenerator {
    AuthenticationKeyPair generate();
}

public final class PemUtil {
    private PemUtil() {
    }

    public static RSAPublicKey parsePublicKey(String pem) {
        try {
            String content = pem.replace("-----BEGIN PUBLIC KEY-----", "")
                    .replace("-----END PUBLIC KEY-----", "").replaceAll("\\s", "");
            byte[] bytes = Base64.getDecoder().decode(content);
            X509EncodedKeySpec spec = new X509EncodedKeySpec(bytes);
            return (RSAPublicKey) KeyFactory.getInstance("RSA").generatePublic(spec);
        } catch (Exception e) {
            throw new IllegalStateException("Invalid public key PEM", e);
        }
    }

    public static RSAPrivateKey parsePrivateKey(String pem) {
        try {
            String content = pem.replace("-----BEGIN PRIVATE KEY-----", "")
                    .replace("-----END PRIVATE KEY-----", "").replaceAll("\\s", "");
            byte[] bytes = Base64.getDecoder().decode(content);
            PKCS8EncodedKeySpec spec = new PKCS8EncodedKeySpec(bytes);
            return (RSAPrivateKey) KeyFactory.getInstance("RSA").generatePrivate(spec);
        } catch (Exception e) {
            throw new IllegalStateException("Invalid private key PEM", e);
        }
    }

    public static String toPublicPem(RSAPublicKey key) {
        String base64 = Base64.getEncoder().encodeToString(key.getEncoded());
        return "-----BEGIN PUBLIC KEY-----\n" + wrap(base64) + "\n-----END PUBLIC KEY-----\n";
    }

    public static String toPrivatePem(RSAPrivateKey key) {
        String base64 = Base64.getEncoder().encodeToString(key.getEncoded());
        return "-----BEGIN PRIVATE KEY-----\n" + wrap(base64) + "\n-----END PRIVATE KEY-----\n";
    }

    private static String wrap(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i += 64) {
            sb.append(s, i, Math.min(i + 64, s.length())).append('\n');
        }
        return sb.toString().trim();
    }
}

public static RSAPrivateKey parsePrivateKey(String pem) {
    try {
        String content = pem.replace("-----BEGIN PRIVATE KEY-----", "")
                .replace("-----END PRIVATE KEY-----", "").replaceAll("\\s", "");
        byte[] bytes = Base64.getDecoder().decode(content);
        PKCS8EncodedKeySpec spec = new PKCS8EncodedKeySpec(bytes);
        return (RSAPrivateKey) KeyFactory.getInstance("RSA").generatePrivate(spec);
    } catch (Exception e) {
        throw new IllegalStateException("Invalid private key PEM", e);
    }
}

public static RSAPublicKey parsePublicKey(String pem) {
    try {
        String content = pem.replace("-----BEGIN PUBLIC KEY-----", "")
                .replace("-----END PUBLIC KEY-----", "").replaceAll("\\s", "");
        byte[] bytes = Base64.getDecoder().decode(content);
        X509EncodedKeySpec spec = new X509EncodedKeySpec(bytes);
        return (RSAPublicKey) KeyFactory.getInstance("RSA").generatePublic(spec);
    } catch (Exception e) {
        throw new IllegalStateException("Invalid public key PEM", e);
    }
}

public static String toPrivatePem(RSAPrivateKey key) {
    String base64 = Base64.getEncoder().encodeToString(key.getEncoded());
    return "-----BEGIN PRIVATE KEY-----\n" + wrap(base64) + "\n-----END PRIVATE KEY-----\n";
}

public static String toPublicPem(RSAPublicKey key) {
    String base64 = Base64.getEncoder().encodeToString(key.getEncoded());
    return "-----BEGIN PUBLIC KEY-----\n" + wrap(base64) + "\n-----END PUBLIC KEY-----\n";
}

private static String wrap(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i += 64) {
        sb.append(s, i, Math.min(i + 64, s.length())).append('\n');
    }
    return sb.toString().trim();
}

@Component
public class RsaAuthenticationKeyPairGenerator implements AuthenticationKeyPairGenerator {

    @Override
    public AuthenticationKeyPair generate() {
        try {
            KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
            kpg.initialize(2048);
            KeyPair kp = kpg.generateKeyPair();
            RSAPublicKey pub = (RSAPublicKey) kp.getPublic();
            RSAPrivateKey priv = (RSAPrivateKey) kp.getPrivate();
            String publicPem = PemUtil.toPublicPem(pub);
            String privatePem = PemUtil.toPrivatePem(priv);
            return new AuthenticationKeyPair(pub, priv, publicPem, privatePem);
        } catch (Exception e) {
            throw new IllegalStateException("Failed to generate RSA key pair", e);
        }
    }
}

@Override
public AuthenticationKeyPair generate() {
    try {
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
        kpg.initialize(2048);
        KeyPair kp = kpg.generateKeyPair();
        RSAPublicKey pub = (RSAPublicKey) kp.getPublic();
        RSAPrivateKey priv = (RSAPrivateKey) kp.getPrivate();
        String publicPem = PemUtil.toPublicPem(pub);
        String privatePem = PemUtil.toPrivatePem(priv);
        return new AuthenticationKeyPair(pub, priv, publicPem, privatePem);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to generate RSA key pair", e);
    }
}

@Service
@RequiredArgsConstructor
@Slf4j
public class TenantKeyService {

    private final TenantKeyRepository tenantKeyRepository;
    private final EncryptionService encryptionService;
    private final AuthenticationKeyPairGenerator keyPairGenerator;

    public RSAKey getOrCreateActiveKey(String tenantId) {
        long activeCount = tenantKeyRepository.countByTenantIdAndActiveTrue(tenantId);
        if (activeCount > 1) {
            log.warn("Multiple active signing keys detected for tenantId='{}' (count={}) - this may cause kid mismatches", tenantId, activeCount);
        }

        TenantKey doc = tenantKeyRepository.findFirstByTenantIdAndActiveTrue(tenantId).orElse(null);
        if (doc == null) {
            log.info("No active signing key found for tenantId='{}'. Generating a new key...", tenantId);
            doc = createAndStore(tenantId);
            log.info("Generated new signing key for tenantId='{}' with kid='{}' createdAt='{}'", tenantId, doc.getKeyId(), doc.getCreatedAt());
        } else {
            log.debug("Using active signing key for tenantId='{}' with kid='{}' createdAt='{}'", tenantId, doc.getKeyId(), doc.getCreatedAt());
        }

        RSAPublicKey pub = PemUtil.parsePublicKey(doc.getPublicPem());
        RSAPrivateKey priv = PemUtil.parsePrivateKey(encryptionService.decryptClientSecret(doc.getPrivateEncrypted()));
