@Slf4j
@RequiredArgsConstructor
public class SsoAuthorizationRequestResolver implements OAuth2AuthorizationRequestResolver {

    private final DefaultOAuth2AuthorizationRequestResolver delegate;
    private final SsoCookieCodec ssoCookieCodec;

    public SsoAuthorizationRequestResolver(ClientRegistrationRepository repo,
                                           SsoCookieCodec ssoCookieCodec) {
        this.delegate = new DefaultOAuth2AuthorizationRequestResolver(repo, "/oauth2/authorization");
        this.ssoCookieCodec = ssoCookieCodec;
    }

    @Override
    public OAuth2AuthorizationRequest resolve(HttpServletRequest request) {
        OAuth2AuthorizationRequest req = delegate.resolve(request);
        return maybeInjectStateFromCookie(request, req);
    }

    @Override
    public OAuth2AuthorizationRequest resolve(HttpServletRequest request, String clientRegistrationId) {
        OAuth2AuthorizationRequest req = delegate.resolve(request, clientRegistrationId);
        return maybeInjectStateFromCookie(request, req);
    }

    private OAuth2AuthorizationRequest maybeInjectStateFromCookie(HttpServletRequest request,
                                                                  OAuth2AuthorizationRequest req) {
        if (req == null) return null;
        Optional<String> state = extractStateFromCookie(request);
        return state.map(s -> OAuth2AuthorizationRequest.from(req).state(s).build()).orElse(req);
    }

    private Optional<String> extractStateFromCookie(HttpServletRequest request) {
        Cookie[] cookies = request.getCookies();
        if (cookies == null) return Optional.empty();
        for (Cookie c : cookies) {
            String name = c.getName();
            String token = c.getValue();
            if (token == null || token.isBlank()) continue;
            if (SsoRegistrationConstants.COOKIE_SSO_REG.equals(name)) {
                var payload = ssoCookieCodec.decodeTenant(token);
                if (payload.isPresent()) return Optional.ofNullable(payload.get().s());
            } else if (SsoRegistrationConstants.COOKIE_SSO_INVITE.equals(name)) {
                var payload = ssoCookieCodec.decodeInvite(token);
                if (payload.isPresent()) return Optional.ofNullable(payload.get().s());
            }
        }
        return Optional.empty();
    }
}

private Optional<String> extractStateFromCookie(HttpServletRequest request) {
    Cookie[] cookies = request.getCookies();
    if (cookies == null) return Optional.empty();
    for (Cookie c : cookies) {
        String name = c.getName();
        String token = c.getValue();
        if (token == null || token.isBlank()) continue;
        if (SsoRegistrationConstants.COOKIE_SSO_REG.equals(name)) {
            var payload = ssoCookieCodec.decodeTenant(token);
            if (payload.isPresent()) return Optional.ofNullable(payload.get().s());
        } else if (SsoRegistrationConstants.COOKIE_SSO_INVITE.equals(name)) {
            var payload = ssoCookieCodec.decodeInvite(token);
            if (payload.isPresent()) return Optional.ofNullable(payload.get().s());
        }
    }
    return Optional.empty();
}

private OAuth2AuthorizationRequest maybeInjectStateFromCookie(HttpServletRequest request,
                                                              OAuth2AuthorizationRequest req) {
    if (req == null) return null;
    Optional<String> state = extractStateFromCookie(request);
    return state.map(s -> OAuth2AuthorizationRequest.from(req).state(s).build()).orElse(req);
}

@Override
public OAuth2AuthorizationRequest resolve(HttpServletRequest request, String clientRegistrationId) {
    OAuth2AuthorizationRequest req = delegate.resolve(request, clientRegistrationId);
    return maybeInjectStateFromCookie(request, req);
}

@Service
@RequiredArgsConstructor
public class SsoCookieCodec {

    private static final Base64.Encoder B64 = Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder B64D = Base64.getUrlDecoder();
    private static final String ALG = "HmacSHA256";

    private final ObjectMapper objectMapper;

    @Value("${openframe.sso.registration-cookie.secret:change-me-in-config}")
    private String hmacSecret;

    public String encode(Object payload) {
        try {
            byte[] json = objectMapper.writeValueAsBytes(payload);
            String body = B64.encodeToString(json);
            String sig = sign(body);
            return body + "." + sig;
        } catch (Exception e) {
            throw new IllegalStateException("cookie_sign_failed", e);
        }
    }

    public String encodeTenant(SsoTenantRegCookiePayload payload) {
        return encode(payload);
    }

    public String encodeInvite(SsoInviteCookiePayload payload) {
        return encode(payload);
    }

    public Optional<SsoTenantRegCookiePayload> decodeTenant(String token) {
        return decode(token, SsoTenantRegCookiePayload.class);
    }

    public Optional<SsoInviteCookiePayload> decodeInvite(String token) {
        return decode(token, SsoInviteCookiePayload.class);
    }

    public <T> Optional<T> decode(String token, Class<T> type) {
        try {
            if (token == null) {
                return Optional.empty();
            }
            int dot = token.indexOf('.');
            if (dot <= 0 || dot >= token.length() - 1) {
                return Optional.empty();
            }
            String body = token.substring(0, dot);
            String sig = token.substring(dot + 1);
            String expected = sign(body);
            if (!constantTimeEquals(sig, expected)) {
                return Optional.empty();
            }
            byte[] json = B64D.decode(body);
            T payload = objectMapper.readValue(json, type);
            long exp = extractExp(payload);
            if (exp > 0 && exp < Instant.now().getEpochSecond()) {
                return Optional.empty();
            }
            return Optional.of(payload);
        } catch (Exception e) {
            return Optional.empty();
        }
    }

    private long extractExp(Object payload) {
        try {
            var m = payload.getClass().getMethod("exp");
            Object v = m.invoke(payload);
            return v instanceof Number n ? n.longValue() : 0L;
        } catch (Exception ignored) {
            return 0L;
        }
    }

    private String sign(String body) throws Exception {
        Mac mac = Mac.getInstance(ALG);
        mac.init(new SecretKeySpec(hmacSecret.getBytes(StandardCharsets.UTF_8), ALG));
        byte[] raw = mac.doFinal(body.getBytes(StandardCharsets.UTF_8));
        return B64.encodeToString(raw);
    }

    private static boolean constantTimeEquals(String a, String b) {
        if (a == null || b == null) return false;
        if (a.length() != b.length()) return false;
        int result = 0;
        for (int i = 0; i < a.length(); i++) {
            result |= a.charAt(i) ^ b.charAt(i);
        }
        return result == 0;
    }
}

private static boolean constantTimeEquals(String a, String b) {
    if (a == null || b == null) return false;
    if (a.length() != b.length()) return false;
    int result = 0;
    for (int i = 0; i < a.length(); i++) {
        result |= a.charAt(i) ^ b.charAt(i);
    }
    return result == 0;
}

