                                        Cookie flowCookie,
                                        String tenantId,
                                        String redirectTo) {
    clearCookie(response, flowCookie.getName());
    String path = "/oauth/continue?tenantId=" +
            encode(tenantId, UTF_8);
    // TODO: Add redirectTo support for local debugging
    foundAtRoot(response, path);
}

