@Component
@Slf4j
public class DownloadConfigurationLinkResolver {

    private static final String VERSION_PLACEHOLDER = "{version}";


    public String resolve(DownloadConfiguration config, String version) {
        String linkTemplate = config.getLinkTemplate();
        String resolvedLink = resolveLink(linkTemplate, version);
        log.debug("Resolved link template '{}' to '{}'", linkTemplate, resolvedLink);
        return resolvedLink;
    }

    private String resolveLink(String linkTemplate, String version) {
        return linkTemplate.replace(VERSION_PLACEHOLDER, version);
    }

}

public String resolve(DownloadConfiguration config, String version) {
    String linkTemplate = config.getLinkTemplate();
    String resolvedLink = resolveLink(linkTemplate, version);
    log.debug("Resolved link template '{}' to '{}'", linkTemplate, resolvedLink);
    return resolvedLink;
}

private String resolveLink(String linkTemplate, String version) {
    return linkTemplate.replace(VERSION_PLACEHOLDER, version);
}

public interface MachineTagEventService {

    /**
     * Processes machine save event.
     * Fetches all tags for the machine and sends MachinePinotMessage.
     *
     * @param machine the machine entity that was saved
     */
    void processMachineSave(Machine machine);

    /**
     * Processes machine saveAll event.
     * Processes each machine in the collection and sends MachinePinotMessage for each.
     *
     * @param machines the collection of machine entities that were saved
     */
    void processMachineSaveAll(Iterable<Machine> machines);

    /**
     * Processes machineTag save event.
     * Fetches associated machine and tag data, then sends MachinePinotMessage.
     *
     * @param machineTag the machineTag entity that was saved
     */
    void processMachineTagSave(MachineTag machineTag);

    /**
     * Processes machineTag saveAll event.
     * Processes each machineTag in the collection and sends MachinePinotMessage for each affected machine.
     *
     * @param machineTags the collection of machineTag entities that were saved
     */
    void processMachineTagSaveAll(Iterable<MachineTag> machineTags);

    /**
     * Processes tag save event.
     * Only processes when tag name changes, fetches all affected machines.
     *
     * @param tag the tag entity that was saved
     */
    void processTagSave(Tag tag);

    /**
     * Processes tag saveAll event.
     * Processes each tag in the collection and sends MachinePinotMessage for affected machines.
     *
     * @param tags the collection of tag entities that were saved
     */
    void processTagSaveAll(Iterable<Tag> tags);
}

@Service
@RequiredArgsConstructor
@Slf4j
@ConditionalOnProperty("spring.cloud.stream.enabled")
public class OpenFrameClientUpdatePublisher {

    private final static String TOPIC_NAME = "machine.all.client-update";

    @Value("${openframe.client.update.feature.enabled:false}")
    private boolean clientUpdateFeatureEnabled;

    private final NatsMessagePublisher natsMessagePublisher;
    private final DownloadConfigurationMapper downloadConfigurationMapper;

    public void publish(OpenFrameClientConfiguration configuration) {
        if (!clientUpdateFeatureEnabled) {
            log.info("Client update publishing is disabled, skipping publish for version: {}", configuration.getVersion());
            return;
        }

        OpenFrameClientUpdateMessage message = buildMessage(configuration);
        natsMessagePublisher.publish(TOPIC_NAME, message);
        log.info("Published client update message for all machines with version: {}", configuration.getVersion());
    }

    private OpenFrameClientUpdateMessage buildMessage(OpenFrameClientConfiguration configuration) {
        OpenFrameClientUpdateMessage message = new OpenFrameClientUpdateMessage();
        message.setVersion(configuration.getVersion());
        message.setDownloadConfigurations(
                downloadConfigurationMapper.map(configuration.getDownloadConfiguration(), configuration.getVersion())
        );
        return message;
    }
}

private OpenFrameClientUpdateMessage buildMessage(OpenFrameClientConfiguration configuration) {
    OpenFrameClientUpdateMessage message = new OpenFrameClientUpdateMessage();
    message.setVersion(configuration.getVersion());
    message.setDownloadConfigurations(
            downloadConfigurationMapper.map(configuration.getDownloadConfiguration(), configuration.getVersion())
    );
    return message;
}

public void publish(OpenFrameClientConfiguration configuration) {
    if (!clientUpdateFeatureEnabled) {
        log.info("Client update publishing is disabled, skipping publish for version: {}", configuration.getVersion());
        return;
    }

    OpenFrameClientUpdateMessage message = buildMessage(configuration);
    natsMessagePublisher.publish(TOPIC_NAME, message);
    log.info("Published client update message for all machines with version: {}", configuration.getVersion());
}

@Service
@RequiredArgsConstructor
@Slf4j
@ConditionalOnProperty("spring.cloud.stream.enabled")
public class ToolAgentUpdateUpdatePublisher {

    private final static String TOPIC_NAME_TEMPLATE = "machine.all.tool.%s.update";

    @Value("${openframe.tool-agent.update.feature.enabled:false}")
    private boolean toolAgentUpdateFeatureEnabled;

    private final NatsMessagePublisher natsMessagePublisher;
    private final DownloadConfigurationMapper downloadConfigurationMapper;

    public void publish(IntegratedToolAgent toolAgent) {
        if (!toolAgentUpdateFeatureEnabled) {
            log.info("Tool agent update publishing is disabled, skipping publish for tool: {} version: {}", toolAgent.getId(), toolAgent.getVersion());
            return;
        }

        String topicName = buildTopicName(toolAgent);
        ToolAgentUpdateMessage message = buildMessage(toolAgent);
        natsMessagePublisher.publish(topicName, message);
        log.info("Published tool update message for tool: {} version: {}", toolAgent.getId(), toolAgent.getVersion());
    }

    private String buildTopicName(IntegratedToolAgent toolAgent) {
        String toolAgentId = toolAgent.getId();
        return format(TOPIC_NAME_TEMPLATE, toolAgentId);
    }

    private ToolAgentUpdateMessage buildMessage(IntegratedToolAgent toolAgent) {
        ToolAgentUpdateMessage message = new ToolAgentUpdateMessage();
        message.setToolAgentId(toolAgent.getId());
        message.setVersion(toolAgent.getVersion());
        message.setSessionType(toolAgent.getSessionType());
        message.setDownloadConfigurations(
                downloadConfigurationMapper.map(toolAgent.getDownloadConfigurations(), toolAgent.getVersion())
        );
        return message;
    }
}

