function getChatTypeMessageType(chatType: ChatType): NatsMessageType {
  return chatType === CHAT_TYPE.ADMIN ? 'admin-message' : 'message'
}

function makeSeqKey(messageType: NatsMessageType, sequenceId: number): string {
  return `${messageType}:${sequenceId}`
}

function useChunkCatchup({
  dialogId,
  onChunkReceived,
  chatTypes = [CHAT_TYPE.CLIENT],
  fetchChunks,
}: UseChunkCatchupOptions): UseChunkCatchupReturn {
  const processedSequenceKeys = useRef<Set<string>>(new Set())
  const lastSequenceId = useRef<number | null>(null)

  const fetchingInProgress = useRef(false)
  const lastFetchParams = useRef<{ dialogId: string; fromSequenceId?: number | null } | null>(null)

  // Buffer for NATS chunks that arrive during catchup
  const chunkBuffer = useRef<BufferedChunk[]>([])
  const bufferUntilInitialCatchupComplete = useRef(false)
  const hasCompletedInitialCatchup = useRef(false)

  const onChunkReceivedRef = useRef(onChunkReceived)
  useEffect(() => {
    onChunkReceivedRef.current = onChunkReceived
  }, [onChunkReceived])

  /**
   * Process a chunk, optionally buffering it if catchup is in progress
   */
  const processChunk = useCallback((
    chunk: ChunkData,
    messageType: NatsMessageType,
    forceProcess: boolean = false
  ): boolean => {
    if (bufferUntilInitialCatchupComplete.current && !forceProcess) {
      chunkBuffer.current.push({ chunk, messageType })
      return true
    }

    if (chunk.sequenceId !== undefined && chunk.sequenceId !== null) {
      lastSequenceId.current = chunk.sequenceId
    }

    // Don't check for duplicates here - let all chunks through
    // Deduplication only happens during catchup merge
    onChunkReceivedRef.current(chunk, messageType)
    return true
  }, [])

  /**
   * Flush buffered realtime chunks after catchup is complete
   */
  const flushBufferedRealtimeChunks = useCallback(() => {
    if (chunkBuffer.current.length === 0) return
    const buffered = [...chunkBuffer.current]
    chunkBuffer.current = []

    buffered.sort((a, b) => {
      const seqA = a.chunk.sequenceId ?? 0
      const seqB = b.chunk.sequenceId ?? 0
      return seqA - seqB
    })

    buffered.forEach(({ chunk, messageType }) => {
      processChunk(chunk, messageType, true)
    })
  }, [processChunk])

  /**
   * Fetch and process chunks from the API
   */
  const catchUpChunks = useCallback(async (fromSequenceId?: number | null) => {
    if (!dialogId) {
      return
    }

    if (hasCompletedInitialCatchup.current) {
      return
    }

    if (fetchingInProgress.current) {
      return
    }

    if (lastFetchParams.current &&
        lastFetchParams.current.dialogId === dialogId &&
        lastFetchParams.current.fromSequenceId === fromSequenceId) {
      return
    }

    if (!fetchChunks) {
      bufferUntilInitialCatchupComplete.current = false
      hasCompletedInitialCatchup.current = true
      flushBufferedRealtimeChunks()
      return
    }

    fetchingInProgress.current = true
    lastFetchParams.current = { dialogId, fromSequenceId }

    try {
      // Fetch chunks for all configured chat types
      const chunkPromises = chatTypes.map(async (chatType) => {
        try {
          const chunks = await fetchChunks(dialogId, chatType, fromSequenceId)
          const messageType = getChatTypeMessageType(chatType)
          return chunks.map(chunk => ({ chunk, messageType }))
        } catch (error) {
          console.error(`Failed to fetch ${chatType} chunks:`, error)
          return []
        }
      })

      const allChunkResults = await Promise.all(chunkPromises)
      const allCatchupChunks: BufferedChunk[] = allChunkResults.flat()

      if (allCatchupChunks.length === 0) {
        flushBufferedRealtimeChunks()
        bufferUntilInitialCatchupComplete.current = false
        hasCompletedInitialCatchup.current = true
        return
      }

      // Combine catchup chunks with buffered NATS chunks
      const bufferedNatsChunks = [...chunkBuffer.current]
      chunkBuffer.current = []
      const allChunks = [...allCatchupChunks, ...bufferedNatsChunks]

      // Sort by sequence ID
      allChunks.sort((a, b) => {
        const seqA = a.chunk.sequenceId ?? 0
        const seqB = b.chunk.sequenceId ?? 0
        return seqA - seqB
      })

      // Deduplicate
      const uniqueAllChunks: BufferedChunk[] = []
      const seenInBatch = new Set<string>()
      for (const item of allChunks) {
        const k = makeBatchDedupKey(item)
        if (seenInBatch.has(k)) continue
        seenInBatch.add(k)
        uniqueAllChunks.push(item)
      }

      // Find last complete message boundary
      let lastMessageStartSeqId: number | null = null
      let lastMessageEndSeqId: number | null = null

      for (let i = uniqueAllChunks.length - 1; i >= 0; i--) {
        const seq = uniqueAllChunks[i].chunk.sequenceId
        if (uniqueAllChunks[i].chunk.type === MESSAGE_TYPE.MESSAGE_END && seq !== undefined && seq !== null) {
          lastMessageEndSeqId = seq
          break
        }
      }

      for (let i = uniqueAllChunks.length - 1; i >= 0; i--) {
        const chunk = uniqueAllChunks[i].chunk
        const seq = chunk.sequenceId
        if (chunk.type === MESSAGE_TYPE.MESSAGE_START && seq !== undefined && seq !== null) {
          if (lastMessageEndSeqId === null || seq > lastMessageEndSeqId) {
            lastMessageStartSeqId = seq
            break
          }
        }
      }

      let chunksToProcess: BufferedChunk[]

      if (lastMessageStartSeqId !== null) {
        // Process from the last incomplete message
        chunksToProcess = uniqueAllChunks.filter(item => 
          item.chunk.sequenceId !== undefined && 
          item.chunk.sequenceId >= lastMessageStartSeqId!
        )
      } else if (lastMessageEndSeqId !== null) {
        // Process only after the last complete message
        chunksToProcess = uniqueAllChunks.filter(item => 
          item.chunk.sequenceId !== undefined && 
          item.chunk.sequenceId > lastMessageEndSeqId!
        )
      } else {
        // Process all
        chunksToProcess = uniqueAllChunks
      }

      // Process the chunks
      chunksToProcess.forEach(({ chunk, messageType }) => {
        if (chunk.sequenceId !== undefined && chunk.sequenceId !== null) {
          processedSequenceKeys.current.add(makeSeqKey(messageType, chunk.sequenceId))
          lastSequenceId.current = chunk.sequenceId
        }
        onChunkReceivedRef.current(chunk, messageType)
      })

      bufferUntilInitialCatchupComplete.current = false
      hasCompletedInitialCatchup.current = true
    } catch (error) {
      console.error('Error during chunk catchup:', error)
    } finally {
      fetchingInProgress.current = false

      if (bufferUntilInitialCatchupComplete.current) {
        bufferUntilInitialCatchupComplete.current = false
        hasCompletedInitialCatchup.current = true
        flushBufferedRealtimeChunks()
      }
    }
  }, [dialogId, chatTypes, fetchChunks, flushBufferedRealtimeChunks])

  /**
   * Reset all tracking state
   */
  const resetChunkTracking = useCallback(() => {
    processedSequenceKeys.current.clear()
    lastSequenceId.current = null
    fetchingInProgress.current = false
    lastFetchParams.current = null
    chunkBuffer.current = []
    bufferUntilInitialCatchupComplete.current = false
    hasCompletedInitialCatchup.current = false
  }, [])

  /**
   * Start buffering NATS chunks for initial catchup
   */
  const startInitialBuffering = useCallback(() => {
    chunkBuffer.current = []
    bufferUntilInitialCatchupComplete.current = true
    hasCompletedInitialCatchup.current = false
  }, [])

  /**
   * Check if buffering is currently active
   */
  const isBufferingActive = useCallback(() => bufferUntilInitialCatchupComplete.current, [])

  return {
    catchUpChunks,
    processChunk,
    resetChunkTracking,
    startInitialBuffering,
    isBufferingActive,
    processedCount: processedSequenceKeys.current.size
  }
}

function buildNatsWsUrl(
  apiBaseUrl: string,
  options?: {
    token?: string
    includeAuthParam?: boolean
  }
): string {
  const u = new URL('/ws/nats', apiBaseUrl)
  u.protocol = u.protocol === 'https:' ? 'wss:' : 'ws:'

  if (options?.includeAuthParam && options?.token) {
    u.searchParams.set('authorization', options.token)
  }

  return u.toString()
}

function useNatsDialogSubscription({
  enabled,
  dialogId,
  topics = ['message'],
  onEvent,
  onConnect,
  onDisconnect,
  onSubscribed,
  getNatsWsUrl,
  clientConfig = {},
}: UseNatsDialogSubscriptionOptions): UseNatsDialogSubscriptionReturn {
  const [isConnected, setIsConnected] = useState(false)
  const [isSubscribed, setIsSubscribed] = useState(false)

  const clientRef = useRef<NatsClient | null>(null)
  const subscriptionRefs = useRef<Map<NatsMessageType, NatsSubscriptionHandle | null>>(new Map())

  // Stable refs for callbacks
  const onEventRef = useRef(onEvent)
  useEffect(() => {
    onEventRef.current = onEvent
  }, [onEvent])

  const onConnectRef = useRef(onConnect)
  useEffect(() => {
    onConnectRef.current = onConnect
  }, [onConnect])

  const onDisconnectRef = useRef(onDisconnect)
  useEffect(() => {
    onDisconnectRef.current = onDisconnect
  }, [onDisconnect])

  const onSubscribedRef = useRef(onSubscribed)
  useEffect(() => {
    onSubscribedRef.current = onSubscribed
  }, [onSubscribed])

  const acquireClient = useCallback((url: string): SharedConnection => {
    if (shared?.wsUrl !== url) {
      // Close existing connection if URL changed
      if (shared) {
        shared.closeTimer && clearTimeout(shared.closeTimer)
        const old = shared
        shared = null
        void old.client.close().catch(() => {})
      }

      const { name = 'openframe-frontend', user = 'machine', pass = '' } = clientConfig

      const client = createNatsClient({
        servers: url,
        name,
        user,
        pass,
        connectTimeoutMs: NETWORK_CONFIG.CONNECT_TIMEOUT_MS,
        reconnect: true,
        maxReconnectAttempts: -1, // Unlimited reconnection attempts
        reconnectTimeWaitMs: NETWORK_CONFIG.RECONNECT_TIME_WAIT_MS,
        pingIntervalMs: NETWORK_CONFIG.PING_INTERVAL_MS,
        maxPingOut: NETWORK_CONFIG.MAX_PING_OUT,
      })
      shared = { wsUrl: url, client, connectPromise: null, refCount: 0, closeTimer: null }
    }

    shared.refCount += 1
    shared.closeTimer && clearTimeout(shared.closeTimer)
    shared.closeTimer = null
    return shared
  }, [clientConfig])

  const releaseClient = useCallback((url: string) => {
    if (!shared || shared.wsUrl !== url) return

    shared.refCount = Math.max(0, shared.refCount - 1)
    if (shared.refCount > 0) return

    shared.closeTimer = setTimeout(() => {
      const s = shared
      shared = null
      s && void s.client.close().catch(() => {})
    }, NETWORK_CONFIG.SHARED_CLOSE_DELAY_MS)
  }, [])

  // Store the current WebSocket URL to prevent unnecessary reconnections
  const currentWsUrlRef = useRef<string>('')

  // Connection effect
  useEffect(() => {
    const wsUrl = getNatsWsUrl()
    if (!enabled || !wsUrl) {
      // Clean up if disabled or no URL
      if (currentWsUrlRef.current && clientRef.current) {
        releaseClient(currentWsUrlRef.current)
        clientRef.current = null
        currentWsUrlRef.current = ''
        setIsConnected(false)
      }
      return
    }

    // Skip if we're already connected to the same URL
    if (wsUrl === currentWsUrlRef.current && clientRef.current && clientRef.current.isConnected()) {
      return
    }

    // Clean up existing connection if URL changed
    if (currentWsUrlRef.current && currentWsUrlRef.current !== wsUrl && clientRef.current) {
      releaseClient(currentWsUrlRef.current)
      clientRef.current = null
      setIsConnected(false)
    }

    currentWsUrlRef.current = wsUrl
    const sharedConn = acquireClient(wsUrl)
    const client = sharedConn.client

    clientRef.current = client
    setIsConnected(false)

    let hasConnected = false

    const unsubscribeStatus = client.onStatus((event) => {
      const connected = event.status === 'connected'
      const disconnected = ['closed', 'disconnected', 'error'].includes(event.status)
      if (connected) {
        setIsConnected(true)
        if (!hasConnected) {
          hasConnected = true
          onConnectRef.current?.()
        }
      }
      if (disconnected) {
        setIsConnected(false)
        hasConnected = false
        onDisconnectRef.current?.()
      }
    })

    let closed = false
    ;(async () => {
      try {
        sharedConn.connectPromise ||= client.connect()
        await sharedConn.connectPromise
        if (!closed) {
          setIsConnected(true)
        }
      } catch (e) {
        sharedConn.connectPromise = null
        setIsConnected(false)
        onDisconnectRef.current?.()
        await client.close().catch(() => {})
      }
    })()

    return () => {
      closed = true
      setIsConnected(false)
      unsubscribeStatus()

      // Unsubscribe all subscriptions
      subscriptionRefs.current.forEach((sub) => {
        try {
          sub?.unsubscribe()
        } catch {
          // ignore
        }
      })
      subscriptionRefs.current.clear()

      if (clientRef.current && currentWsUrlRef.current) {
        releaseClient(currentWsUrlRef.current)
        clientRef.current = null
        currentWsUrlRef.current = ''
      }
    }
  }, [enabled, getNatsWsUrl, acquireClient, releaseClient])

  const topicsKey = topics.join(',')
  const lastSubscribedDialogIdRef = useRef<string | null>(null)
  const isConnectedRef = useRef(isConnected)

  useEffect(() => {
    isConnectedRef.current = isConnected
  }, [isConnected])

  // Track subscription state separately from dialog changes
  const currentDialogIdRef = useRef<string | null>(null)
  const abortControllerRef = useRef<AbortController | null>(null)

  // Handle dialog changes and subscription lifecycle
  useEffect(() => {
    currentDialogIdRef.current = dialogId

    if (!enabled || !dialogId) {
      // Clean up if disabled or no dialog
      if (subscriptionRefs.current.size > 0) {
        setIsSubscribed(false)
        subscriptionRefs.current.forEach((sub) => {
          try {
            sub?.unsubscribe()
          } catch {
            // ignore
          }
        })
        subscriptionRefs.current.clear()
        lastSubscribedDialogIdRef.current = null
        abortControllerRef.current?.abort()
        abortControllerRef.current = null
      }
      return
    }

    const needsNewSubscription = 
      lastSubscribedDialogIdRef.current !== dialogId || 
      subscriptionRefs.current.size === 0

    if (!needsNewSubscription) {
      return
    }

    // Clean up any existing subscriptions before creating new ones
    if (subscriptionRefs.current.size > 0) {
      subscriptionRefs.current.forEach((sub) => {
        try {
          sub?.unsubscribe()
        } catch {
          // ignore
        }
      })
      subscriptionRefs.current.clear()
      abortControllerRef.current?.abort()
    }

    // Create new abort controller for this subscription set
    abortControllerRef.current = new AbortController()
    const abort = abortControllerRef.current

    const createSubscriptions = () => {
      if (!isConnectedRef.current) {
        return
      }

      const client = clientRef.current
      if (!client || currentDialogIdRef.current !== dialogId) {
        return
      }

      const decoder = new TextDecoder()

      const handleMessage = (messageType: NatsMessageType) => async (msg: any) => {
        if (!onEventRef.current) return
        try {
          const dataStr = decoder.decode(msg.data)
          const parsed = JSON.parse(dataStr)
          onEventRef.current(parsed, messageType)
        } catch {
          // Ignore parse errors
        }
      }

      // Subscribe to all configured topics
      topics.forEach((topic) => {
        const subscription = client.subscribeBytes(
          `chat.${dialogId}.${topic}`,
          handleMessage(topic),
          { signal: abort.signal }
        )
        subscriptionRefs.current.set(topic, subscription)
      })

      lastSubscribedDialogIdRef.current = dialogId
      setIsSubscribed(true)
      onSubscribedRef.current?.()
    }

    if (isConnectedRef.current) {
      createSubscriptions()
    }

    return () => {
      setIsSubscribed(false)
      abort.abort()
      subscriptionRefs.current.forEach((sub) => {
        try {
          sub?.unsubscribe()
        } catch {
          // ignore
        }
      })
      subscriptionRefs.current.clear()
      lastSubscribedDialogIdRef.current = null
      abortControllerRef.current = null
    }
  }, [enabled, dialogId, topicsKey, topics])

  // Separate effect to handle connection state changes
  useEffect(() => {
    if (!enabled || !currentDialogIdRef.current || !isConnected) {
      return
    }

    if (subscriptionRefs.current.size === 0 && lastSubscribedDialogIdRef.current !== currentDialogIdRef.current) {
      const client = clientRef.current
      if (!client) return

      const dialogId = currentDialogIdRef.current
      const decoder = new TextDecoder()

      const abort = abortControllerRef.current || new AbortController()
      if (!abortControllerRef.current) {
        abortControllerRef.current = abort
      }

      const handleMessage = (messageType: NatsMessageType) => async (msg: any) => {
        if (!onEventRef.current) return
        try {
          const dataStr = decoder.decode(msg.data)
          const parsed = JSON.parse(dataStr)
          onEventRef.current(parsed, messageType)
        } catch {
          // Ignore parse errors
        }
      }

      // Subscribe to all configured topics
      topics.forEach((topic) => {
        const subscription = client.subscribeBytes(
          `chat.${dialogId}.${topic}`,
          handleMessage(topic),
          { signal: abort.signal }
        )
        subscriptionRefs.current.set(topic, subscription)
      })

      lastSubscribedDialogIdRef.current = dialogId
      setIsSubscribed(true)
      onSubscribedRef.current?.()
    } else if (subscriptionRefs.current.size > 0) {
      // We have subscriptions, just update the state
      setIsSubscribed(true)
    }
  }, [isConnected, enabled, topics, topicsKey])

  return { isConnected, isSubscribed }
}

function useRealtimeChunkProcessor(
  options: UseRealtimeChunkProcessorOptions
): UseRealtimeChunkProcessorReturn {
  const { callbacks, displayApprovalTypes = ['CLIENT'], approvalStatuses = {}, initialState } = options

  const accumulatorRef = useRef<MessageSegmentAccumulator>(
    createMessageSegmentAccumulator({
      onApprove: callbacks.onApprove,
      onReject: callbacks.onReject,
    })
  )

  const hasInitializedWithData = useRef(false)

  // Initialize accumulator when we get initial state data
  useEffect(() => {
    if (initialState && !hasInitializedWithData.current) {
      accumulatorRef.current.initializeWithState(initialState)

      if (initialState.escalatedApprovals) {
        pendingEscalatedRef.current = new Map(initialState.escalatedApprovals)

        initialState.escalatedApprovals.forEach((data, requestId) => {
          callbacks.onEscalatedApproval?.(requestId, data)
        })
      }

      hasInitializedWithData.current = true
    }
  }, [initialState, callbacks])

  // Track pending escalated approvals
  const pendingEscalatedRef = useRef<Map<string, { command: string; explanation?: string; approvalType: string }>>(
    new Map()
  )

  const processChunk = useCallback(
    (chunk: unknown) => {
      const action = parseChunkToAction(chunk)
      if (!action) return

      const accumulator = accumulatorRef.current

      switch (action.action) {
        case 'message_start':
          callbacks.onStreamStart?.()
          // Reset accumulator for new message
          accumulator.resetSegments()
          break

        case 'message_end':
          callbacks.onStreamEnd?.()
          break

        case 'metadata':
          callbacks.onMetadata?.(action)
          break

        case 'text': {
          const segments = accumulator.appendText(action.text)
          callbacks.onSegmentsUpdate?.(segments)
          break
        }

        case 'tool_execution': {
          const segments = accumulator.addToolExecution(action.segment)
          callbacks.onSegmentsUpdate?.(segments)
          break
        }

        case 'approval_request': {
          const { requestId, command, explanation, approvalType } = action

          if (displayApprovalTypes.includes(approvalType)) {
            // Display directly
            const status = approvalStatuses[requestId] || 'pending'
            const segments = accumulator.addApprovalRequest(
              requestId,
              command,
              explanation,
              approvalType,
              status as ChatApprovalStatus
            )
            callbacks.onSegmentsUpdate?.(segments)
          } else {
            // Track as escalated
            pendingEscalatedRef.current.set(requestId, { command, explanation, approvalType })
            callbacks.onEscalatedApproval?.(requestId, { command, explanation, approvalType })
          }
          break
        }

        case 'approval_result': {
          const { requestId, approved, approvalType } = action
          const escalatedData = pendingEscalatedRef.current.get(requestId)
          if (escalatedData) {
            pendingEscalatedRef.current.delete(requestId)
            callbacks.onEscalatedApprovalResult?.(requestId, approved, escalatedData)

            const segments = accumulator.addApprovalRequest(
              requestId,
              escalatedData.command,
              escalatedData.explanation,
              escalatedData.approvalType,
              approved ? 'approved' : 'rejected'
            )
            callbacks.onSegmentsUpdate?.(segments)
          } else {
            const segments = accumulator.updateApprovalStatus(
              requestId,
              approved ? 'approved' : 'rejected'
            )
            callbacks.onSegmentsUpdate?.(segments)
          }
          break
        }

        case 'error':
          callbacks.onError?.(action.error, action.details)
          // Reset accumulator on error
          accumulator.resetSegments()
          break

        case 'message_request':
          callbacks.onUserMessage?.(action.text)
          break

        default:
          // Unknown action - ignore
          break
      }
    },
    [callbacks, displayApprovalTypes, approvalStatuses, initialState]
  )

  const getSegments = useCallback(() => {
    return accumulatorRef.current.getSegments()
  }, [])

  const reset = useCallback(() => {
    accumulatorRef.current.reset()
    pendingEscalatedRef.current.clear()
    hasInitializedWithData.current = false
  }, [])

  const updateApprovalStatus = useCallback(
    (requestId: string, status: ChatApprovalStatus) => {
      return accumulatorRef.current.updateApprovalStatus(requestId, status)
    },
    []
  )

  const getPendingApprovals = useCallback(() => {
    return new Map(pendingEscalatedRef.current)
  }, [])

  return {
    processChunk,
    getSegments,
    reset,
    updateApprovalStatus,
    getPendingApprovals,
  }
}

