function extractTextFromChunk(chunk: unknown): string | null {
  if (!chunk || typeof chunk !== 'object') return null
  const data = chunk as ChunkData
  if (data.type === MESSAGE_TYPE.TEXT && typeof data.text === 'string') {
    return data.text
  }
  return null
}

function isControlChunk(chunk: unknown): boolean {
  if (!chunk || typeof chunk !== 'object') return false
  const data = chunk as ChunkData
  const type = String(data.type || '')
  return type === MESSAGE_TYPE.MESSAGE_START || type === MESSAGE_TYPE.MESSAGE_END
}

function isErrorChunk(chunk: unknown): boolean {
  if (!chunk || typeof chunk !== 'object') return false
  const data = chunk as ChunkData
  return data.type === MESSAGE_TYPE.ERROR
}

function isMetadataChunk(chunk: unknown): boolean {
  if (!chunk || typeof chunk !== 'object') return false
  const data = chunk as ChunkData
  return data.type === MESSAGE_TYPE.AI_METADATA
}

function parseChunkToAction(chunk: unknown): ParsedChunkAction | null {
  if (!chunk || typeof chunk !== 'object') return null

  const data = chunk as ChunkData
  const type = String(data.type || '')

  switch (type) {
    case MESSAGE_TYPE.MESSAGE_START:
      return { action: 'message_start' }

    case MESSAGE_TYPE.MESSAGE_END:
      return { action: 'message_end' }

    case MESSAGE_TYPE.AI_METADATA: {
      const providerName = data.providerName || data.provider
      if (typeof data.modelName === 'string' && typeof providerName === 'string') {
        return {
          action: 'metadata',
          modelName: data.modelName,
          providerName,
          contextWindow: typeof data.contextWindow === 'number' ? data.contextWindow : 0,
        }
      }
      return null
    }

    case MESSAGE_TYPE.TEXT:
      if (typeof data.text === 'string') {
        return { action: 'text', text: data.text }
      }
      return null

    case MESSAGE_TYPE.EXECUTING_TOOL:
      return {
        action: 'tool_execution',
        segment: {
          type: 'tool_execution',
          data: {
            type: 'EXECUTING_TOOL',
            integratedToolType: data.integratedToolType || '',
            toolFunction: data.toolFunction || '',
            parameters: data.parameters,
          }
        }
      }

    case MESSAGE_TYPE.EXECUTED_TOOL:
      return {
        action: 'tool_execution',
        segment: {
          type: 'tool_execution',
          data: {
            type: 'EXECUTED_TOOL',
            integratedToolType: data.integratedToolType || '',
            toolFunction: data.toolFunction || '',
            parameters: data.parameters,
            result: data.result,
            success: data.success,
          }
        }
      }

    case MESSAGE_TYPE.APPROVAL_REQUEST:
      return {
        action: 'approval_request',
        requestId: data.approvalRequestId || data.approval_request_id || '',
        command: data.command || '',
        explanation: data.explanation,
        approvalType: data.approvalType || 'USER',
      }

    case MESSAGE_TYPE.APPROVAL_RESULT:
      return {
        action: 'approval_result',
        requestId: data.approvalRequestId || data.approval_request_id || '',
        approved: data.approved === true,
        approvalType: data.approvalType || 'CLIENT',
      }

    case MESSAGE_TYPE.ERROR:
      return {
        action: 'error',
        error: data.error || 'An error occurred',
        details: data.details,
      }

    case MESSAGE_TYPE.MESSAGE_REQUEST:
      return {
        action: 'message_request',
        text: String(data.text || ''),
      }

    default:
      return null
  }
}

function extractIncompleteMessageState(
  lastMessage: ProcessedMessage | undefined
): {
  existingSegments?: MessageSegment[]
  pendingApprovals?: Map<string, PendingApproval>
  executingTools?: Map<string, { integratedToolType: string; toolFunction: string; parameters?: Record<string, any> }>
} | undefined {
  if (!lastMessage || lastMessage.role !== 'assistant' || typeof lastMessage.content === 'string') {
    return undefined
  }

  const segments = lastMessage.content as MessageSegment[]
  const pendingApprovals = new Map<string, PendingApproval>()
  const executingTools = new Map<string, { integratedToolType: string; toolFunction: string; parameters?: Record<string, any> }>()
  let hasIncompleteState = false

  segments.forEach(segment => {
    switch (segment.type) {
      case 'tool_execution':
        if (segment.data.type === 'EXECUTING_TOOL') {
          const toolKey = `${segment.data.integratedToolType}-${segment.data.toolFunction}`
          executingTools.set(toolKey, {
            integratedToolType: segment.data.integratedToolType,
            toolFunction: segment.data.toolFunction,
            parameters: segment.data.parameters,
          })
          hasIncompleteState = true
        }
        break

      case 'approval_request':
        if (segment.status === 'pending' && segment.data.requestId) {
          pendingApprovals.set(segment.data.requestId, {
            command: segment.data.command,
            explanation: segment.data.explanation,
            approvalType: segment.data.approvalType || 'CLIENT',
          })
          hasIncompleteState = true
        }
        break
    }
  })

  if (!hasIncompleteState) {
    return undefined
  }

  return {
    existingSegments: segments,
    pendingApprovals: pendingApprovals.size > 0 ? pendingApprovals : undefined,
    executingTools: executingTools.size > 0 ? executingTools : undefined,
  }
}

interface AccumulatorCallbacks {
  onApprove?: (requestId?: string) => Promise<void> | void
  onReject?: (requestId?: string) => Promise<void> | void
}

class MessageSegmentAccumulator {
  private segments: MessageSegment[] = []
  private currentTextBuffer: string = ''
  private pendingApprovals: Map<string, PendingApproval> = new Map()
  private executingTools: Map<string, { integratedToolType: string; toolFunction: string; parameters?: Record<string, any> }> = new Map()
  private callbacks: AccumulatorCallbacks = {}

  constructor(callbacks?: AccumulatorCallbacks) {
    if (callbacks) {
      this.callbacks = callbacks
    }
  }

  /**
   * Set callbacks for approval actions
   */
  setCallbacks(callbacks: AccumulatorCallbacks): void {
    this.callbacks = callbacks
  }

  /**
   * Initialize accumulator with existing state from an incomplete historical message
   * Used to continue building messages across page refreshes or reconnections
   */
  initializeWithState(state: {
    existingSegments?: MessageSegment[]
    pendingApprovals?: Map<string, PendingApproval>
    executingTools?: Map<string, { integratedToolType: string; toolFunction: string; parameters?: Record<string, any> }>
  }): void {
    if (state.existingSegments) {
      this.segments = [...state.existingSegments]

      const lastSegment = this.segments[this.segments.length - 1]
      if (lastSegment && lastSegment.type === 'text') {
        this.currentTextBuffer = lastSegment.text
      } else {
        this.currentTextBuffer = ''
      }
    }

    if (state.pendingApprovals) {
      this.pendingApprovals = new Map(state.pendingApprovals)
    }

    if (state.executingTools) {
      this.executingTools = new Map(state.executingTools)
    }
  }

  /**
   * Get current segments
   */
  getSegments(): MessageSegment[] {
    return [...this.segments]
  }

  /**
   * Get the state of the accumulator for serialization
   */
  getState(): AccumulatorState {
    return {
      segments: [...this.segments],
      currentTextBuffer: this.currentTextBuffer,
      pendingApprovals: new Map(this.pendingApprovals),
      executingTools: new Map(this.executingTools),
    }
  }

  /**
   * Reset the accumulator to initial state
   */
  reset(): void {
    this.segments = []
    this.currentTextBuffer = ''
    this.pendingApprovals.clear()
    this.executingTools.clear()
  }

  /**
   * Reset only segments (keep pending state for continued processing)
   */
  resetSegments(): void {
    this.segments = []
    this.currentTextBuffer = ''
  }

  /**
   * Append text to the current message
   * If the last segment is text, append to it; otherwise create a new text segment
   */
  appendText(text: string): MessageSegment[] {
    const lastSegment = this.segments[this.segments.length - 1]

    if (lastSegment && lastSegment.type === 'text') {
      this.currentTextBuffer += text
      this.segments[this.segments.length - 1] = { type: 'text', text: this.currentTextBuffer }
    } else {
      this.currentTextBuffer = text
      this.segments.push({ type: 'text', text: this.currentTextBuffer })
    }

    return this.getSegments()
  }

  /**
   * Add a tool execution segment
   * If adding EXECUTED_TOOL, replace the matching EXECUTING_TOOL
   */
  addToolExecution(segment: ToolExecutionSegment): MessageSegment[] {
    const toolData = segment.data
    const toolKey = `${toolData.integratedToolType}-${toolData.toolFunction}`

    if (toolData.type === 'EXECUTING_TOOL') {
      this.executingTools.set(toolKey, {
        integratedToolType: toolData.integratedToolType,
        toolFunction: toolData.toolFunction,
        parameters: toolData.parameters,
      })
      this.segments.push(segment)
    } else if (toolData.type === 'EXECUTED_TOOL') {
      const existingIndex = this.segments.findIndex(
        (s): s is ToolExecutionSegment =>
          s.type === 'tool_execution' &&
          s.data.type === 'EXECUTING_TOOL' &&
          s.data.integratedToolType === toolData.integratedToolType &&
          s.data.toolFunction === toolData.toolFunction
      )

      const executingTool = this.executingTools.get(toolKey)
      const mergedSegment: ToolExecutionSegment = {
        type: 'tool_execution',
        data: {
          ...toolData,
          parameters: toolData.parameters || executingTool?.parameters,
        }
      }

      if (existingIndex !== -1) {
        this.segments[existingIndex] = mergedSegment
      } else {
        this.segments.push(mergedSegment)
      }

      this.executingTools.delete(toolKey)
    }

    return this.getSegments()
  }

  /**
   * Track a pending approval request
   */
  trackApprovalRequest(requestId: string, data: PendingApproval): void {
    this.pendingApprovals.set(requestId, data)
  }

  /**
   * Add an approval request segment directly (for CLIENT approvals)
   */
  addApprovalRequest(
    requestId: string,
    command: string,
    explanation: string | undefined,
    approvalType: string,
    status: ChatApprovalStatus = 'pending'
  ): MessageSegment[] {
    const segment: ApprovalRequestSegment = {
      type: 'approval_request',
      data: {
        command,
        explanation,
        requestId,
        approvalType,
      },
      status,
      onApprove: this.callbacks.onApprove,
      onReject: this.callbacks.onReject,
    }

    this.segments.push(segment)
    return this.getSegments()
  }

  /**
   * Process an approval result and create a segment
   * Returns the pending approval data if found
   */
  processApprovalResult(
    requestId: string,
    approved: boolean,
    approvalType: string
  ): { segment: ApprovalRequestSegment; pendingData: PendingApproval | null } | null {
    const pendingApproval = this.pendingApprovals.get(requestId)
    const status: ChatApprovalStatus = approved ? 'approved' : 'rejected'

    const segment: ApprovalRequestSegment = {
      type: 'approval_request',
      data: {
        command: pendingApproval?.command || '',
        explanation: pendingApproval?.explanation,
        requestId,
        approvalType: pendingApproval?.approvalType || approvalType,
      },
      status,
      onApprove: this.callbacks.onApprove,
      onReject: this.callbacks.onReject,
    }

    this.segments.push(segment)

    if (pendingApproval) {
      this.pendingApprovals.delete(requestId)
    }

    return { segment, pendingData: pendingApproval || null }
  }

  /**
   * Update status of an existing approval segment
   */
  updateApprovalStatus(requestId: string, status: ChatApprovalStatus): MessageSegment[] {
    this.segments = this.segments.map(segment => {
      if (segment.type === 'approval_request' && segment.data.requestId === requestId) {
        return { ...segment, status }
      }
      return segment
    })
    return this.getSegments()
  }

  /**
   * Get pending approvals that haven't been resolved
   */
  getPendingApprovals(): Map<string, PendingApproval> {
    return new Map(this.pendingApprovals)
  }

  /**
   * Check if there are any pending approvals
   */
  hasPendingApprovals(): boolean {
    return this.pendingApprovals.size > 0
  }

  /**
   * Create segments for all remaining pending approvals
   */
  flushPendingApprovals(): ApprovalRequestSegment[] {
    const segments: ApprovalRequestSegment[] = []

    this.pendingApprovals.forEach((approval, requestId) => {
      segments.push({
        type: 'approval_request',
        data: {
          command: approval.command,
          explanation: approval.explanation,
          requestId,
          approvalType: approval.approvalType,
        },
        status: 'pending',
        onApprove: this.callbacks.onApprove,
        onReject: this.callbacks.onReject,
      })
    })

    return segments
  }

  /**
   * Check if segments have any content
   */
  hasContent(): boolean {
    return this.segments.length > 0
  }

  /**
   * Get the number of segments
   */
  get length(): number {
    return this.segments.length
  }
}

