      if (existingIndex !== -1) {
        this.segments[existingIndex] = mergedSegment
      } else {
        this.segments.push(mergedSegment)
      }

      this.executingTools.delete(toolKey)
    }

    return this.getSegments()
  }

appendText(text: string): MessageSegment[] {
    const lastSegment = this.segments[this.segments.length - 1]

    if (lastSegment && lastSegment.type === 'text') {
      this.currentTextBuffer += text
      this.segments[this.segments.length - 1] = { type: 'text', text: this.currentTextBuffer }
    } else {
      this.currentTextBuffer = text
      this.segments.push({ type: 'text', text: this.currentTextBuffer })
    }

    return this.getSegments()
  }

function createMessageSegmentAccumulator(callbacks?: AccumulatorCallbacks): MessageSegmentAccumulator {
  return new MessageSegmentAccumulator(callbacks)
}

flushPendingApprovals(): ApprovalRequestSegment[] {
    const segments: ApprovalRequestSegment[] = []

    this.pendingApprovals.forEach((approval, requestId) => {
      segments.push({
        type: 'approval_request',
        data: {
          command: approval.command,
          explanation: approval.explanation,
          requestId,
          approvalType: approval.approvalType,
        },
        status: 'pending',
        onApprove: this.callbacks.onApprove,
        onReject: this.callbacks.onReject,
      })
    })

    return segments
  }

getPendingApprovals(): Map<string, PendingApproval> {
    return new Map(this.pendingApprovals)
  }

getSegments(): MessageSegment[] {
    return [...this.segments]
  }

getState(): AccumulatorState {
    return {
      segments: [...this.segments],
      currentTextBuffer: this.currentTextBuffer,
      pendingApprovals: new Map(this.pendingApprovals),
      executingTools: new Map(this.executingTools),
    }
  }

hasContent(): boolean {
    return this.segments.length > 0
  }

hasPendingApprovals(): boolean {
    return this.pendingApprovals.size > 0
  }

initializeWithState(state: {
    existingSegments?: MessageSegment[]
    pendingApprovals?: Map<string, PendingApproval>
    executingTools?: Map<string, { integratedToolType: string; toolFunction: string; parameters?: Record<string, any> }>
  }): void {
    if (state.existingSegments) {
      this.segments = [...state.existingSegments]

      const lastSegment = this.segments[this.segments.length - 1]
      if (lastSegment && lastSegment.type === 'text') {
        this.currentTextBuffer = lastSegment.text
      } else {
        this.currentTextBuffer = ''
      }
    }

    if (state.pendingApprovals) {
      this.pendingApprovals = new Map(state.pendingApprovals)
    }

    if (state.executingTools) {
      this.executingTools = new Map(state.executingTools)
    }
  }

get length(): number {
    return this.segments.length
  }

processApprovalResult(
    requestId: string,
    approved: boolean,
    approvalType: string
  ): { segment: ApprovalRequestSegment; pendingData: PendingApproval | null } | null {
    const pendingApproval = this.pendingApprovals.get(requestId)
    const status: ChatApprovalStatus = approved ? 'approved' : 'rejected'

    const segment: ApprovalRequestSegment = {
      type: 'approval_request',
      data: {
        command: pendingApproval?.command || '',
        explanation: pendingApproval?.explanation,
        requestId,
        approvalType: pendingApproval?.approvalType || approvalType,
      },
      status,
      onApprove: this.callbacks.onApprove,
      onReject: this.callbacks.onReject,
    }

    this.segments.push(segment)

    if (pendingApproval) {
      this.pendingApprovals.delete(requestId)
    }

    return { segment, pendingData: pendingApproval || null }
  }

reset(): void {
    this.segments = []
    this.currentTextBuffer = ''
    this.pendingApprovals.clear()
    this.executingTools.clear()
  }

resetSegments(): void {
    this.segments = []
    this.currentTextBuffer = ''
  }

setCallbacks(callbacks: AccumulatorCallbacks): void {
    this.callbacks = callbacks
  }

trackApprovalRequest(requestId: string, data: PendingApproval): void {
    this.pendingApprovals.set(requestId, data)
  }

updateApprovalStatus(requestId: string, status: ChatApprovalStatus): MessageSegment[] {
    this.segments = this.segments.map(segment => {
      if (segment.type === 'approval_request' && segment.data.requestId === requestId) {
        return { ...segment, status }
      }
      return segment
    })
    return this.getSegments()
  }

interface ProcessHistoricalMessagesResult {
  messages: ProcessedMessage[]
  escalatedApprovals: Map<string, { command: string; explanation?: string; approvalType: string }>
}

function extractErrorMessages(
  messages: HistoricalMessage[],
  options: MessageProcessingOptions = {}
): ProcessedMessage[] {
  const { assistantName = 'Fae', assistantType = 'fae', assistantAvatar, chatTypeFilter } = options

  const errorMessages: ProcessedMessage[] = []

  messages.forEach((msg) => {
    if (chatTypeFilter && msg.chatType !== chatTypeFilter) return

    const messageDataArray = Array.isArray(msg.messageData)
      ? msg.messageData
      : msg.messageData
      ? [msg.messageData]
      : []

    messageDataArray.forEach((data) => {
      if (data.type === MESSAGE_TYPE.ERROR) {
        errorMessages.push({
          id: `${msg.id}-error`,
          role: 'error',
          content: 'error' in data && data.error ? data.error : 'An error occurred',
          name: assistantName,
          assistantType,
          timestamp: new Date(msg.createdAt),
          avatar: assistantAvatar,
        })
      }
    })
  })

  return errorMessages
}

function processHistoricalMessages(
  messages: HistoricalMessage[],
  options: MessageProcessingOptions = {}
): ProcessHistoricalMessagesResult {
  const {
    assistantName = 'Fae',
    assistantType = 'fae',
    assistantAvatar,
    onApprove,
    onReject,
    chatTypeFilter,
    approvalStatuses = {},
    displayApprovalTypes,
  } = options

  const processedMessages: ProcessedMessage[] = []
  const accumulator = createMessageSegmentAccumulator({ onApprove, onReject })
  const escalatedApprovals = new Map<string, { command: string; explanation?: string; approvalType: string }>()

  let currentAssistantId: string | null = null
  let currentAssistantTimestamp: Date | null = null

  /**
   * Flush the current assistant message to processedMessages
   */
  const flushAssistantMessage = () => {
    if (currentAssistantId && accumulator.hasContent()) {
      processedMessages.push({
        id: currentAssistantId,
        role: 'assistant',
        content: accumulator.getSegments(),
        name: assistantName,
        assistantType,
        timestamp: currentAssistantTimestamp || new Date(),
        avatar: assistantAvatar,
      })
      accumulator.resetSegments()
      currentAssistantId = null
      currentAssistantTimestamp = null
    }
  }

  messages.forEach((msg, index) => {
    // Filter by chat type if specified
    if (chatTypeFilter && msg.chatType !== chatTypeFilter) return

    const messageDataArray = Array.isArray(msg.messageData)
      ? msg.messageData
      : msg.messageData
      ? [msg.messageData]
      : []

    const isUserMessage =
      msg.owner?.type === OWNER_TYPE.CLIENT || msg.owner?.type === OWNER_TYPE.ADMIN

    if (isUserMessage) {
      flushAssistantMessage()

      messageDataArray.forEach((data) => {
        if (data.type === MESSAGE_TYPE.TEXT && 'text' in data && data.text) {
          processedMessages.push({
            id: msg.id,
            role: 'user',
            content: data.text,
            name: msg.owner?.type === OWNER_TYPE.ADMIN ? 'Admin' : 'You',
            timestamp: new Date(msg.createdAt),
          })
        }
      })
    } else {
      if (!currentAssistantId) {
        currentAssistantId = msg.id
        currentAssistantTimestamp = new Date(msg.createdAt)
      }

      messageDataArray.forEach((data) => {
        processMessageData(data, accumulator, approvalStatuses, { displayApprovalTypes }, escalatedApprovals)
      })

      // Check if we should flush (next message is from user or last message)
      const nextMsg = messages[index + 1]
      const isLastMessage = index === messages.length - 1
      const nextIsFromUser =
        nextMsg &&
        (nextMsg.owner?.type === OWNER_TYPE.CLIENT || nextMsg.owner?.type === OWNER_TYPE.ADMIN)

      if (isLastMessage || nextIsFromUser) {
        flushAssistantMessage()
      }
    }
  })

  flushAssistantMessage()

  const pendingApprovalSegments = accumulator.flushPendingApprovals()
  if (pendingApprovalSegments.length > 0) {
    processedMessages.push({
      id: `pending-approvals-${Date.now()}`,
      role: 'assistant',
      content: pendingApprovalSegments,
      name: assistantName,
      assistantType,
      timestamp: new Date(),
      avatar: assistantAvatar,
    })
  }

  return {
    messages: processedMessages,
    escalatedApprovals: escalatedApprovals
  }
}

function processHistoricalMessagesWithErrors(
  messages: HistoricalMessage[],
  options: MessageProcessingOptions = {}
): ProcessHistoricalMessagesResult {
  const { chatTypeFilter, assistantName = 'Fae', assistantType = 'fae', assistantAvatar, onApprove, onReject, approvalStatuses = {}, displayApprovalTypes } = options

  const processedMessages: ProcessedMessage[] = []
  const accumulator = createMessageSegmentAccumulator({ onApprove, onReject })
  const escalatedApprovals = new Map<string, { command: string; explanation?: string; approvalType: string }>()

  let currentAssistantId: string | null = null
  let currentAssistantTimestamp: Date | null = null

  const flushAssistantMessage = () => {
    if (currentAssistantId && accumulator.hasContent()) {
      processedMessages.push({
        id: currentAssistantId,
        role: 'assistant',
        content: accumulator.getSegments(),
        name: assistantName,
        assistantType,
        timestamp: currentAssistantTimestamp || new Date(),
        avatar: assistantAvatar,
      })
      accumulator.resetSegments()
      currentAssistantId = null
      currentAssistantTimestamp = null
    }
  }

  messages.forEach((msg, index) => {
    if (chatTypeFilter && msg.chatType !== chatTypeFilter) return

    const messageDataArray = Array.isArray(msg.messageData)
      ? msg.messageData
      : msg.messageData
      ? [msg.messageData]
      : []

    const isUserMessage =
      msg.owner?.type === OWNER_TYPE.CLIENT || msg.owner?.type === OWNER_TYPE.ADMIN

    if (isUserMessage) {
      flushAssistantMessage()

      messageDataArray.forEach((data) => {
        if (data.type === MESSAGE_TYPE.TEXT && 'text' in data && data.text) {
          processedMessages.push({
            id: msg.id,
            role: 'user',
            content: data.text,
            name: msg.owner?.type === OWNER_TYPE.ADMIN ? 'Admin' : 'You',
            timestamp: new Date(msg.createdAt),
          })
        }
      })
    } else {
      if (!currentAssistantId) {
        currentAssistantId = msg.id
        currentAssistantTimestamp = new Date(msg.createdAt)
      }

      messageDataArray.forEach((data) => {
        if (data.type === MESSAGE_TYPE.ERROR) {
          flushAssistantMessage()
          processedMessages.push({
            id: `${msg.id}-error`,
            role: 'error',
            content: 'error' in data && data.error ? data.error : 'An error occurred',
            name: assistantName,
            assistantType,
            timestamp: new Date(msg.createdAt),
            avatar: assistantAvatar,
          })
        } else {
          processMessageData(data, accumulator, approvalStatuses, { displayApprovalTypes }, escalatedApprovals)
        }
      })

      const nextMsg = messages[index + 1]
      const isLastMessage = index === messages.length - 1
      const nextIsFromUser =
        nextMsg &&
        (nextMsg.owner?.type === OWNER_TYPE.CLIENT || nextMsg.owner?.type === OWNER_TYPE.ADMIN)

      if (isLastMessage || nextIsFromUser) {
        flushAssistantMessage()
      }
    }
  })

  flushAssistantMessage()

  const pendingApprovalSegments = accumulator.flushPendingApprovals()
  if (pendingApprovalSegments.length > 0) {
    processedMessages.push({
      id: `pending-approvals-${Date.now()}`,
      role: 'assistant',
      content: pendingApprovalSegments,
      name: assistantName,
      assistantType,
      timestamp: new Date(),
      avatar: assistantAvatar,
    })
  }

  return {
    messages: processedMessages,
    escalatedApprovals: escalatedApprovals
  }
}

function processMessageData(
  data: MessageData,
  accumulator: MessageSegmentAccumulator,
  approvalStatuses: Record<string, string>,
  options: MessageProcessingOptions = {},
  escalatedApprovals?: Map<string, { command: string; explanation?: string; approvalType: string }>
): void {
  const { displayApprovalTypes } = options
  switch (data.type) {
    case MESSAGE_TYPE.TEXT:
      if ('text' in data && data.text) {
        accumulator.appendText(data.text)
      }
      break

    case MESSAGE_TYPE.EXECUTING_TOOL:
      if ('integratedToolType' in data) {
        accumulator.addToolExecution({
          type: 'tool_execution',
          data: {
            type: 'EXECUTING_TOOL',
            integratedToolType: data.integratedToolType || '',
            toolFunction: data.toolFunction || '',
            parameters: data.parameters,
          },
        })
      }
      break

    case MESSAGE_TYPE.EXECUTED_TOOL:
      if ('integratedToolType' in data) {
        accumulator.addToolExecution({
          type: 'tool_execution',
          data: {
            type: 'EXECUTED_TOOL',
            integratedToolType: data.integratedToolType || '',
            toolFunction: data.toolFunction || '',
            parameters: data.parameters,
            result: data.result,
            success: data.success,
          },
        })
      }
      break

    case MESSAGE_TYPE.APPROVAL_REQUEST:
      if ('approvalRequestId' in data && data.approvalRequestId) {
        const approvalType = data.approvalType || 'CLIENT'

        if (!displayApprovalTypes || displayApprovalTypes.includes(approvalType)) {
          accumulator.trackApprovalRequest(data.approvalRequestId, {
            command: data.command || '',
            explanation: data.explanation,
            approvalType,
          })
        } else {
          escalatedApprovals?.set(data.approvalRequestId, {
            command: data.command || '',
            explanation: data.explanation,
            approvalType,
          })
        }
      }
      break

    case MESSAGE_TYPE.APPROVAL_RESULT:
      if ('approvalRequestId' in data && data.approvalRequestId) {
        const existingStatus = approvalStatuses[data.approvalRequestId]
        const status = existingStatus || (data.approved ? 'approved' : 'rejected')
        const escalatedData = escalatedApprovals?.get(data.approvalRequestId)

        if (escalatedData) {
          accumulator.trackApprovalRequest(data.approvalRequestId, {
            command: escalatedData.command,
            explanation: escalatedData.explanation,
            approvalType: escalatedData.approvalType,
          })
          escalatedApprovals?.delete(data.approvalRequestId)
        }

        accumulator.processApprovalResult(
          data.approvalRequestId,
          status === 'approved',
          data.approvalType || 'USER'
        )
      }
      break

    case MESSAGE_TYPE.ERROR:
      // Errors are handled separately as error messages
      // The caller should check for error data and create error messages
      break

    default:
      // Unknown message type - ignore
      break
  }
}

