function getDeviceTypeIcon(
  type?: DeviceType,
  props?: DeviceTypeIconProps
): React.ReactElement {
  switch (type) {
    case 'desktop':
      return (
        <MonitorIcon
          className={props?.className}
          style={{ color: props?.color }}
          size={props?.size}
        />
      )
    case 'laptop':
      return (
        <LaptopIcon
          className={props?.className}
          style={{ color: props?.color }}
          size={props?.size}
        />
      )
    case 'server':
      return (
        <HardDriveIcon
          className={props?.className}
          style={{ color: props?.color }}
          size={props?.size}
        />
      )
    case 'mobile':
    case 'tablet':
    default:
      return (
        <MonitorIcon
          className={props?.className}
          style={{ color: props?.color }}
          size={props?.size}
        />
      )
  }
}

