interface UseNatsClientOptions {
  /**
   * When true, connect on mount and close on unmount.
   */
  autoConnect?: boolean
}

interface UseNatsClientResult {
  client: NatsClient | null
  status: NatsStatus
  isConnected: boolean
  lastError: unknown
}

function useNatsClient(
  clientOptions: NatsClientOptions | null,
  options: UseNatsClientOptions = {},
): UseNatsClientResult {
  const { autoConnect = true } = options

  const client = useMemo(() => {
    if (!clientOptions) return null
    return createNatsClient(clientOptions)
  }, [clientOptions])

  const [status, setStatus] = useState<NatsStatus>('disconnected')
  const [lastError, setLastError] = useState<unknown>(null)

  useEffect(() => {
    if (!client) {
      setStatus('disconnected')
      setLastError(null)
      return
    }

    const off = client.onStatus((event) => {
      setStatus(event.status)
      if (event.status === 'error') setLastError(event.data)
    })

    if (autoConnect) {
      client.connect().catch((e) => {
        setLastError(e)
        setStatus('error')
      })
    }

    return () => {
      off()
      client.close().catch(() => {
        // ignore
      })
    }
  }, [client, autoConnect])

  return {
    client,
    status,
    isConnected: status === 'connected',
    lastError,
  }
}

interface UsePlatformConfigResult {
  platforms: PlatformConfig[];
  platformOptions: PlatformOption[];
  selectableOptions: SelectableOption[];  // Rich options with icons and colors
  isLoading: boolean;
  error: Error | null;
}

function usePlatformByValue(value: string): PlatformConfig | undefined {
  const { platforms } = usePlatformConfig();
  return platforms.find(platform => platform.value === value);
}

function usePlatformConfig(): UsePlatformConfigResult {
  const [platforms, setPlatforms] = useState<PlatformConfig[]>(platformCache || []);
  const [isLoading, setIsLoading] = useState(!platformCache);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    // If we already have cached platforms, use them
    if (platformCache) {
      setPlatforms(platformCache);
      setIsLoading(false);
      return;
    }

    // If a fetch is already in progress, wait for it
    if (fetchPromise) {
      fetchPromise
        .then(data => {
          setPlatforms(data);
          setIsLoading(false);
        })
        .catch(err => {
          setError(err);
          setIsLoading(false);
        });
      return;
    }

    // Start a new fetch
    console.log('🔧 Fetching platform configurations from API (should only happen once)');

    fetchPromise = fetch('/api/config/platforms')
      .then(response => {
        if (!response.ok) {
          throw new Error(`Failed to fetch platform config: ${response.statusText}`);
        }
        return response.json();
      })
      .then(data => {
        const platforms = data.platforms || data;
        console.log('✅ Platform configurations loaded:', platforms.length, 'platforms');
        platformCache = platforms;
        fetchPromise = null;
        return platforms;
      });

    fetchPromise
      .then(data => {
        setPlatforms(data);
        setIsLoading(false);
      })
      .catch(err => {
        console.error('❌ Failed to fetch platform config:', err);
        setError(err);
        setIsLoading(false);
        fetchPromise = null;
      });
  }, []);

  // Create options for dropdowns with "All Platforms" option
  const platformOptions: PlatformOption[] = [
    { value: 'all', label: 'All Platforms' },
    ...platforms.map((platform: PlatformConfig) => ({
      value: platform.value,
      label: platform.label
    }))
  ];

  // Create rich selectable options with icons and colors
  const selectableOptions = transformPlatformConfigsToOptions(platforms);

  return {
    platforms,
    platformOptions,
    selectableOptions,
    isLoading,
    error
  };
}

function useValidatePlatform(value: string): boolean {
  const { platforms } = usePlatformConfig();
  return platforms.some(platform => platform.value === value);
}

interface FlattenedParam {
  /** URL parameter name (e.g., "severity") */
  urlParamName: string
  /** Path in GraphQL variables (e.g., "filter.severity") */
  graphqlPath: string
  /** JavaScript type for URL handling */
  type: JSType
  /** Default value for this parameter */
  defaultValue?: any
  /** Whether this parameter is required */
  required?: boolean
  /** Whether this parameter is an array */
  isArray?: boolean
}

async function flattenQueryVariables(
  queryVariables: Record<string, VariableDefinition>,
  introspector: GraphQLIntrospector
): Promise<Record<string, FlattenedParam>> {
  const flattened: Record<string, FlattenedParam> = {}

  for (const [varName, varDef] of Object.entries(queryVariables)) {
    // Primitive types or arrays - keep at top level
    if (varDef.type !== 'object') {
      flattened[varName] = {
        urlParamName: varName,
        graphqlPath: varName,
        type: varDef.isArray ? 'array' : varDef.type,
        required: varDef.required,
        isArray: varDef.isArray
      }
      continue
    }

    // Input object types - flatten fields to top level
    // This requires introspection to know the input type's fields
    if (introspector.isLoaded() && introspector.hasType(varDef.graphqlTypeName)) {
      const fields = introspector.getInputTypeFields(varDef.graphqlTypeName)

      for (const [fieldName, fieldDef] of Object.entries(fields)) {
        flattened[fieldName] = {
          urlParamName: fieldName,
          graphqlPath: `${varName}.${fieldName}`,
          type: fieldDef.isArray ? 'array' : fieldDef.type,
          required: fieldDef.required,
          isArray: fieldDef.isArray
        }
      }
    } else {
      // Introspection not available or type not found
      // Keep as top-level object (will need manual handling)
      flattened[varName] = {
        urlParamName: varName,
        graphqlPath: varName,
        type: 'object',
        required: varDef.required,
        isArray: false
      }
    }
  }

  return flattened
}

function getArrayParams(schema: Record<string, FlattenedParam>): string[] {
  return Object.entries(schema)
    .filter(([_, param]) => param.type === 'array' || param.isArray)
    .map(([key]) => key)
}

function getRequiredParams(schema: Record<string, FlattenedParam>): string[] {
  return Object.entries(schema)
    .filter(([_, param]) => param.required)
    .map(([key]) => key)
}

function mergeDefaults(
  schema: Record<string, FlattenedParam>,
  defaults: Record<string, any>
): Record<string, FlattenedParam> {
  const merged: Record<string, FlattenedParam> = {}

  for (const [key, param] of Object.entries(schema)) {
    merged[key] = {
      ...param,
      defaultValue: defaults[key] !== undefined ? defaults[key] : param.defaultValue
    }
  }

  return merged
}

function shouldIncludeInUrl(
  value: any,
  param: FlattenedParam
): boolean {
  // Null/undefined - exclude
  if (value === null || value === undefined) {
    return false
  }

  // Empty arrays - exclude
  if (Array.isArray(value) && value.length === 0) {
    return false
  }

  // Empty strings - exclude
  if (value === '') {
    return false
  }

  // Default values - exclude to keep URL clean
  if (param.defaultValue !== undefined && value === param.defaultValue) {
    return false
  }

  return true
}

function validateSchema(schema: Record<string, FlattenedParam>): void {
  const urlParamNames = new Set<string>()

  for (const [key, param] of Object.entries(schema)) {
    if (urlParamNames.has(param.urlParamName)) {
      throw new Error(
        `[FlattenSchema] Conflict: Multiple parameters map to URL param "${param.urlParamName}"`
      )
    }
    urlParamNames.add(param.urlParamName)
  }
}

interface ParsedType {
  typeName: string
  isNonNull: boolean
  isList: boolean
}

function extractVariablesFromQuery(
  query: DocumentNode
): Record<string, VariableDefinition> {
  const variables: Record<string, VariableDefinition> = {}

  visit(query, {
    VariableDefinition(node: VariableDefinitionNode) {
      const name = node.variable.name.value
      const typeInfo = parseGraphQLType(node.type)

      variables[name] = {
        name,
        type: mapGraphQLTypeToJS(typeInfo.typeName),
        required: typeInfo.isNonNull,
        isArray: typeInfo.isList,
        graphqlTypeName: typeInfo.typeName
      }
    }
  })

  return variables
}

function isInputObjectType(graphqlTypeName: string): boolean {
  return !isScalarType(graphqlTypeName)
}

function isScalarType(graphqlTypeName: string): boolean {
  const scalars = ['String', 'Int', 'Float', 'Boolean', 'ID']
  return scalars.includes(graphqlTypeName)
}

function mapGraphQLTypeToJS(graphqlType: string): JSType {
  // GraphQL scalar types
  const scalarTypeMap: Record<string, JSType> = {
    'String': 'string',
    'Int': 'number',
    'Float': 'number',
    'Boolean': 'boolean',
    'ID': 'string'
  }

  // Check if it's a known scalar
  if (scalarTypeMap[graphqlType]) {
    return scalarTypeMap[graphqlType]
  }

  // Unknown types are assumed to be input objects
  // These will be flattened using introspection
  return 'object'
}

function parseGraphQLType(typeNode: TypeNode): ParsedType {
  let typeName = ''
  let isNonNull = false
  let isList = false

  // Unwrap NonNullType wrapper
  if (typeNode.kind === 'NonNullType') {
    isNonNull = true
    typeNode = typeNode.type
  }

  // Handle ListType
  if (typeNode.kind === 'ListType') {
    isList = true
    typeNode = typeNode.type

    // ListType can also be wrapped in NonNullType
    if (typeNode.kind === 'NonNullType') {
      typeNode = typeNode.type
    }
  }

  // Extract the base type name
  if (typeNode.kind === 'NamedType') {
    typeName = typeNode.name.value
  }

  return {
    typeName,
    isNonNull,
    isList
  }
}

class GraphQLIntrospector {
  private schema: GraphQLSchema | null = null
  private cacheKey = 'graphql-schema-cache-v1'
  private cacheDuration = 24 * 60 * 60 * 1000  // 24 hours
  private schemaVersion = '1.0.0'

  /**
   * Fetch GraphQL schema via introspection query
   *
   * @param endpoint - GraphQL endpoint URL
   * @param headers - HTTP headers (e.g., authentication)
   * @param skipCache - Force fresh fetch, ignore cache
   *
   * @example
   * await introspector.fetchSchema(
   *   'http://localhost/api/graphql',
   *   { 'Authorization': 'Bearer token123' }
   * )
   */
  async fetchSchema(
    endpoint: string,
    headers: Record<string, string> = {},
    skipCache = false
  ): Promise<void> {
    // Check cache first (unless skipped)
    if (!skipCache) {
      const cached = this.loadFromCache()
      if (cached && Date.now() - cached.timestamp < this.cacheDuration) {
        try {
          this.schema = buildClientSchema(cached.schema)
          return
        } catch (error) {
          console.warn('[Introspector] Failed to build schema from cache:', error)
          // Continue to fetch fresh schema
        }
      }
    }

    // Fetch schema via introspection query
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...headers
        },
        body: JSON.stringify({
          query: getIntrospectionQuery()
        })
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      const { data, errors } = await response.json()

      if (errors) {
        throw new Error(`GraphQL errors: ${JSON.stringify(errors)}`)
      }

      if (!data) {
        throw new Error('No data returned from introspection query')
      }

      // Build and cache schema
      this.schema = buildClientSchema(data)
      this.saveToCache(data)
    } catch (error) {
      console.error('[Introspector] Failed to fetch schema:', error)
      throw error
    }
  }

  /**
   * Get fields from a GraphQL input object type
   *
   * @param typeName - Name of the input type (e.g., "LogFilterInput")
   * @returns Record of field definitions
   *
   * @example
   * const fields = introspector.getInputTypeFields('LogFilterInput')
   * // {
   * //   severity: { name: 'severity', type: 'array', ... },
   * //   toolType: { name: 'toolType', type: 'array', ... }
   * // }
   */
  getInputTypeFields(typeName: string): Record<string, VariableDefinition> {
    if (!this.schema) {
      return {}
    }

    const type = this.schema.getType(typeName)

    if (!type || !isInputObjectType(type)) {
      return {}
    }

    const fields: Record<string, VariableDefinition> = {}
    const typeFields = type.getFields()

    for (const [fieldName, field] of Object.entries(typeFields)) {
      const fieldType = this.unwrapType(field.type)

      fields[fieldName] = {
        name: fieldName,
        type: this.mapGraphQLTypeToJS(fieldType.typeName),
        required: fieldType.isNonNull,
        isArray: fieldType.isList,
        graphqlTypeName: fieldType.typeName
      }
    }

    return fields
  }

  /**
   * Check if a type exists in the schema
   */
  hasType(typeName: string): boolean {
    if (!this.schema) return false
    return this.schema.getType(typeName) !== undefined
  }

  /**
   * Get the schema (if loaded)
   */
  getSchema(): GraphQLSchema | null {
    return this.schema
  }

  /**
   * Check if schema is loaded
   */
  isLoaded(): boolean {
    return this.schema !== null
  }

  /**
   * Clear cached schema
   */
  clearCache(): void {
    try {
      localStorage.removeItem(this.cacheKey)
      this.schema = null
    } catch {
      // Ignore storage errors
    }
  }

  /**
   * Unwrap GraphQL type to get base type info
   * Handles NonNull and List wrappers
   */
  private unwrapType(type: GraphQLInputType): {
    typeName: string
    isNonNull: boolean
    isList: boolean
  } {
    let typeName = ''
    let isNonNull = false
    let isList = false
    let current: any = type

    // Unwrap NonNull wrapper
    if (current.toString().endsWith('!')) {
      isNonNull = true
      current = 'ofType' in current ? current.ofType : current
    }

    // Check for List wrapper
    if (current.toString().startsWith('[')) {
      isList = true
      current = 'ofType' in current ? current.ofType : current
    }

    // Handle inner NonNull (e.g., [String!])
    if (current.toString().endsWith('!')) {
      current = 'ofType' in current ? current.ofType : current
    }

    // Get base type name
    typeName = current.name || current.toString().replace(/[[\]!]/g, '')

    return { typeName, isNonNull, isList }
  }

  /**
   * Map GraphQL types to JavaScript types for URL handling
   */
  private mapGraphQLTypeToJS(graphqlType: string): JSType {
    const typeMap: Record<string, JSType> = {
      'String': 'string',
      'Int': 'number',
      'Float': 'number',
      'Boolean': 'boolean',
      'ID': 'string'
    }

    return typeMap[graphqlType] || 'object'
  }

  /**
   * Load schema from localStorage cache
   */
  private loadFromCache(): SchemaCache | null {
    try {
      const cached = localStorage.getItem(this.cacheKey)
      if (!cached) return null

      const parsed = JSON.parse(cached) as SchemaCache

      // Validate cache version
      if (parsed.version !== this.schemaVersion) {
        return null
      }

      return parsed
    } catch (error) {
      console.warn('[Introspector] Failed to load cache:', error)
      return null
    }
  }

  /**
   * Save schema to localStorage cache
   */
  private saveToCache(schema: IntrospectionQuery): void {
    try {
      const cache: SchemaCache = {
        schema,
        timestamp: Date.now(),
        version: this.schemaVersion
      }

      localStorage.setItem(this.cacheKey, JSON.stringify(cache))
    } catch (error) {
      console.warn('[Introspector] Failed to save cache:', error)
      // Ignore storage errors (e.g., quota exceeded)
    }
  }
}

interface SchemaCache {
  schema: IntrospectionQuery
  timestamp: number
  version: string
}

clearCache(): void {
    try {
      localStorage.removeItem(this.cacheKey)
      this.schema = null
    } catch {
      // Ignore storage errors
    }
  }

async fetchSchema(
    endpoint: string,
    headers: Record<string, string> = {},
    skipCache = false
  ): Promise<void> {
    // Check cache first (unless skipped)
    if (!skipCache) {
      const cached = this.loadFromCache()
      if (cached && Date.now() - cached.timestamp < this.cacheDuration) {
        try {
          this.schema = buildClientSchema(cached.schema)
          return
        } catch (error) {
          console.warn('[Introspector] Failed to build schema from cache:', error)
          // Continue to fetch fresh schema
        }
      }
    }

    // Fetch schema via introspection query
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...headers
        },
        body: JSON.stringify({
          query: getIntrospectionQuery()
        })
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }

      const { data, errors } = await response.json()

      if (errors) {
        throw new Error(`GraphQL errors: ${JSON.stringify(errors)}`)
      }

      if (!data) {
        throw new Error('No data returned from introspection query')
      }

      // Build and cache schema
      this.schema = buildClientSchema(data)
      this.saveToCache(data)
    } catch (error) {
      console.error('[Introspector] Failed to fetch schema:', error)
      throw error
    }
  }

getInputTypeFields(typeName: string): Record<string, VariableDefinition> {
    if (!this.schema) {
      return {}
    }

    const type = this.schema.getType(typeName)

    if (!type || !isInputObjectType(type)) {
      return {}
    }

    const fields: Record<string, VariableDefinition> = {}
    const typeFields = type.getFields()

    for (const [fieldName, field] of Object.entries(typeFields)) {
      const fieldType = this.unwrapType(field.type)

      fields[fieldName] = {
        name: fieldName,
        type: this.mapGraphQLTypeToJS(fieldType.typeName),
        required: fieldType.isNonNull,
        isArray: fieldType.isList,
        graphqlTypeName: fieldType.typeName
      }
    }

    return fields
  }

getSchema(): GraphQLSchema | null {
    return this.schema
  }

hasType(typeName: string): boolean {
    if (!this.schema) return false
    return this.schema.getType(typeName) !== undefined
  }

isLoaded(): boolean {
    return this.schema !== null
  }

private loadFromCache(): SchemaCache | null {
    try {
      const cached = localStorage.getItem(this.cacheKey)
      if (!cached) return null

      const parsed = JSON.parse(cached) as SchemaCache

      // Validate cache version
      if (parsed.version !== this.schemaVersion) {
        return null
      }

      return parsed
    } catch (error) {
      console.warn('[Introspector] Failed to load cache:', error)
      return null
    }
  }

private mapGraphQLTypeToJS(graphqlType: string): JSType {
    const typeMap: Record<string, JSType> = {
      'String': 'string',
      'Int': 'number',
      'Float': 'number',
      'Boolean': 'boolean',
      'ID': 'string'
    }

    return typeMap[graphqlType] || 'object'
  }

private saveToCache(schema: IntrospectionQuery): void {
    try {
      const cache: SchemaCache = {
        schema,
        timestamp: Date.now(),
        version: this.schemaVersion
      }

      localStorage.setItem(this.cacheKey, JSON.stringify(cache))
    } catch (error) {
      console.warn('[Introspector] Failed to save cache:', error)
      // Ignore storage errors (e.g., quota exceeded)
    }
  }

private unwrapType(type: GraphQLInputType): {
    typeName: string
    isNonNull: boolean
    isList: boolean
  } {
    let typeName = ''
    let isNonNull = false
    let isList = false
    let current: any = type

    // Unwrap NonNull wrapper
    if (current.toString().endsWith('!')) {
      isNonNull = true
      current = 'ofType' in current ? current.ofType : current
    }

    // Check for List wrapper
    if (current.toString().startsWith('[')) {
      isList = true
      current = 'ofType' in current ? current.ofType : current
    }

    // Handle inner NonNull (e.g., [String!])
    if (current.toString().endsWith('!')) {
      current = 'ofType' in current ? current.ofType : current
    }

    // Get base type name
    typeName = current.name || current.toString().replace(/[[\]!]/g, '')

    return { typeName, isNonNull, isList }
  }

function clearParams(
  variables: Record<string, any>,
  paramNames: string[],
  schema: Record<string, FlattenedParam>
): Record<string, any> {
  const cleared = { ...variables }

  for (const paramName of paramNames) {
    const paramConfig = schema[paramName]
    if (!paramConfig) continue

    // Set to undefined (will be excluded from URL)
    setNestedValue(cleared, paramConfig.graphqlPath, undefined)
  }

  return cleared
}

function coerceValue(value: string | string[], type: JSType): any {
  // Array handling
  if (Array.isArray(value)) {
    return value.map(v => coerceValue(v, type === 'array' ? 'string' : type))
  }

  // Type coercion for single values
  switch (type) {
    case 'number':
      const num = parseFloat(value)
      return isNaN(num) ? null : num

    case 'boolean':
      return value === 'true' || value === '1'

    case 'array':
      // Single value treated as array with one element
      return [value]

    case 'string':
    default:
      return value
  }
}

function getNestedValue(obj: any, path: string): any {
  return path.split('.').reduce((current, key) => {
    return current?.[key]
  }, obj)
}

function mergeVariables(
  currentVariables: Record<string, any>,
  updates: Record<string, any>,
  schema: Record<string, FlattenedParam>
): Record<string, any> {
  const merged = { ...currentVariables }

  for (const [paramName, value] of Object.entries(updates)) {
    const paramConfig = schema[paramName]
    if (!paramConfig) continue

    setNestedValue(merged, paramConfig.graphqlPath, value)
  }

  return merged
}

function setNestedValue(obj: any, path: string, value: any): void {
  const parts = path.split('.')
  let current = obj

  // Navigate/create intermediate objects
  for (let i = 0; i < parts.length - 1; i++) {
    const part = parts[i]
    if (!(part in current) || typeof current[part] !== 'object') {
      current[part] = {}
    }
    current = current[part]
  }

  // Set final value
  const lastPart = parts[parts.length - 1]
  current[lastPart] = value
}

function urlParamsToVariables(
  searchParams: URLSearchParams,
  schema: Record<string, FlattenedParam>
): Record<string, any> {
  const variables: Record<string, any> = {}

  for (const [paramName, paramConfig] of Object.entries(schema)) {
    // Read value from URL
    const rawValue = paramConfig.type === 'array' || paramConfig.isArray
      ? searchParams.getAll(paramName)
      : searchParams.get(paramName)

    // Skip if no value in URL
    if (!rawValue || (Array.isArray(rawValue) && rawValue.length === 0)) {
      // Use default value if available
      if (paramConfig.defaultValue !== undefined) {
        setNestedValue(variables, paramConfig.graphqlPath, paramConfig.defaultValue)
      }
      continue
    }

    // Coerce value to correct type
    const value = coerceValue(rawValue, paramConfig.type)

    // Set value at nested path
    setNestedValue(variables, paramConfig.graphqlPath, value)
  }

  return variables
}

function validateVariables(
  variables: Record<string, any>,
  schema: Record<string, FlattenedParam>
): string[] {
  const errors: string[] = []

  for (const [paramName, paramConfig] of Object.entries(schema)) {
    const value = getNestedValue(variables, paramConfig.graphqlPath)

    // Check required parameters
    if (paramConfig.required && (value === null || value === undefined)) {
      errors.push(`Required parameter "${paramName}" is missing`)
    }

    // Check type consistency
    if (value !== null && value !== undefined) {
      const actualType = Array.isArray(value) ? 'array' : typeof value
      const expectedType = paramConfig.type === 'array' ? 'array' : paramConfig.type

      if (actualType !== expectedType && actualType !== 'object') {
        errors.push(
          `Parameter "${paramName}" has wrong type: expected ${expectedType}, got ${actualType}`
        )
      }
    }
  }

  return errors
}

function variablesToUrlParams(
  variables: Record<string, any>,
  schema: Record<string, FlattenedParam>
): URLSearchParams {
  const params = new URLSearchParams()

  for (const [paramName, paramConfig] of Object.entries(schema)) {
    // Get value from nested path
    const value = getNestedValue(variables, paramConfig.graphqlPath)

    // Skip if should not include in URL
    if (!shouldIncludeInUrl(value, paramConfig)) {
      continue
    }

    // Add to URL params
    if (Array.isArray(value)) {
      // Array: Use repeated params (e.g., ?tag=foo&tag=bar)
      value.forEach(v => {
        if (v !== null && v !== undefined && v !== '') {
          params.append(paramName, String(v))
        }
      })
    } else {
      // Single value: Use set
      params.set(paramName, String(value))
    }
  }

  return params
}

interface ParamConfig<T extends JSType = JSType> {
  /** JavaScript type for URL parameter */
  type: T
  /** Default value matching the type */
  default?: DefaultValueForType<T>
  /** Whether parameter is required */
  required?: boolean
}

interface UseApiParamsOptions {
  /** Enable debug logging */
  debug?: boolean
}

interface UseApiParamsReturn<
  TSchema extends ParamSchema,
  TParams = InferParamsFromSchema<TSchema>
> {
  /** Parsed parameters object with strict typing */
  params: TParams

  /** URLSearchParams for fetch/axios */
  urlSearchParams: URLSearchParams

  /** Set a single parameter with type-safe key and value */
  setParam: <K extends keyof TSchema & string>(
    key: K,
    value: InferInputParamsFromSchema<Pick<TSchema, K>>[K]
  ) => void

  /** Set multiple parameters at once */
  setParams: (updates: Partial<InferInputParamsFromSchema<TSchema>>) => void

  /** Clear specific parameters */
  clearParams: (keys: (keyof TSchema & string)[]) => void

  /** Reset all parameters (clear URL) */
  resetParams: () => void
}

function createSearchParams(params: Record<string, ParamValue>): URLSearchParams {
  const searchParams = new URLSearchParams()

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === '' || value === null) {
      continue
    }

    if (Array.isArray(value)) {
      value.forEach(v => {
        if (v !== undefined && v !== '' && v !== null) {
          searchParams.append(key, String(v))
        }
      })
    } else if (typeof value === 'object') {
      // For objects, convert to JSON string
      searchParams.set(key, JSON.stringify(value))
    } else {
      searchParams.set(key, String(value))
    }
  }

  return searchParams
}

function defineParamSchema<T extends ParamSchema>(schema: T): T {
  return schema
}

function useApiParams<TSchema extends ParamSchema>(
  schema: TSchema,
  options: UseApiParamsOptions = {}
): UseApiParamsReturn<TSchema> {
  const router = useRouter()
  const searchParams = useSearchParams()
  const debug = options.debug || false

  // Convert schema to flattened format for reuse
  const flattenedSchema = useMemo((): Record<string, FlattenedParam> => {
    const flattened: Record<string, FlattenedParam> = {}

    for (const [key, config] of Object.entries(schema)) {
      flattened[key] = {
        urlParamName: key,
        graphqlPath: key,
        type: config.type,
        defaultValue: config.default,
        required: config.required,
        isArray: config.type === 'array'
      }
    }

    return flattened
  }, [schema])

  // Parse URL parameters with type coercion
  const params = useMemo((): InferParamsFromSchema<TSchema> => {
    const result: Record<string, unknown> = {}

    for (const [key, config] of Object.entries(schema)) {
      // Read from URL
      const rawValue = config.type === 'array'
        ? searchParams.getAll(key)
        : searchParams.get(key)

      // Use value from URL or default
      if (rawValue && (Array.isArray(rawValue) ? rawValue.length > 0 : true)) {
        result[key] = coerceValue(rawValue, config.type)
      } else {
        result[key] = config.default
      }
    }

    if (debug) {
      console.log('[useApiParams] Parsed params:', result)
    }

    return result as InferParamsFromSchema<TSchema>
  }, [searchParams, schema, debug])

  // Helper: Add parameter value to URLSearchParams
  const addParamToSearchParams = useCallback((
    searchParams: URLSearchParams,
    key: string,
    value: ParamValue
  ): void => {
    if (value === undefined || value === '' || value === null) {
      return
    }

    if (Array.isArray(value)) {
      value.forEach(v => {
        if (v !== undefined && v !== '' && v !== null) {
          searchParams.append(key, String(v))
        }
      })
    } else if (typeof value === 'object') {
      // For objects, convert to JSON string
      searchParams.set(key, JSON.stringify(value))
    } else {
      searchParams.set(key, String(value))
    }
  }, [])

  // Get URLSearchParams for fetch/axios
  const urlSearchParams = useMemo((): URLSearchParams => {
    const newParams = new URLSearchParams()

    for (const [key, config] of Object.entries(schema)) {
      const value = (params as Record<string, unknown>)[key]
      const paramConfig = flattenedSchema[key]

      // Skip if should not include
      if (!shouldIncludeInUrl(value, paramConfig)) {
        continue
      }

      addParamToSearchParams(newParams, key, value as ParamValue)
    }

    return newParams
  }, [params, schema, flattenedSchema, addParamToSearchParams])

  // Update URL with new parameters (preserve other params not managed by this hook)
  const updateUrl = useCallback((newParams: URLSearchParams, keysToRemove: string[] = []) => {
    // Preserve all existing params, then override with new ones
    const finalParams = new URLSearchParams(searchParams)

    // Remove keys that are explicitly marked for removal
    keysToRemove.forEach(key => {
      if (key in schema) {
        finalParams.delete(key)
      }
    })

    // Remove keys that are being updated (from newParams)
    // This preserves other schema parameters that aren't being changed
    newParams.forEach((_, key) => {
      // Only remove keys that are in our schema
      if (key in schema) {
        finalParams.delete(key)
      }
    })

    // Add all new values (including multiple values for array params)
    // Only add parameters that are in our schema to avoid duplicating external params
    newParams.forEach((value, key) => {
      // Only process keys that are in our schema
      if (key in schema) {
        if (finalParams.has(key)) {
          // Key already exists (from array params), append
          finalParams.append(key, value)
        } else {
          // First value for this key, use set
          finalParams.set(key, value)
        }
      }
    })

    const url = finalParams.toString() 
      ? `?${finalParams.toString()}` 
      : window.location.pathname

    if (debug) {
      console.log('[useApiParams] Updating URL:', url)
    }

    // Use replace for shallow routing (no page reload, no history spam)
    router.replace(url, { scroll: false })
  }, [router, debug, searchParams, schema])

  // Helper to check if value is empty
  const isEmptyValue = (value: unknown): boolean => {
    if (value === undefined || value === null || value === '') {
      return true
    }
    if (Array.isArray(value)) {
      // Empty array or array with all empty/null/undefined values
      return value.length === 0 || value.every(v => v === undefined || v === null || v === '')
    }
    return false
  }

  // Set a single parameter
  const setParam = useCallback(<K extends keyof TSchema & string>(
    key: K,
    value: InferInputParamsFromSchema<Pick<TSchema, K>>[K]
  ) => {
    const config = schema[key]

    if (!config) {
      console.warn(`[useApiParams] Unknown parameter: ${key}`)
      return
    }

    const newParams = new URLSearchParams()

    if (isEmptyValue(value)) {
      updateUrl(newParams, [key])
    } else {
      addParamToSearchParams(newParams, key, value as ParamValue)
      updateUrl(newParams)
    }
  }, [schema, updateUrl, addParamToSearchParams])

  // Set multiple parameters
  const setParams = useCallback((
    updates: Partial<InferInputParamsFromSchema<TSchema>>
  ) => {
    const newParams = new URLSearchParams()
    const keysToRemove: string[] = []

    for (const [key, value] of Object.entries(updates)) {
      const config = schema[key]

      if (!config) {
        console.warn(`[useApiParams] Unknown parameter: ${key}`)
        continue
      }

      if (isEmptyValue(value)) {
        keysToRemove.push(key)
      } else {
        addParamToSearchParams(newParams, key, value as ParamValue)
      }
    }

    updateUrl(newParams, keysToRemove)
  }, [schema, updateUrl, addParamToSearchParams])

  // Clear specific parameters
  const clearParams = useCallback((keys: (keyof TSchema & string)[]) => {
    const newParams = new URLSearchParams()
    updateUrl(newParams, keys)
  }, [updateUrl])

  // Reset all parameters
  const resetParams = useCallback(() => {
    if (debug) {
      console.log('[useApiParams] Resetting params')
    }

    router.replace(window.location.pathname, { scroll: false })
  }, [router, debug])

  return {
    params,
    urlSearchParams,
    setParam,
    setParams,
    clearParams,
    resetParams
  }
}

interface CursorPaginationStateReturn {
  // Search
  searchInput: string
  setSearchInput: (value: string) => void

  // Pagination tracking
  hasLoadedBeyondFirst: boolean
  setHasLoadedBeyondFirst: (value: boolean) => void

  // Handlers for useTablePagination
  handleNextPage: (endCursor: string, fetchFn: () => Promise<unknown>) => Promise<void>
  handleResetToFirstPage: (fetchFn: () => Promise<unknown>) => Promise<void>

  // URL params access (for advanced use cases)
  params: PaginationParams
  setParam: ApiParamsReturn['setParam']
  setParams: ApiParamsReturn['setParams']
}

interface UseCursorPaginationStateOptions {
  /**
   * Debounce delay for search input (default: 300ms)
   */
  debounceMs?: number

  /**
   * Callback for initial page load
   * Called once on mount with current search and cursor from URL
   */
  onInitialLoad: (search: string, cursor: string | null) => void | Promise<unknown>

  /**
   * Callback when search term changes (after debounce)
   * Called after URL is updated, cursor is already reset
   */
  onSearchChange: (search: string) => void | Promise<unknown>
}

function useCursorPaginationState(
  options: UseCursorPaginationStateOptions
): CursorPaginationStateReturn {
  const {
    onInitialLoad,
    onSearchChange,
  } = options

  const { params, setParam, setParams } = useApiParams(urlSchema)

  // Local search input with debounce
  const [searchInput, setSearchInput] = useState(params.search || '')

  // Pagination tracking
  const [hasLoadedBeyondFirst, setHasLoadedBeyondFirst] = useState(false)
  // Use a counter instead of boolean to ensure effects see the latest state
  const [initialLoadCount, setInitialLoadCount] = useState(0)
  // Initialize to null to distinguish "never set" from "set to empty string"
  const lastSearchRef = useRef<string | null>(null)
  // Track if we're syncing from URL to prevent loops
  const isSyncingFromUrl = useRef(false)
  // Track if initial load is in progress to block ALL other effects
  const isInitialLoadInProgress = useRef(true)

  // Sync local input with URL param (for tab switches that clear params)
  // Only sync if the URL changed externally (not from our own debounce update)
  useEffect(() => {
    // Block during initial load
    if (isInitialLoadInProgress.current) return

    const urlSearch = params.search || ''
    // Only sync if URL differs from current input
    if (urlSearch !== searchInput) {
      isSyncingFromUrl.current = true
      setSearchInput(urlSearch)
      // Reset the flag after a tick to allow normal operation
      setTimeout(() => { isSyncingFromUrl.current = false }, 0)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [params.search, initialLoadCount]) // Add initialLoadCount to re-run after initial load

  // Sync debounced search to URL, reset cursor when search changes
  useEffect(() => {
    // Block during initial load
    if (isInitialLoadInProgress.current) return
    // Skip if we're syncing from URL to prevent loops
    if (isSyncingFromUrl.current) return

    if (searchInput !== params.search) {
      setParams({
        search: searchInput,
        cursor: '' // Reset cursor when search changes
      })
    }
  }, [searchInput, params.search, setParams, initialLoadCount])

  // Initial load effect - runs once and blocks all other effects until complete
  useEffect(() => {
    if (initialLoadCount === 0) {
      const cursor = params.cursor || null
      const search = params.search || ''

      // Set all refs BEFORE calling onInitialLoad
      lastSearchRef.current = search

      // If we have a cursor in URL (page refresh), we're beyond first page
      if (cursor) {
        setHasLoadedBeyondFirst(true)
      }

      // Call the initial load and wait for it to complete before
      // marking initial load as done (handles async onInitialLoad)
      Promise.resolve(onInitialLoad(search, cursor)).finally(() => {
        isInitialLoadInProgress.current = false
        setInitialLoadCount(1)
      })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Search change detection - only after initial load is fully complete
  useEffect(() => {
    // Block during initial load
    if (isInitialLoadInProgress.current) return
    if (initialLoadCount === 0) return

    const currentSearch = params.search || ''
    // Only trigger search change if:
    // 1. lastSearchRef has been set (not null - means initial load happened)
    // 2. The search actually changed
    if (lastSearchRef.current !== null && currentSearch !== lastSearchRef.current) {
      lastSearchRef.current = currentSearch
      setHasLoadedBeyondFirst(false)
      onSearchChange(currentSearch)
    }
  }, [params.search, onSearchChange, initialLoadCount])

  // Pagination handlers
  const handleNextPage = useCallback(
    async (endCursor: string, fetchFn: () => Promise<unknown>) => {
      setParam('cursor', endCursor)
      await fetchFn()
      setHasLoadedBeyondFirst(true)
    },
    [setParam]
  )

  const handleResetToFirstPage = useCallback(
    async (fetchFn: () => Promise<unknown>) => {
      setParam('cursor', '')
      await fetchFn()
      setHasLoadedBeyondFirst(false)
    },
    [setParam]
  )

  return {
    searchInput,
    setSearchInput,
    hasLoadedBeyondFirst,
    setHasLoadedBeyondFirst,
    handleNextPage,
    handleResetToFirstPage,
    params,
    setParam,
    setParams,
  }
}

interface UseQueryParamsOptions {
  /** Default values for parameters */
  defaultValues?: Record<string, any>

  /** GraphQL endpoint for introspection (defaults to process.env.NEXT_PUBLIC_API_URL/graphql) */
  introspectionEndpoint?: string

  /** HTTP headers for introspection (e.g., authentication) */
  introspectionHeaders?: Record<string, string>

  /** Skip introspection (use only AST parsing, no nested type flattening) */
  skipIntrospection?: boolean

  /** Custom parameter name mapping (override auto-generated names) */
  paramMapping?: Record<string, string>

  /** Enable debug logging */
  debug?: boolean
}

interface UseQueryParamsReturn<TVariables = Record<string, any>> {
  /** GraphQL variables ready for Apollo Client */
  variables: TVariables

  /** Raw URL parameters (before conversion to variables) */
  params: Record<string, any>

  /** Flattened parameter schema */
  schema: Record<string, FlattenedParam>

  /** Set a single parameter */
  setParam: (key: string, value: any) => void

  /** Set multiple parameters at once */
  setParams: (params: Record<string, any>) => void

  /** Clear specific parameters */
  clearParams: (keys: string[]) => void

  /** Reset all parameters (clear URL) */
  resetParams: () => void

  /** Whether schema is ready (introspection complete) */
  isReady: boolean

  /** Loading state during initialization */
  isLoading: boolean

  /** Error during initialization */
  error: Error | null
}

function applyParamMapping(
  schema: Record<string, FlattenedParam>,
  mapping: Record<string, string>
): Record<string, FlattenedParam> {
  const mapped: Record<string, FlattenedParam> = {}

  for (const [key, param] of Object.entries(schema)) {
    const newKey = mapping[key] || key
    mapped[newKey] = {
      ...param,
      urlParamName: mapping[key] || param.urlParamName
    }
  }

  return mapped
}

function useQueryParams<TVariables = Record<string, any>>(
  query: DocumentNode,
  options: UseQueryParamsOptions = {}
): UseQueryParamsReturn<TVariables> {
  const router = useRouter()
  const searchParams = useSearchParams()

  const [isLoading, setIsLoading] = useState(true)
  const [isReady, setIsReady] = useState(false)
  const [error, setError] = useState<Error | null>(null)
  const [schema, setSchema] = useState<Record<string, FlattenedParam>>({})

  // Extract default values
  const defaultValues = options.defaultValues || {}
  const skipIntrospection = options.skipIntrospection || false
  const debug = options.debug || false

  // Initialize: Parse query + fetch schema (once)
  useEffect(() => {
    async function initialize() {
      try {
        if (debug) console.log('[useQueryParams] Initializing...')

        // 1. Extract variables from query AST
        const queryVariables = extractVariablesFromQuery(query)

        if (debug) {
          console.log('[useQueryParams] Extracted variables:', queryVariables)
        }

        // 2. Fetch GraphQL schema via introspection (if needed and not skipped)
        if (!skipIntrospection && !introspector.isLoaded()) {
          const endpoint = options.introspectionEndpoint ||
            (typeof window !== 'undefined' && process.env.NEXT_PUBLIC_API_URL
              ? `${process.env.NEXT_PUBLIC_API_URL}/graphql`
              : '')

          if (endpoint) {
            try {
              await introspector.fetchSchema(endpoint, options.introspectionHeaders)
              if (debug) console.log('[useQueryParams] Introspection complete')
            } catch (err) {
              console.warn('[useQueryParams] Introspection failed, continuing without it:', err)
              // Continue without introspection - nested types won't be flattened
            }
          }
        }

        // 3. Flatten schema (with or without introspection)
        let flattenedSchema = await flattenQueryVariables(queryVariables, introspector)

        // Apply custom param mapping if provided
        if (options.paramMapping) {
          flattenedSchema = applyParamMapping(flattenedSchema, options.paramMapping)
        }

        // Merge default values
        flattenedSchema = mergeDefaults(flattenedSchema, defaultValues)

        // Validate schema
        validateSchema(flattenedSchema)

        if (debug) {
          console.log('[useQueryParams] Flattened schema:', flattenedSchema)
        }

        setSchema(flattenedSchema)
        setIsReady(true)
      } catch (err) {
        const error = err instanceof Error ? err : new Error(String(err))
        console.error('[useQueryParams] Initialization failed:', error)
        setError(error)
      } finally {
        setIsLoading(false)
      }
    }

    initialize()
  }, [query, options.introspectionEndpoint, skipIntrospection, debug])

  // Convert URL params to GraphQL variables
  const variables = useMemo(() => {
    if (!isReady) {
      return defaultValues as TVariables
    }

    try {
      const varsFromUrl = urlParamsToVariables(searchParams, schema)
      const merged = { ...defaultValues, ...varsFromUrl }

      if (debug) {
        console.log('[useQueryParams] Variables from URL:', merged)
      }

      return merged as TVariables
    } catch (err) {
      console.error('[useQueryParams] Failed to convert URL to variables:', err)
      return defaultValues as TVariables
    }
  }, [searchParams, schema, isReady, defaultValues, debug])

  // Raw URL params (before conversion)
  const params = useMemo(() => {
    const result: Record<string, any> = {}
    searchParams.forEach((value, key) => {
      if (result[key]) {
        // Multiple values - convert to array
        if (!Array.isArray(result[key])) {
          result[key] = [result[key]]
        }
        result[key].push(value)
      } else {
        result[key] = value
      }
    })
    return result
  }, [searchParams])

  // Update URL with new parameters
  const updateUrl = useCallback((newParams: URLSearchParams) => {
    const url = newParams.toString() ? `?${newParams.toString()}` : window.location.pathname

    if (debug) {
      console.log('[useQueryParams] Updating URL:', url)
    }

    // Use replace for shallow routing (no page reload, no history spam)
    router.replace(url, { scroll: false })
  }, [router, debug])

  // Set a single parameter
  const setParam = useCallback((key: string, value: any) => {
    if (!isReady) {
      console.warn('[useQueryParams] Schema not ready, cannot set param')
      return
    }

    try {
      const currentVars = variables
      const updated = mergeVariables(currentVars as Record<string, any>, { [key]: value }, schema)
      const newParams = variablesToUrlParams(updated, schema)
      updateUrl(newParams)
    } catch (err) {
      console.error('[useQueryParams] Failed to set param:', err)
    }
  }, [variables, schema, isReady, updateUrl])

  // Set multiple parameters
  const setParams = useCallback((updates: Record<string, any>) => {
    if (!isReady) {
      console.warn('[useQueryParams] Schema not ready, cannot set params')
      return
    }

    try {
      const currentVars = variables
      const updated = mergeVariables(currentVars as Record<string, any>, updates, schema)
      const newParams = variablesToUrlParams(updated, schema)
      updateUrl(newParams)
    } catch (err) {
      console.error('[useQueryParams] Failed to set params:', err)
    }
  }, [variables, schema, isReady, updateUrl])

  // Clear specific parameters
  const clearParamsHandler = useCallback((keys: string[]) => {
    if (!isReady) {
      console.warn('[useQueryParams] Schema not ready, cannot clear params')
      return
    }

    try {
      const currentVars = variables
      const updated = clearParams(currentVars as Record<string, any>, keys, schema)
      const newParams = variablesToUrlParams(updated, schema)
      updateUrl(newParams)
    } catch (err) {
      console.error('[useQueryParams] Failed to clear params:', err)
    }
  }, [variables, schema, isReady, updateUrl])

  // Reset all parameters
  const resetParams = useCallback(() => {
    if (debug) {
      console.log('[useQueryParams] Resetting params')
    }

    router.replace(window.location.pathname, { scroll: false })
  }, [router, debug])

  return {
    variables,
    params,
    schema,
    setParam,
    setParams,
    clearParams: clearParamsHandler,
    resetParams,
    isReady,
    isLoading,
    error
  }
}

function useDebounce<T>(value: T, delay = 500): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    // Set up timeout to update debounced value
    const timer = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    // Clean up timeout on value change or unmount
    return () => {
      clearTimeout(timer)
    }
  }, [value, delay])

  return debouncedValue
}

function useLocalStorage<T>(key: string, initialValue: T): [T, (value: T | ((val: T) => T)) => void] {
  // State to store our value
  // Use lazy initialization to read from localStorage synchronously on first render
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      if (typeof window !== "undefined") {
        const item = window.localStorage.getItem(key)
        // Parse stored json or if none return initialValue
        return item ? JSON.parse(item) : initialValue
      }
    } catch (error) {
      console.error(`Error reading localStorage key "${key}":`, error)
    }
    return initialValue
  })

  // Use a ref to track if we've initialized from localStorage
  const isInitialized = useRef(true) // Set to true since we initialize in useState
  // Use a ref to track if the current state change came from a storage event
  const isFromStorageEvent = useRef(false)

  // Listen for storage events to sync with other tabs/components
  useEffect(() => {
    if (!isInitialized.current) return

    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === key && e.newValue !== null) {
        try {
          const newValue = JSON.parse(e.newValue)
          isFromStorageEvent.current = true
          setStoredValue(newValue)
          console.log(`🔄 Updated localStorage key "${key}" from storage event`)
        } catch (error) {
          console.error(`Error parsing storage event for key "${key}":`, error)
        }
      }
    }

    const handleCustomStorageUpdate = (e: CustomEvent) => {
      if (e.detail.key === key) {
        try {
          if (e.detail.newValue === null || e.detail.newValue === undefined) {
            // localStorage was cleared or key was removed
            isFromStorageEvent.current = true
            setStoredValue(initialValue)
            console.log(`🔄 Cleared localStorage key "${key}" from custom storage event`)
          } else {
            const newValue = JSON.parse(e.detail.newValue)
            isFromStorageEvent.current = true
            setStoredValue(newValue)
            console.log(`🔄 Updated localStorage key "${key}" from custom storage event`)
          }
        } catch (error) {
          console.error(`Error parsing custom storage event for key "${key}":`, error)
        }
      }
    }

    window.addEventListener('storage', handleStorageChange)
    window.addEventListener('localStorageUpdate', handleCustomStorageUpdate as EventListener)

    return () => {
      window.removeEventListener('storage', handleStorageChange)
      window.removeEventListener('localStorageUpdate', handleCustomStorageUpdate as EventListener)
    }
  }, [key])

  // Update localStorage when state changes, but only after initialization and NOT from storage events
  useEffect(() => {
    if (!isInitialized.current) return

    // Skip localStorage write if this state change came from a storage event
    if (isFromStorageEvent.current) {
      isFromStorageEvent.current = false
      return
    }

    try {
      // Save state to localStorage
      if (typeof window !== "undefined") {
        window.localStorage.setItem(key, JSON.stringify(storedValue))
      }
    } catch (error) {
      console.error(`Error writing to localStorage key "${key}":`, error)
    }
  }, [key, storedValue])

  // Return a wrapped version of useState's setter function that
  // persists the new value to localStorage
  const setValue = (value: T | ((val: T) => T)) => {
    try {
      // Allow value to be a function so we have same API as useState
      const valueToStore = value instanceof Function ? value(storedValue) : value
      // Save state
      setStoredValue(valueToStore)
    } catch (error) {
      console.error(`Error setting value for localStorage key "${key}":`, error)
    }
  }

  return [storedValue, setValue]
}

