  return matches === undefined ? undefined : matches
}

function useMemoizedCallback<T extends (...args: any[]) => any>(callback: T, dependencies: any[]): T {
  // Store the callback and dependencies
  const callbackRef = useRef<T>(callback)
  const dependenciesRef = useRef<any[]>(dependencies)

  // Update the callback if it changes
  callbackRef.current = callback

  // Check if dependencies have changed
  const depsChanged = dependencies.some((dep, i) => !Object.is(dep, dependenciesRef.current[i]))

  // Update dependencies if they've changed
  if (depsChanged) {
    dependenciesRef.current = dependencies
  }

  // Return memoized callback
  return useCallback(((...args: any[]) => callbackRef.current(...args)) as T, [depsChanged])
}

function useOnboardingState(storageKey: string = 'openframe-onboarding-state') {
  const [state, setState] = useState<OnboardingState>(() => loadOnboardingState(storageKey))
  const [, forceUpdate] = useState(0)

  // Listen for storage changes from other tabs
  useEffect(() => {
    const handleStorageUpdate = (e: CustomEvent) => {
      if (e.detail.key === storageKey) {
        const newState = loadOnboardingState(storageKey)
        setState(newState)
        forceUpdate(prev => prev + 1)
        console.log('🔄 State updated from storage event:', newState)
      }
    }

    window.addEventListener('localStorageUpdate', handleStorageUpdate as EventListener)
    return () => {
      window.removeEventListener('localStorageUpdate', handleStorageUpdate as EventListener)
    }
  }, [storageKey])

  const markComplete = useCallback((stepId: string) => {
    console.log(`🎯 markComplete called for: "${stepId}"`)
    const newState = storageMarkComplete(storageKey, stepId)
    setState(newState)
    forceUpdate(prev => prev + 1)
  }, [storageKey])

  const markSkipped = useCallback((stepId: string) => {
    console.log(`⏭️ markSkipped called for: "${stepId}"`)
    const newState = storageMarkSkipped(storageKey, stepId)
    setState(newState)
    forceUpdate(prev => prev + 1)
  }, [storageKey])

  const dismissOnboarding = useCallback(() => {
    console.log(`🚫 dismissOnboarding called`)
    const newState = storageDismiss(storageKey)
    setState(newState)
    forceUpdate(prev => prev + 1)
  }, [storageKey])

  const markMultipleComplete = useCallback((stepIds: string[]) => {
    console.log(`🎯 markMultipleComplete called for:`, stepIds)
    const newState = storageMarkMultiple(storageKey, stepIds)
    setState(newState)
    forceUpdate(prev => prev + 1)
    console.log(`📝 State after batch:`, newState)
  }, [storageKey])

  const isStepComplete = useCallback((stepId: string): boolean => {
    return state.completedSteps.includes(stepId)
  }, [state.completedSteps])

  const isStepSkipped = useCallback((stepId: string): boolean => {
    return state.skippedSteps.includes(stepId)
  }, [state.skippedSteps])

  const allStepsComplete = useCallback((steps: OnboardingStepConfig[]): boolean => {
    return steps.every(step => isStepComplete(step.id) || isStepSkipped(step.id))
  }, [isStepComplete, isStepSkipped])

  return {
    state,
    markComplete,
    markSkipped,
    dismissOnboarding,
    isStepComplete,
    isStepSkipped,
    allStepsComplete,
    markMultipleComplete
  }
}

function useTablePagination(
  config: PaginationConfig | null
): CursorPaginationProps | undefined {
  return useMemo(() => {
    if (!config) return undefined

    if (config.type === 'client') {
      // Client-side pagination: show if more than 1 page
      if (config.totalPages <= 1) return undefined

      return {
        hasNextPage: config.currentPage < config.totalPages,
        hasPreviousPage: config.currentPage > 1,
        isFirstPage: config.currentPage === 1,
        startCursor: (config.currentPage - 1).toString(),
        endCursor: config.currentPage.toString(),
        currentCount: config.itemCount,
        itemName: config.itemName || 'items',
        onNext: () => config.onNext(),
        onPrevious: () => config.onPrevious(),
        showInfo: config.showInfo ?? true
      }
    } else {
      // Server-side pagination: show if pageInfo exists
      return {
        hasNextPage: config.hasNextPage,
        hasPreviousPage: config.hasLoadedBeyondFirst,
        isFirstPage: !config.hasLoadedBeyondFirst,
        startCursor: config.startCursor,
        endCursor: config.endCursor,
        currentCount: config.itemCount,
        itemName: config.itemName || 'items',
        onNext: config.onNext,
        onPrevious: config.onReset, // Previous button goes back to first page
        showInfo: config.showInfo ?? true
      }
    }
  }, [config])
}

function useThrottle<T>(value: T, limit = 200): T {
  const [throttledValue, setThrottledValue] = useState<T>(value)
  const lastUpdated = useRef<number>(Date.now())

  useEffect(() => {
    const now = Date.now()
    const elapsed = now - lastUpdated.current

    // If enough time has elapsed, update the throttled value
    if (elapsed >= limit) {
      setThrottledValue(value)
      lastUpdated.current = now
    } else {
      // Otherwise, set up a timeout to update after the limit
      const timerId = setTimeout(() => {
        setThrottledValue(value)
        lastUpdated.current = Date.now()
      }, limit - elapsed)

      return () => {
        clearTimeout(timerId)
      }
    }
  }, [value, limit])

  return throttledValue
}

function useWindowSize() {
  const [windowSize, setWindowSize] = useState({
    width: 0,
    height: 0,
  })
  const [isClient, setIsClient] = useState(false)

  useLayoutEffect(() => {
    setIsClient(true)
    if (!isClient) return

    const handleResize = () => {
      setWindowSize({
        width: window.innerWidth,
        height: window.innerHeight,
      })
    }

    // Set initial size
    handleResize()

    // Add event listener
    window.addEventListener("resize", handleResize)

    // Remove event listener on cleanup
    return () => window.removeEventListener("resize", handleResize)
  }, [isClient])

  return windowSize
}

interface AuthenticatedImageConfig {
  /** Base URL for tenant-specific API calls (e.g., 'https://tenant.openframe.dev' or '') */
  tenantHostUrl?: string
  /** Enable dev mode with Bearer token from localStorage */
  enableDevMode?: boolean
  /** localStorage key for access token (default: 'of_access_token') */
  accessTokenKey?: string
}

function configureAuthenticatedImage(config: AuthenticatedImageConfig): void {
  globalImageConfig = { ...globalImageConfig, ...config }
}

function getImageConfig(): Required<AuthenticatedImageConfig> {
  return {
    tenantHostUrl: globalImageConfig.tenantHostUrl || '',
    enableDevMode: globalImageConfig.enableDevMode ?? false,
    accessTokenKey: globalImageConfig.accessTokenKey || 'of_access_token'
  }
}

function useAuthenticatedImage(
  imageUrl?: string | null,
  refreshKey?: string | number,
  config?: AuthenticatedImageConfig
): {
  imageUrl: string | undefined
  isLoading: boolean
  error: string | null
} {
  const [fetchedImageUrl, setFetchedImageUrl] = useState<string | undefined>()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cleanup: (() => void) | undefined

    if (imageUrl) {
      setIsLoading(true)
      setError(null)

      const { tenantHostUrl, enableDevMode, accessTokenKey } = {
        ...getImageConfig(),
        ...config
      }

      // Construct full image URL
      let fullImageUrl: string
      if (imageUrl.startsWith('http://') || imageUrl.startsWith('https://')) {
        fullImageUrl = imageUrl
      } else if (imageUrl.startsWith('/api/')) {
        fullImageUrl = `${tenantHostUrl}${imageUrl}`
      } else if (imageUrl.startsWith('/')) {
        fullImageUrl = `${tenantHostUrl}/api${imageUrl}`
      } else {
        fullImageUrl = `${tenantHostUrl}/api/${imageUrl}`
      }

      // Add cache buster (use refreshKey if provided, otherwise timestamp)
      const cacheBuster = refreshKey ? `?v=${refreshKey}` : `?t=${Date.now()}`
      fullImageUrl = fullImageUrl + cacheBuster

      // Prepare headers
      const headers: Record<string, string> = {
        'Accept': 'image/*',
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Pragma': 'no-cache'
      }

      // Add Bearer token in dev mode
      if (enableDevMode) {
        try {
          const accessToken = localStorage.getItem(accessTokenKey)
          if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`
          }
        } catch (error) {
          // Silently continue without token
        }
      }

      // Fetch image
      fetch(fullImageUrl, {
        method: 'GET',
        credentials: 'include', // Include cookies for authentication
        headers
      })
        .then(response => {
          if (!response.ok) {
            throw new Error(`Failed to fetch image: ${response.status}`)
          }
          return response.blob()
        })
        .then(blob => {
          const objectUrl = URL.createObjectURL(blob)
          setFetchedImageUrl(objectUrl)
          setIsLoading(false)

          // Setup cleanup function
          cleanup = () => {
            URL.revokeObjectURL(objectUrl)
          }
        })
        .catch(err => {
          setError(err instanceof Error ? err.message : 'Failed to fetch image')
          setFetchedImageUrl(undefined)
          setIsLoading(false)
        })
    } else {
      // No imageUrl provided
      setFetchedImageUrl(undefined)
      setIsLoading(false)
      setError(null)
    }

    // Cleanup blob URL on unmount or when imageUrl/refreshKey changes
    return () => {
      if (cleanup) {
        cleanup()
      }
    }
  }, [imageUrl, refreshKey, config])

  return { imageUrl: fetchedImageUrl, isLoading, error }
}

interface BatchImageFetchConfig {
  /** Base URL for tenant-specific API calls (e.g., 'https://tenant.openframe.dev' or '') */
  tenantHostUrl?: string
  /** Enable dev mode with Bearer token from localStorage */
  enableDevMode?: boolean
  /** localStorage key for access token (default: 'of_access_token') */
  accessTokenKey?: string
}

async function batchFetchAuthenticatedImages(
  imageUrls: string[],
  config?: BatchImageFetchConfig
): Promise<Record<string, string | undefined>> {
  const results: Record<string, string | undefined> = {}

  if (imageUrls.length === 0) {
    return results
  }

  const { tenantHostUrl, enableDevMode, accessTokenKey } = {
    ...getBatchImageConfig(),
    ...config
  }

  const fetchPromises = imageUrls.map(async (imageUrl) => {
    try {
      // Construct full image URL
      let fullImageUrl: string
      if (imageUrl.startsWith('http://') || imageUrl.startsWith('https://')) {
        fullImageUrl = imageUrl
      } else if (imageUrl.startsWith('/api/')) {
        fullImageUrl = `${tenantHostUrl}${imageUrl}`
      } else if (imageUrl.startsWith('/')) {
        fullImageUrl = `${tenantHostUrl}/api${imageUrl}`
      } else {
        fullImageUrl = `${tenantHostUrl}/api/${imageUrl}`
      }

      // Add cache buster
      const cacheBuster = `?t=${Date.now()}`
      fullImageUrl = fullImageUrl + cacheBuster

      // Prepare headers
      const headers: Record<string, string> = {
        'Accept': 'image/*',
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Pragma': 'no-cache'
      }

      // Add Bearer token in dev mode
      if (enableDevMode) {
        try {
          const accessToken = localStorage.getItem(accessTokenKey)
          if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`
          }
        } catch (error) {
          // Silently continue without token
        }
      }

      // Fetch image
      const response = await fetch(fullImageUrl, {
        method: 'GET',
        credentials: 'include', // Include cookies for authentication
        headers
      })

      if (!response.ok) {
        throw new Error(`Failed to fetch image: ${response.status}`)
      }

      // Convert to blob URL
      const blob = await response.blob()
      const objectUrl = URL.createObjectURL(blob)

      return { imageUrl, fetchedUrl: objectUrl }
    } catch (error) {
      console.warn(`Failed to fetch image ${imageUrl}:`, error)
      return { imageUrl, fetchedUrl: undefined }
    }
  })

  const fetchResults = await Promise.all(fetchPromises)

  fetchResults.forEach(({ imageUrl, fetchedUrl }) => {
    results[imageUrl] = fetchedUrl
  })

  return results
}

function configureBatchImageFetch(config: BatchImageFetchConfig): void {
  globalBatchImageConfig = { ...globalBatchImageConfig, ...config }
}

function getBatchImageConfig(): Required<BatchImageFetchConfig> {
  return {
    tenantHostUrl: globalBatchImageConfig.tenantHostUrl || '',
    enableDevMode: globalBatchImageConfig.enableDevMode ?? false,
    accessTokenKey: globalBatchImageConfig.accessTokenKey || 'of_access_token'
  }
}

function useBatchImages(
  imageUrls: (string | null | undefined)[],
  config?: BatchImageFetchConfig
): Record<string, string | undefined> {
  const [fetchedImages, setFetchedImages] = useState<Record<string, string | undefined>>({})
  const [loading, setLoading] = useState(false)

  // Deduplicate and filter out null/undefined
  const uniqueUrls = useMemo(() =>
    Array.from(new Set(imageUrls.filter((url): url is string => Boolean(url)))),
    [imageUrls]
  )

  // Track URLs we've already requested to avoid duplicate fetches
  const requestedUrls = useRef<Set<string>>(new Set())

  useEffect(() => {
    if (uniqueUrls.length === 0) {
      setFetchedImages({})
      return
    }

    // Find URLs we haven't fetched yet
    const urlsToFetch = uniqueUrls.filter(url => !requestedUrls.current.has(url))

    if (urlsToFetch.length === 0) {
      return // All URLs already requested
    }

    // Mark these URLs as requested
    urlsToFetch.forEach(url => requestedUrls.current.add(url))

    setLoading(true)

    batchFetchAuthenticatedImages(urlsToFetch, config)
      .then(newResults => {
        setFetchedImages(prev => ({ ...prev, ...newResults }))
      })
      .catch(error => {
        console.error('Failed to batch fetch images:', error)
      })
      .finally(() => {
        setLoading(false)
      })

    // Cleanup blob URLs on unmount
    return () => {
      Object.values(fetchedImages).forEach(blobUrl => {
        if (blobUrl && blobUrl.startsWith('blob:')) {
          URL.revokeObjectURL(blobUrl)
        }
      })
    }
  }, [uniqueUrls, config])

  return fetchedImages
}

interface ContactFormData {
  name: string;
  email: string;
  companySize: string;
  referralSource: string;
  helpCategory: string;
  message: string;
}

interface ContactSubmissionOptions {
  userId?: string;
  successRedirectUrl?: string;
  successToastMessage?: string;
  onSuccess?: () => void;
}

function useContactSubmission(options: ContactSubmissionOptions = {}) {
  const { userId, successRedirectUrl, successToastMessage, onSuccess } = options;
  const { toast } = useToast();
  const router = useRouter();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const submit = useCallback(async (formData: ContactFormData) => {
    if (isSubmitting) return;

    setIsSubmitting(true);

    try {
      const response = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          ...formData,
          user_id: userId
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to submit contact form');
      }

      // Success
      setIsSuccess(true);
      const message = successToastMessage 
        ? `Thank you! Your message has been sent. ${successToastMessage}`
        : 'Thank you! Your message has been sent successfully.';

      toast({
        title: "Message sent!",
        description: message,
        variant: 'success',
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Something went wrong. Please try again.';
      toast({ 
        title: 'Failed to send message', 
        description: message, 
        variant: 'destructive' 
      });
      throw error; // allow caller to handle if needed
    } finally {
      setIsSubmitting(false);
    }
  }, [isSubmitting, toast, userId, successToastMessage]);

  // Handle redirect after success
  useEffect(() => {
    if (isSuccess && successRedirectUrl) {
      console.log('🚀 Contact submission successful, redirecting to:', successRedirectUrl);
      const timer = setTimeout(() => {
        console.log('🎯 Performing redirect now to:', successRedirectUrl);
        if (successRedirectUrl.startsWith('http')) {
          window.location.href = successRedirectUrl;
        } else {
          router.push(successRedirectUrl);
        }
      }, 1500);

      return () => clearTimeout(timer);
    }
  }, [isSuccess, successRedirectUrl, router]);

  // Call onSuccess callback if provided
  useEffect(() => {
    if (isSuccess && onSuccess) {
      onSuccess();
    }
  }, [isSuccess, onSuccess]);

  return { submit, isSubmitting, isSuccess, setIsSuccess } as const;
}

