function formatRelativeTime(timestamp: string | Date): string {
  const now = new Date();
  const targetTime = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;

  // Validate the date
  if (isNaN(targetTime.getTime())) {
    console.warn('⚠️ Invalid timestamp in formatRelativeTime:', timestamp);
    return 'Unknown time';
  }

  const diffInMs = now.getTime() - targetTime.getTime();
  const diffInMinutes = Math.floor(diffInMs / (1000 * 60));

  // Handle future dates (should not happen but graceful fallback)
  if (diffInMinutes < 0) {
    return 'Just now';
  }

  // Less than 1 minute
  if (diffInMinutes < 1) return 'Just now';

  // 1-59 minutes
  if (diffInMinutes < 60) return `${diffInMinutes}m ago`;

  // 1-23 hours  
  const diffInHours = Math.floor(diffInMinutes / 60);
  if (diffInHours < 24) return `${diffInHours}h ago`;

  // 1-6 days
  const diffInDays = Math.floor(diffInHours / 24);
  if (diffInDays < 7) return `${diffInDays}d ago`;

  // 1-4 weeks
  if (diffInDays < 30) {
    const weeks = Math.floor(diffInDays / 7);
    return `${weeks}w ago`;
  }

  // Older than 30 days - show formatted date
  return targetTime.toLocaleDateString('en-US', { 
    month: 'short', 
    day: 'numeric',
    year: targetTime.getFullYear() !== now.getFullYear() ? 'numeric' : undefined
  });
}

function getDetailedTimeDifference(timestamp: string | Date): string {
  const now = new Date();
  const targetTime = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;

  if (isNaN(targetTime.getTime())) {
    return 'Invalid date';
  }

  const diffInMs = now.getTime() - targetTime.getTime();
  const diffInSeconds = Math.floor(diffInMs / 1000);
  const diffInMinutes = Math.floor(diffInSeconds / 60);
  const diffInHours = Math.floor(diffInMinutes / 60);
  const diffInDays = Math.floor(diffInHours / 24);

  if (diffInSeconds < 60) return `${diffInSeconds} seconds ago`;
  if (diffInMinutes < 60) return `${diffInMinutes} minutes ago`;
  if (diffInHours < 24) return `${diffInHours} hours ago`;
  if (diffInDays < 30) return `${diffInDays} days ago`;

  const diffInMonths = Math.floor(diffInDays / 30);
  if (diffInMonths < 12) return `${diffInMonths} months ago`;

  const diffInYears = Math.floor(diffInDays / 365);
  return `${diffInYears} years ago`;
}

function isToday(timestamp: string | Date): boolean {
  const today = new Date();
  const targetTime = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;

  return today.toDateString() === targetTime.toDateString();
}

function isWithinMinutes(timestamp: string | Date, minutes: number): boolean {
  const now = new Date();
  const targetTime = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
  const diffInMs = now.getTime() - targetTime.getTime();
  const diffInMinutes = diffInMs / (1000 * 60);

  return diffInMinutes <= minutes && diffInMinutes >= 0;
}

function getDynamicIcon(
  iconName: string | undefined | null,
  size: DynamicIconSize = 'md',
  className?: string
): React.ReactNode {

  if (!iconName) {
    console.warn('[getDynamicIcon] No iconName provided, using Globe fallback');
    return <Globe className={SIZE_CLASSES[size]} />;
  }

  const sizeClass = SIZE_CLASSES[size];
  const finalClassName = className ? `${sizeClass} ${className}` : sizeClass;

  // Lookup icon from registry
  const IconComponent = ICON_REGISTRY[iconName];

  if (IconComponent) {
    const colorConfig = ICON_COLORS[iconName] || {};
    return <IconComponent className={finalClassName} {...colorConfig} />;
  }

  // Fallback
  console.error(`[getDynamicIcon] Icon NOT found in registry: "${iconName}". Available icons:`, Object.keys(ICON_REGISTRY));
  return <Globe className={finalClassName} />;
}

