    switchTheme: (newPlatform: Platform) => switchPlatformTheme(newPlatform),
    getSemanticColor: (semanticName: string) => getSemanticColor(semanticName, currentPlatform)
  };
}

interface OnboardingState {
  completedSteps: string[]
  skippedSteps: string[]
  dismissed: boolean
  lastUpdated: string
}

function dismissOnboarding(key: string): OnboardingState {
  const state = loadOnboardingState(key)
  const newState: OnboardingState = {
    ...state,
    dismissed: true,
    lastUpdated: new Date().toISOString()
  }
  saveOnboardingState(key, newState)
  return newState
}

function isOnboardingDismissed(key: string): boolean {
  const state = loadOnboardingState(key)
  return state.dismissed
}

function isStepComplete(key: string, stepId: string): boolean {
  const state = loadOnboardingState(key)
  return state.completedSteps.includes(stepId)
}

function isStepSkipped(key: string, stepId: string): boolean {
  const state = loadOnboardingState(key)
  return state.skippedSteps.includes(stepId)
}

function loadOnboardingState(key: string): OnboardingState {
  if (typeof window === 'undefined') return DEFAULT_STATE

  try {
    const raw = localStorage.getItem(key)
    if (!raw) return DEFAULT_STATE

    const parsed = JSON.parse(raw) as OnboardingState
    return parsed
  } catch (err) {
    console.warn('[onboarding-storage] Failed parsing localStorage data:', err)
    return DEFAULT_STATE
  }
}

function markMultipleComplete(
  key: string,
  stepIds: string[]
): OnboardingState {
  const state = loadOnboardingState(key)
  const newState: OnboardingState = {
    ...state,
    completedSteps: [...new Set([...state.completedSteps, ...stepIds])],
    skippedSteps: state.skippedSteps.filter(id => !stepIds.includes(id)),
    lastUpdated: new Date().toISOString()
  }
  saveOnboardingState(key, newState)
  return newState
}

function markStepComplete(key: string, stepId: string): OnboardingState {
  return markMultipleComplete(key, [stepId])
}

function markStepSkipped(key: string, stepId: string): OnboardingState {
  const state = loadOnboardingState(key)
  const newState: OnboardingState = {
    ...state,
    skippedSteps: [...new Set([...state.skippedSteps, stepId])],
    completedSteps: state.completedSteps.filter(id => id !== stepId),
    lastUpdated: new Date().toISOString()
  }
  saveOnboardingState(key, newState)
  return newState
}

function saveOnboardingState(key: string, state: OnboardingState): void {
  if (typeof window === 'undefined') return

  try {
    localStorage.setItem(key, JSON.stringify(state))
    console.log('💾 Saved onboarding state:', state)

    // Dispatch custom event for cross-tab sync
    if (typeof window !== 'undefined') {
      window.dispatchEvent(
        new CustomEvent('localStorageUpdate', {
          detail: { key, newValue: JSON.stringify(state) }
        })
      )
    }
  } catch (err) {
    console.warn('[onboarding-storage] Failed saving to localStorage:', err)
  }
}

