function fixSupabaseStorageUrl(url: string): string {
  // Early return if nothing to process
  if (!url) return url;

  /**
   * We previously restricted the fix to URLs that contained a specific Supabase
   * domain ("supabase.co"). However, we now serve assets from a custom domain
   * (e.g. app.openmsp.ai) that still uses the same `/storage/v1/object/public/`
   * path structure. The old guard clause prevented those URLs from being
   * cleaned which resulted in paths like:
   *   https://app.openmsp.ai/storage/v1/object/public/logos///Ansible.png
   * Googlebot treats the triple-slash as a distinct resource and reports 404
   * errors which in turn causes the "URL will be indexed only if certain
   * conditions are met" warning in Search Console.
   *
   * Solution: detect the canonical Supabase storage path segment instead of
   * the host name. Whenever we see that path we safely collapse multiple
   * consecutive slashes to a single slash while preserving the protocol
   * (`https://`).
   */

  const SUPABASE_STORAGE_SEGMENT = '/storage/v1/object/public/';

  if (url.includes(SUPABASE_STORAGE_SEGMENT)) {
    return fixUrlDoubleSlashes(url);
  }

  // No known storage segment – return the original URL untouched
  return url;
}

function fixUrlDoubleSlashes(url: string): string {
  if (!url) return url;

  // Split on protocol to preserve it
  const protocolMatch = url.match(/^(https?:\/\/)/);
  if (protocolMatch) {
    const protocol = protocolMatch[1];
    const rest = url.substring(protocol.length);
    // Replace multiple consecutive slashes with single slash in the path part
    const fixedRest = rest.replace(/\/+/g, '/');
    return protocol + fixedRest;
  }

  // For relative URLs, just fix multiple slashes
  return url.replace(/\/+/g, '/');
}

function joinUrlPath(...segments: string[]): string {
  return segments
    .map((segment, index) => {
      // Remove leading slash from all but first segment
      if (index > 0 && segment.startsWith('/')) {
        segment = segment.substring(1);
      }
      // Remove trailing slash from all but last segment
      if (index < segments.length - 1 && segment.endsWith('/')) {
        segment = segment.substring(0, segment.length - 1);
      }
      return segment;
    })
    .filter(segment => segment.length > 0)
    .join('/');
}

interface EmailDomainValidationResult {
  valid: boolean
  error?: string
  cleanedDomain?: string
}

function cleanEmailDomain(domain: string): string {
  if (!domain || typeof domain !== 'string') {
    return ''
  }

  let cleaned = domain.trim().toLowerCase()

  // Remove leading @
  if (cleaned.startsWith('@')) {
    cleaned = cleaned.substring(1)
  }

  // Remove protocol if present
  cleaned = cleaned.replace(/^https?:\/\//, '')

  // Remove trailing slash and path
  cleaned = cleaned.split('/')[0]

  // Remove www. prefix
  cleaned = cleaned.replace(/^www\./, '')

  return cleaned
}

function isValidEmailDomain(domain: string): boolean {
  if (!domain || typeof domain !== 'string') {
    return false
  }

  const trimmed = domain.trim()
  if (!trimmed) {
    return false
  }

  // Domain regex: must have at least one dot, valid characters, and proper TLD
  // Allows subdomains, hyphens (not at start/end of labels), alphanumeric characters
  const domainRegex = /^(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.[A-Za-z0-9-]{1,63})*\.[A-Za-z]{2,}$/
  return domainRegex.test(trimmed)
}

function validateEmailDomain(domain: string): EmailDomainValidationResult {
  if (!domain || typeof domain !== 'string') {
    return { valid: false, error: 'Email domain is required' }
  }

  // Clean the input: trim and remove leading @ if user enters it
  let trimmed = domain.trim()
  if (trimmed.startsWith('@')) {
    trimmed = trimmed.substring(1)
  }

  // Check for empty after cleaning
  if (!trimmed) {
    return { valid: false, error: 'Email domain is required' }
  }

  // Check for protocol (common mistake: entering full URL)
  if (trimmed.includes('://')) {
    return { valid: false, error: 'Enter email domain only (e.g., openframe.ai), not a URL' }
  }

  // Check for @ symbol (common mistake: entering full email address)
  if (trimmed.includes('@')) {
    return { valid: false, error: 'Enter domain only, not a full email address' }
  }

  // Check for spaces
  if (trimmed.includes(' ')) {
    return { valid: false, error: 'Domain cannot contain spaces' }
  }

  // Check for trailing slash
  if (trimmed.includes('/')) {
    return { valid: false, error: 'Enter domain only, without paths' }
  }

  // Validate the domain format
  if (!isValidEmailDomain(trimmed)) {
    return { valid: false, error: 'Invalid domain format (e.g., openframe.ai)' }
  }

  // Return success with the cleaned domain
  return { valid: true, cleanedDomain: trimmed.toLowerCase() }
}

function validateEmailDomainList(domains: string[]): {
  valid: boolean
  error?: string
  cleanedDomains?: string[]
} {
  if (!Array.isArray(domains)) {
    return { valid: false, error: 'Domains must be an array' }
  }

  const cleanedDomains: string[] = []
  const seenDomains = new Set<string>()

  for (const domain of domains) {
    const result = validateEmailDomain(domain)

    if (!result.valid) {
      return { valid: false, error: `Invalid domain "${domain}": ${result.error}` }
    }

    const cleanedDomain = result.cleanedDomain!

    // Check for duplicates (case-insensitive)
    if (seenDomains.has(cleanedDomain)) {
      return { valid: false, error: `Duplicate domain: ${cleanedDomain}` }
    }

    seenDomains.add(cleanedDomain)
    cleanedDomains.push(cleanedDomain)
  }

  return { valid: true, cleanedDomains }
}

interface VendorMedia {
  media_type: 'logo' | 'image' | 'video';
  media_url: string;
}

interface VendorWithMedia {
  id?: number;
  title: string;
  slug?: string;
  logo?: string | null;
  logo_url?: string; // Support direct logo_url field from lightweight API
  vendor_media?: VendorMedia[];
}

function addVendorMedia(vendor: VendorWithMedia, type: 'logo' | 'image' | 'video', url: string): VendorMedia[] {
  const existingMedia = vendor.vendor_media || [];
  const newMedia: VendorMedia = { media_type: type, media_url: url };
  return [...existingMedia, newMedia];
}

function getVendorImage(vendor: VendorWithMedia): string | null {
  const imageMedia = vendor.vendor_media?.find(m => m.media_type === 'image');
  return imageMedia?.media_url ? fixSupabaseStorageUrl(imageMedia.media_url) : null;
}

function getVendorLogo(vendor: VendorWithMedia): string | null {
  // First check for direct logo_url field (from lightweight API)
  if (vendor.logo_url) {
    return fixSupabaseStorageUrl(vendor.logo_url);
  }

  // Check for legacy logo field
  if (vendor.logo) {
    return fixSupabaseStorageUrl(vendor.logo);
  }

  // Fallback to vendor_media array (from detailed API)
  const logoMedia = vendor.vendor_media?.find(m => m.media_type === 'logo');
  if (logoMedia?.media_url) {
    return fixSupabaseStorageUrl(logoMedia.media_url);
  }

  return null;
}

function getVendorMediaByType(vendor: VendorWithMedia, type: 'logo' | 'image' | 'video'): string[] {
  return vendor.vendor_media?.filter(m => m.media_type === type).map(m => fixSupabaseStorageUrl(m.media_url)) || [];
}

function getVendorMediaCount(vendor: VendorWithMedia): {
  logos: number;
  images: number;
  videos: number;
  total: number;
} {
  const media = vendor.vendor_media || [];

  const logos = media.filter(m => m.media_type === 'logo').length;
  const images = media.filter(m => m.media_type === 'image').length;
  const videos = media.filter(m => m.media_type === 'video').length;

  return {
    logos,
    images,
    videos,
    total: media.length
  };
}

function getVendorMediaGrouped(vendor: VendorWithMedia): {
  logos: string[];
  images: string[];
  videos: string[];
} {
  const media = vendor.vendor_media || [];

  return {
    logos: media.filter(m => m.media_type === 'logo').map(m => fixSupabaseStorageUrl(m.media_url)),
    images: media.filter(m => m.media_type === 'image').map(m => fixSupabaseStorageUrl(m.media_url)),
    videos: media.filter(m => m.media_type === 'video').map(m => fixSupabaseStorageUrl(m.media_url))
  };
}

function getVendorVideo(vendor: VendorWithMedia): string | null {
  const videoMedia = vendor.vendor_media?.find(m => m.media_type === 'video');
  return videoMedia?.media_url ? fixSupabaseStorageUrl(videoMedia.media_url) : null;
}

function hasVendorMedia(vendor: VendorWithMedia, type: 'logo' | 'image' | 'video'): boolean {
  return vendor.vendor_media?.some(m => m.media_type === type) || false;
}

function removeVendorMedia(vendor: VendorWithMedia, url: string): VendorMedia[] {
  return vendor.vendor_media?.filter(m => m.media_url !== url) || [];
}

