            .map(t -> {
                String dbIssuer = allowedIssuerBase + "/" + t.getId();
                List<String> list = new ArrayList<>(2);
                list.add(dbIssuer);
                if (superTenantId != null && !superTenantId.isBlank()) {
                    String superIssuer = allowedIssuerBase + "/" + superTenantId;
                    if (!superIssuer.equals(dbIssuer)) {
