                .port(uri.getPort())
                .path(uri.getPath())
                .query(uri.getQuery())
                .fragment(uri.getFragment())
                .build()
                .toUriString();
        } catch (Exception e) {
            log.error("Failed to parse URL: {}", originalUrl, e);
            return originalUrl;
