            .post()
            .uri(String.format("%s/%s/oauth2/token", authServerUrl, tenantId))
            .headers(h -> {
                h.add(com.openframe.core.constants.HttpHeaders.AUTHORIZATION, basicAuth(clientId, clientSecret));
