        if (errorNode != null && !errorNode.isNull()) {
            if (queryName != null) {
                return Optional.of(String.format("Query '%s' execution failed: %s", queryName, errorNode.asText()));
            }
            return Optional.of("Query execution failed: " + errorNode.asText());
        }

