interface UseChatMessagesOptions {
  onApprove?: (requestId?: string) => Promise<void> | void
  onReject?: (requestId?: string) => Promise<void> | void
}

function useChatMessages({ onApprove, onReject }: UseChatMessagesOptions = {}) {
  const [messages, setMessages] = useState<Message[]>([])
  const segmentAccumulator = useRef(
    createMessageSegmentAccumulator({ onApprove, onReject })
  ).current

  const addMessage = useCallback((message: Message) => {
    setMessages(prev => [...prev, message])
  }, [])

  const updateLastAssistantMessage = useCallback((segments: MessageSegment[]) => {
    setMessages(prev => {
      const newMessages = [...prev]
      const lastMessage = newMessages[newMessages.length - 1]
      if (lastMessage?.role === 'assistant') {
        newMessages[newMessages.length - 1] = {
          ...lastMessage,
          content: segments.length > 0 ? segments : ''
        }
      }
      return newMessages
    })
  }, [])

  const ensureAssistantMessage = useCallback(() => {
    setMessages(prev => {
      const last = prev[prev.length - 1]
      if (last?.role === 'assistant') return prev

      const assistantMessage: Message = {
        id: `assistant-${Date.now()}`,
        role: 'assistant',
        name: 'Fae',
        content: [],
        timestamp: new Date(),
        avatar: faeAvatar
      }
      return [...prev, assistantMessage]
    })
  }, [])

  const addErrorMessage = useCallback((errorText: string) => {
    const errorMessage: Message = {
      id: `error-${Date.now()}`,
      role: 'error',
      name: 'Fae',
      timestamp: new Date(),
      avatar: faeAvatar,
      content: errorText,
    }

    setMessages(prev => {
      const lastMessage = prev[prev.length - 1]
      if (lastMessage?.role === 'assistant' && 
          (lastMessage.content === '' || 
           (Array.isArray(lastMessage.content) && lastMessage.content.length === 0))) {
        return [...prev.slice(0, -1), errorMessage]
      }
      return [...prev, errorMessage]
    })
  }, [])

  const clearMessages = useCallback(() => {
    setMessages([])
    segmentAccumulator.reset()
  }, [segmentAccumulator])

  const appendTextToCurrentMessage = useCallback((text: string) => {
    const segments = segmentAccumulator.appendText(text)
    updateLastAssistantMessage(segments)
  }, [segmentAccumulator, updateLastAssistantMessage])

  const addToolSegmentToCurrentMessage = useCallback((segment: MessageSegment) => {
    if (segment.type === 'tool_execution') {
      const segments = segmentAccumulator.addToolExecution(segment)
      updateLastAssistantMessage(segments)
    }
  }, [segmentAccumulator, updateLastAssistantMessage])

  const resetCurrentMessageSegments = useCallback(() => {
    segmentAccumulator.resetSegments()
  }, [segmentAccumulator])

  const updateSegments = useCallback((segments: MessageSegment[]) => {
    segmentAccumulator.reset()
    segments.forEach(segment => {
      if (segment.type === 'text' && segment.text) {
        segmentAccumulator.appendText(segment.text)
      } else if (segment.type === 'tool_execution') {
        segmentAccumulator.addToolExecution(segment)
      } else if (segment.type === 'approval_request') {
        const { data, status } = segment
        segmentAccumulator.addApprovalRequest(
          data.requestId || '',
          data.command,
          data.explanation,
          data.approvalType || '',
          status
        )
      }
    })
    updateLastAssistantMessage(segmentAccumulator.getSegments())
  }, [segmentAccumulator, updateLastAssistantMessage])

  return {
    messages,
    hasMessages: messages.length > 0,
    addMessage,
    updateLastAssistantMessage,
    ensureAssistantMessage,
    addErrorMessage,
    clearMessages,
    appendTextToCurrentMessage,
    addToolSegmentToCurrentMessage,
    resetCurrentMessageSegments,
    updateSegments,
    segmentAccumulator
  }
}

interface UseChunkCatchupOptions {
  dialogId: string | null
  onChunkReceived: (chunk: ChunkData, messageType: NatsMessageType) => void
}

function useChunkCatchup({ dialogId, onChunkReceived }: UseChunkCatchupOptions): UseChunkCatchupReturn {
  const fetchChunks = useCallback(async (
    dialogId: string,
    chatType: ChatType,
    fromSequenceId?: number | null
  ): Promise<ChunkData[]> => {
    await tokenService.ensureTokenReady()
    const token = tokenService.getCurrentToken()
    const apiUrl = tokenService.getCurrentApiBaseUrl()

    if (!token || !apiUrl) {
      throw new Error('Token or API URL not available')
    }

    let url = `${apiUrl}/chat/api/v1/dialogs/${dialogId}/chunks?chatType=${chatType}`
    if (fromSequenceId !== null && fromSequenceId !== undefined) {
      url += `&fromSequenceId=${fromSequenceId}`
    }

    const response = await fetch(url, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    })

    if (!response.ok) {
      console.error(`Failed to fetch ${chatType} chunks:`, response.status)
      return []
    }

    return await response.json() as ChunkData[]
  }, [])

  const options = useMemo<CoreChunkCatchupOptions>(() => ({
    dialogId,
    onChunkReceived,
    chatTypes: [CHAT_TYPE.CLIENT],
    fetchChunks,
  }), [dialogId, onChunkReceived, fetchChunks])

  return useChunkCatchupCore(options)
}

interface UseConnectionStatusReturn {
  status: ConnectionStatus
  serverUrl: string | null
  aiConfiguration: AIConfiguration | null
  isFullyLoaded: boolean
}

function useConnectionStatus(): UseConnectionStatusReturn {
  const [status, setStatus] = useState<ConnectionStatus>('connecting')
  const [serverUrl, setServerUrl] = useState<string | null>(null)
  const [aiConfiguration, setAiConfiguration] = useState<AIConfiguration | null>(null)
  const [isFullyLoaded, setIsFullyLoaded] = useState(false)

  const [apiBaseUrl, setApiBaseUrl] = useState(tokenService.getCurrentApiBaseUrl())
  const [token, setToken] = useState(tokenService.getCurrentToken())

  useEffect(() => {
    const initializeCredentials = async () => {
      try {
        if (!apiBaseUrl) {
          await tokenService.initApiUrl()
          setApiBaseUrl(tokenService.getCurrentApiBaseUrl())
        }

        if (!token) {
          await tokenService.requestToken()
          setToken(tokenService.getCurrentToken())
        }
      } catch (error) {
        console.error('Failed to initialize credentials:', error)
      }
    }

    initializeCredentials()
  }, [apiBaseUrl, token])

  useEffect(() => {
    const unsubscribeToken = tokenService.onTokenUpdate(setToken)
    const unsubscribeApiUrl = tokenService.onApiUrlUpdate(setApiBaseUrl)

    return () => {
      unsubscribeToken()
      unsubscribeApiUrl()
    }
  }, [])

  useEffect(() => {
    if (apiBaseUrl) {
      setServerUrl(apiBaseUrl.replace(/^https?:\/\//, ''))
    }
  }, [apiBaseUrl])

  useEffect(() => {
    const loadAiConfiguration = async () => {
      try {
        const currentApiBaseUrl = tokenService.getCurrentApiBaseUrl()
        const currentToken = tokenService.getCurrentToken()

        if (!currentApiBaseUrl || !currentToken) {
          return
        }

        const response = await fetch(`${currentApiBaseUrl}/chat/api/v1/ai-configuration`, {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${currentToken}`
          },
          signal: AbortSignal.timeout(5000)
        })

        if (response && response.ok) {
          const config = await response.json()
          setAiConfiguration(config)

          await supportedModelsService.loadSupportedModels()
          setIsFullyLoaded(true)
        }
      } catch (error) {
        console.error('Failed to load AI configuration:', error)
      }
    }

    loadAiConfiguration()
  }, [apiBaseUrl, token])

  const getNatsWsUrl = useMemo(() => {
    return (): string => {
      if (!apiBaseUrl || !token) return ''
      return buildNatsWsUrl(apiBaseUrl, { token, includeAuthParam: true })
    }
  }, [apiBaseUrl, token])

  const clientConfig = useMemo(() => ({
    name: 'openframe-chat-status',
    user: 'machine',
    pass: ''
  }), [])

  const { isConnected } = useNatsDialogSubscription({
    enabled: !!apiBaseUrl && !!token,
    dialogId: null, // No dialog subscription, just connection monitoring
    topics: [],
    onConnect: () => {
      setStatus('connected')
    },
    onDisconnect: () => {
      setStatus('disconnected')
    },
    getNatsWsUrl,
    clientConfig
  })

  useEffect(() => {
    if (!apiBaseUrl || !token) {
      setStatus('connecting')
      return
    }

    if (isConnected) {
      setStatus('connected')
    } else {
      setStatus('disconnected')
    }
  }, [isConnected, apiBaseUrl, token])

  const displayUrl = serverUrl?.replace(/^https?:\/\//, '') || null

  return { status, serverUrl: displayUrl, aiConfiguration, isFullyLoaded }
}

class ChatApiService {
  private dialogId: string | null = null
  private debugMode: boolean
  private tokenUnsubscribe?: () => void
  private apiUrlUnsubscribe?: () => void
  private dialogIdListeners: Set<(dialogId: string | null) => void> = new Set()

  constructor(debug: boolean = false) {
    this.debugMode = debug

    this.tokenUnsubscribe = tokenService.onTokenUpdate(() => {
      if (this.debugMode) {
        console.log('[ChatApiService] Token updated via listener')
      }
    })

    this.apiUrlUnsubscribe = tokenService.onApiUrlUpdate((apiUrl) => {
      if (this.debugMode) {
        console.log('[ChatApiService] API URL updated:', apiUrl)
      }
    })
  }

  onDialogIdUpdate(callback: (dialogId: string | null) => void): () => void {
    this.dialogIdListeners.add(callback)
    try {
      callback(this.dialogId)
    } catch {
      // ignore callback errors
    }
    return () => {
      this.dialogIdListeners.delete(callback)
    }
  }

  setDialogId(dialogId: string | null) {
    if (this.dialogId === dialogId) return
    this.dialogId = dialogId
    for (const listener of this.dialogIdListeners) {
      try {
        listener(dialogId)
      } catch {
        // ignore listener failures
      }
    }
  }

  private getApiBaseUrl(): string {
    return tokenService.getCurrentApiBaseUrl() || ''
  }

  private getHeaders(): HeadersInit {
    const token = tokenService.getCurrentToken()

    return {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    }
  }

  async createDialog(): Promise<string> {
    await tokenService.ensureTokenReady()

    const url = `${this.getApiBaseUrl()}/chat/api/v1/dialogs`
    const response = await fetch(url, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({}),
    }).catch((err) => {
      if (this.debugMode) {
        throw new Error(`Network error creating dialog: ${err.message}\nURL: ${url}`)
      }
      throw err
    })

    if (!response.ok) {
      const errorText = (await response.json().catch(() => response.statusText))?.message;
      throw new Error(`Failed to create dialog: ${errorText}`)
    }

    const parsed = (await response.json().catch(() => ({}))) as CreateDialogResponse
    const id = parsed?.id || parsed?.dialogId
    if (!id) {
      throw new Error('Failed to create dialog: response did not include "id"')
    }

    this.setDialogId(id)
    return id
  }

  async sendMessage(args: { dialogId: string; content: string; chatType: 'CLIENT_CHAT' }): Promise<void> {
    await tokenService.ensureTokenReady()

    const url = `${this.getApiBaseUrl()}/chat/api/v1/messages`
    const response = await fetch(url, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify(args),
    }).catch((err) => {
      if (this.debugMode) {
        throw new Error(`Network error sending message: ${err.message}\nURL: ${url}\nDialog ID: ${args.dialogId}`)
      }
      throw err
    })

    if (!response.ok) {
      const errorText = await response.text().catch(() => response.statusText)
      throw new Error(`Failed to send message: ${response.status} ${response.statusText}\n${errorText}`)
    }
  }

  setDebugMode(enabled: boolean) {
    this.debugMode = enabled
  }

  reset() {
    this.setDialogId(null)
  }

  getDialogId(): string | null {
    return this.dialogId
  }

  destroy() {
    if (this.tokenUnsubscribe) {
      this.tokenUnsubscribe()
    }
    if (this.apiUrlUnsubscribe) {
      this.apiUrlUnsubscribe()
    }
  }
}

