function useChatsOverview() {
  const [stats, setStats] = useState(() => ({
    total: 0,
    active: 0,
    resolved: 0,
    avgResolveTime: '—',
    avgFaeRate: 0,
    activePercentage: 0,
    resolvedPercentage: 0
  }))

  useEffect(() => {
    let isMounted = true

    type DialogStatistics = {
      dialogStatistics: {
        totalCount: number
        statusCounts: Array<{ status: string; count: number }>
        averageResolutionTimeFormatted: string
        averageRating: number
      }
    }

    const fetchStats = async () => {
      try {
        const res: { ok: boolean, status: number, error?: string, data?: GraphQLResponse<DialogStatistics> } = await apiClient.post<GraphQLResponse<DialogStatistics>>('/chat/graphql', {
          query: GET_DIALOG_STATISTICS_QUERY
        })

        if (!res.ok) {
          throw new Error(res.error || `Request failed with status ${res.status}`)
        }

        const data = res.data?.data?.dialogStatistics
        if (!data) return

        const total = data.totalCount || 0
        const active = (data.statusCounts || [])
          .filter(s => (s.status || '').toUpperCase() === 'ACTIVE')
          .reduce((sum, s) => sum + (s.count || 0), 0)
        const resolved = (data.statusCounts || [])
          .filter(s => (s.status || '').toUpperCase() === 'RESOLVED')
          .reduce((sum, s) => sum + (s.count || 0), 0)

        if (!isMounted) return

        setStats({
          total,
          active,
          resolved,
          avgResolveTime: data.averageResolutionTimeFormatted || '—',
          avgFaeRate: typeof data.averageRating === 'number' ? Number(data.averageRating.toFixed(1)) : 0,
          activePercentage: total > 0 ? Math.round((active / total) * 100) : 0,
          resolvedPercentage: total > 0 ? Math.round((resolved / total) * 100) : 0,
        })
      } catch (_) {
        // keep defaults on error
      }
    }

    fetchStats()
    return () => { isMounted = false }
  }, [])

  return stats
}

function useDevicesOverview() {
  const [stats, setStats] = useState(() => ({
    total: 0,
    active: 0,
    inactive: 0,
    activePercentage: 0,
    inactivePercentage: 0
  }))
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    let isMounted = true
    setIsLoading(true)

    const fetchStatusCounts = async () => {
      try {
        type DeviceFiltersResponse = { deviceFilters: { filteredCount: number, statuses?: Array<{ value: string, count: number }> } }

        const devRes: { ok: boolean, status: number, error?: string, data?: GraphQLResponse<DeviceFiltersResponse> } = await apiClient.post<GraphQLResponse<DeviceFiltersResponse>>('/api/graphql', {
          query: GET_DEVICE_FILTERS_QUERY,
          variables: { filter: { statuses: [...DEFAULT_VISIBLE_STATUSES] } }
        })

        if (!devRes.ok) {
          throw new Error(devRes.error || `Request failed with status ${devRes.status}`)
        }

        const total = devRes.data?.data?.deviceFilters?.filteredCount || 0
        const statuses = devRes.data?.data?.deviceFilters?.statuses || []
        const active = statuses
          .filter(s => ['ONLINE'].includes((s.value || '').toUpperCase()))
          .reduce((sum, s) => sum + (s.count || 0), 0)
        const inactive = Math.max(0, total - active)

        if (!isMounted) return

        setStats({
          total,
          active,
          inactive,
          activePercentage: total > 0 ? Math.round((active / total) * 100) : 0,
          inactivePercentage: total > 0 ? Math.round((inactive / total) * 100) : 0
        })
      } catch (err) {
        // Swallow errors for now; keep zeros. Dashboard can still render.
      } finally {
        if (isMounted) {
          setIsLoading(false)
        }
      }
    }

    fetchStatusCounts()
    return () => { isMounted = false }
  }, [])

  return { ...stats, isLoading }
}

function useLogsOverview() {
  const [stats, setStats] = useState(() => ({
    total: 0,
    info: 0,
    warning: 0,
    critical: 0,
    infoPercentage: 0,
    warningPercentage: 0,
    criticalPercentage: 0
  }))

  useEffect(() => {
    let isMounted = true

    const fetchSeverityCounts = async () => {
      try {
        const normalize = (v: string) => v?.toUpperCase?.() || v

        type LogEdge = { node: { severity?: string } }
        type PageInfo = { hasNextPage: boolean, endCursor?: string | null }
        type LogsResponse = { logs: { edges: LogEdge[], pageInfo: PageInfo } }

        const pageLimit = 50
        let cursor: string | null | undefined = null
        let hasNext = true
        let total = 0
        let info = 0
        let warning = 0
        let critical = 0
        let safetyPages = 50

        while (hasNext && safetyPages > 0) {
          const logsRes: { ok: boolean, status: number, error?: string, data?: GraphQLResponse<LogsResponse> } = await apiClient.post<GraphQLResponse<LogsResponse>>('/api/graphql', {
            query: GET_LOGS_QUERY,
            variables: {
              filter: {},
              pagination: { limit: pageLimit, cursor },
              search: ''
            }
          })

          if (!logsRes.ok) {
            throw new Error(logsRes.error || `Request failed with status ${logsRes.status}`)
          }

          const data: LogsResponse | undefined = logsRes.data?.data
          if (!data) break

          const edges: LogEdge[] = data.logs.edges || []
          total += edges.length

          for (const e of edges) {
            const sev = normalize(e?.node?.severity || '')
            if (sev === 'INFO') info += 1
            else if (sev === 'WARNING') warning += 1
            else if (sev === 'CRITICAL') critical += 1
          }

          hasNext = !!data.logs.pageInfo?.hasNextPage
          cursor = data.logs.pageInfo?.endCursor || null
          safetyPages -= 1
        }

        if (!isMounted) return

        setStats({
          total,
          info,
          warning,
          critical,
          infoPercentage: total > 0 ? Math.round((info / total) * 100) : 0,
          warningPercentage: total > 0 ? Math.round((warning / total) * 100) : 0,
          criticalPercentage: total > 0 ? Math.round((critical / total) * 100) : 0
        })
      } catch (err) {
        // keep zeros if request fails
      }
    }

    fetchSeverityCounts()
    return () => { isMounted = false }
  }, [])

  return stats
}

function useOnboardingCompletion() {
  // Use existing hooks to get data
  const { organizations, isLoading: orgsLoading, fetchOrganizations } = useOrganizations({})
  const { total: deviceCount, isLoading: devicesLoading } = useDevicesOverview()
  // useUsers now uses react-query and automatically fetches data
  const { totalElements, isLoading: usersLoading } = useUsers(0, 10)
  const { fetchAvailableProviders, fetchProviderConfig } = useSsoConfig()

  const [ssoProvidersCount, setSsoProvidersCount] = useState(0)
  const [ssoLoading, setSsoLoading] = useState(true) // Start as true to indicate initial load

  // Refs to prevent duplicate fetches and track mount state
  const ssoFetchedRef = useRef(false)
  const orgsFetchedRef = useRef(false)
  const isMountedRef = useRef(true)

  // Stable callback for SSO fetch
  const fetchSsoProviders = useCallback(async () => {
    if (ssoFetchedRef.current) return
    ssoFetchedRef.current = true

    setSsoLoading(true)
    try {
      const providers = await fetchAvailableProviders()

      if (!isMountedRef.current) return

      // Fetch config for each provider to check enabled status
      const configs = await Promise.all(
        providers.map(p => fetchProviderConfig(p.provider))
      )

      if (!isMountedRef.current) return

      // Count only providers that are enabled
      const activeCount = configs.filter(cfg => cfg?.enabled === true).length
      setSsoProvidersCount(activeCount)
      console.log('✓ SSO providers loaded:', providers.length, 'active:', activeCount)
    } catch (err) {
      console.error('SSO providers fetch failed:', err)
      if (isMountedRef.current) {
        setSsoProvidersCount(0)
      }
    } finally {
      if (isMountedRef.current) {
        setSsoLoading(false)
      }
    }
  }, [fetchAvailableProviders, fetchProviderConfig])

  // Stable callback for organizations fetch
  const fetchOrgsOnce = useCallback(async () => {
    if (orgsFetchedRef.current) return
    orgsFetchedRef.current = true

    try {
      await fetchOrganizations('', null, {})
    } catch (err) {
      console.error('Organizations fetch failed:', err)
    }
  }, [fetchOrganizations])

  // Fetch SSO providers once on mount
  useEffect(() => {
    fetchSsoProviders()
  }, [fetchSsoProviders])

  // Fetch organizations once on mount
  useEffect(() => {
    fetchOrgsOnce()
  }, [fetchOrgsOnce])

  // Cleanup on unmount
  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
    }
  }, [])

  // Combined loading state - includes all data sources
  const isLoading = orgsLoading || devicesLoading || usersLoading || ssoLoading

  // Memoize completion status to prevent unnecessary re-renders and recalculations
  const completionStatus = useMemo(() => ({
    'sso-configuration': ssoProvidersCount > 0,
    'organizations-setup': organizations.length > 1,
    'device-management': deviceCount > 0,
    'company-and-team': totalElements > 1
  }), [ssoProvidersCount, organizations.length, deviceCount, totalElements])

  // Log completion status only when loading completes
  useEffect(() => {
    if (!isLoading) {
      console.log('📊 Onboarding completion status:', completionStatus)
      console.log('📊 Raw values - orgs:', organizations.length, 'users:', totalElements, 'devices:', deviceCount, 'sso:', ssoProvidersCount)
    }
  }, [isLoading, completionStatus, organizations.length, totalElements, deviceCount, ssoProvidersCount])

  return {
    completionStatus,
    isLoading
  }
}

