function DevicesView() {
  const router = useRouter()

  // Extra URL params not handled by cursor pagination hook (viewMode and filters)
  const { params: extraParams, setParam: setExtraParam, setParams: setExtraParams } = useApiParams({
    statuses: { type: 'array', default: [] },
    osTypes: { type: 'array', default: [] },
    organizationIds: { type: 'array', default: [] },
    viewMode: { type: 'string', default: 'table' }
  })

  // Backend filters from URL params (default excludes ARCHIVED and DELETED)
  const filters = useMemo(() => ({
    statuses: extraParams.statuses.length > 0 ? extraParams.statuses : DEFAULT_VISIBLE_STATUSES,
    osTypes: extraParams.osTypes,
    organizationIds: extraParams.organizationIds
  }), [extraParams.statuses, extraParams.osTypes, extraParams.organizationIds])

  const { devices, deviceFilters, isLoading, error, searchDevices, pageInfo, fetchNextPage, fetchFirstPage, hasLoadedBeyondFirst, setHasLoadedBeyondFirst, fetchDevices, fetchDeviceFilters, markInitialLoadDone } = useDevices(filters)

  // Unified cursor pagination state management (no prefix, uses 'search' and 'cursor')
  const {
    searchInput,
    setSearchInput,
    hasLoadedBeyondFirst: hookHasLoadedBeyondFirst,
    handleNextPage,
    handleResetToFirstPage,
    params: paginationParams,
    setParams: setPaginationParams
  } = useCursorPaginationState({
    onInitialLoad: (search, cursor) => {
      if (cursor) {
        fetchDevices(search, cursor)
        setHasLoadedBeyondFirst(true)
      } else {
        fetchDevices(search)
      }
      fetchDeviceFilters()
      markInitialLoadDone()
    },
    onSearchChange: (search) => searchDevices(search)
  })

  const organizationImageUrls = useMemo(() =>
    featureFlags.organizationImages.displayEnabled()
      ? devices.map(device => device.organizationImageUrl).filter(Boolean)
      : [],
    [devices]
  )
  const fetchedImageUrls = useBatchImages(organizationImageUrls)

  const columns = useMemo(() => getDeviceTableColumns(deviceFilters, fetchedImageUrls), [deviceFilters, fetchedImageUrls])

  // Refresh callback for after archive/delete actions
  const refreshDevices = useCallback(() => {
    fetchDevices(paginationParams.search)
  }, [fetchDevices, paginationParams.search])

  const renderRowActions = useMemo(
    () => getDeviceTableRowActions(refreshDevices),
    [refreshDevices]
  )

  // Navigate to device details on row click
  const handleRowClick = useCallback((device: Device) => {
    const id = device.machineId || device.id
    router.push(`/devices/details/${id}`)
  }, [router])

  const handleFilterChange = useCallback((columnFilters: Record<string, any[]>) => {
    // Reset cursor and update filter params
    setPaginationParams({ cursor: '' })
    setExtraParams({
      statuses: columnFilters.status || [],
      osTypes: columnFilters.os || [],
      organizationIds: columnFilters.organization || []
    })
    setHasLoadedBeyondFirst(false)
  }, [setExtraParams, setPaginationParams, setHasLoadedBeyondFirst])

  const onNext = useCallback(async () => {
    if (pageInfo?.hasNextPage && pageInfo?.endCursor) {
      await handleNextPage(pageInfo.endCursor, () => fetchNextPage(paginationParams.search))
    }
  }, [pageInfo, handleNextPage, fetchNextPage, paginationParams.search])

  const onReset = useCallback(async () => {
    await handleResetToFirstPage(() => fetchFirstPage(paginationParams.search))
  }, [handleResetToFirstPage, fetchFirstPage, paginationParams.search])

  const cursorPagination = useTablePagination(
    pageInfo ? {
      type: 'server',
      hasNextPage: pageInfo.hasNextPage,
      hasLoadedBeyondFirst: hasLoadedBeyondFirst || hookHasLoadedBeyondFirst,
      startCursor: pageInfo.startCursor,
      endCursor: pageInfo.endCursor,
      itemCount: devices.length,
      itemName: 'devices',
      onNext,
      onReset,
      showInfo: true
    } : null
  )

  // Convert URL params to table filters format
  const tableFilters = useMemo(() => ({
    status: extraParams.statuses,
    os: extraParams.osTypes,
    organization: extraParams.organizationIds
  }), [extraParams.statuses, extraParams.osTypes, extraParams.organizationIds])

  const viewToggle = (
    <>
      <ViewToggle
        value={extraParams.viewMode as 'table' | 'grid'}
        onValueChange={(value) => setExtraParam('viewMode', value)}
        className="bg-ods-card border border-ods-border h-12"
      />
      <Button
        onClick={() => router.push('/devices/new')}
        leftIcon={<PlusCircleIcon className="w-5 h-5" whiteOverlay/>}
        className="bg-ods-card border border-ods-border hover:bg-ods-bg-hover text-ods-text-primary px-4 py-2.5 rounded-[6px] font-['DM_Sans'] font-bold text-[16px] h-12"
      >
        Add Device
      </Button>
    </>
  )

  const filterGroups = columns.filter(column => column.filterable).map(column => ({
    id: column.key,
    title: column.label,
    options: column.filterOptions || []
  }))

  return (
    <ListPageLayout
      title="Devices"
      headerActions={viewToggle}
      searchPlaceholder="Search for Devices"
      searchValue={searchInput}
      onSearch={setSearchInput}
      error={error}
      padding="none"
      className="pt-6"
      onMobileFilterChange={handleFilterChange}
      mobileFilterGroups={filterGroups}
      currentMobileFilters={tableFilters}
    >
      {/* Conditional View Rendering */}
      {extraParams.viewMode === 'table' ? (
        // Table View
        <Table
          data={devices}
          columns={columns}
          rowKey="machineId"
          loading={isLoading}
          skeletonRows={10}
          emptyMessage="No devices found. Try adjusting your search or filters."
          onRowClick={handleRowClick}
          renderRowActions={renderRowActions}
          filters={tableFilters}
          onFilterChange={handleFilterChange}
          showFilters={true}
          rowClassName="mb-1"
          cursorPagination={cursorPagination}
        />
      ) : (
        // Grid View
        <DevicesGrid
          devices={devices}
          isLoading={isLoading}
          filters={filters}
        />
      )}
    </ListPageLayout>
  )
}

function RemoteShellModal({ isOpen, onClose, deviceId, deviceLabel, shellType = 'cmd' }: RemoteShellModalProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const termRef = useRef<any | null>(null)
  const fitRef = useRef<any | null>(null)
  const tunnelRef = useRef<MeshTunnel | null>(null)
  const [state, setState] = useState<TunnelState>(0)
  const [connecting, setConnecting] = useState(false)
  const [hasReceivedData, setHasReceivedData] = useState(false)
  const powershellCommandSentRef = useRef(false)
  const { toast } = useToast()

  useEffect(() => {
    if (!isOpen) return

    let isDisposed = false

    ;(async () => {
      const [{ Terminal }, { FitAddon }] = await Promise.all([
        import('xterm'),
        import('xterm-addon-fit')
      ])

      if (isDisposed) return

      const term = new Terminal({
        fontFamily: 'monospace',
        theme: { background: '#000000' },
        cursorBlink: true
      })
      const fit = new FitAddon()
      term.loadAddon(fit)
      term.open(containerRef.current!)
      fit.fit()
      term.focus()
      termRef.current = term
      fitRef.current = fit

      const handleResize = () => {
        try { fit.fit() } catch {}
        if (tunnelRef.current && termRef.current) {
          tunnelRef.current.sendCtrl({ ctrlChannel: 102938, type: 'termsize', cols: term.cols, rows: term.rows })
        }
      }
      window.addEventListener('resize', handleResize)
      const disposeResize = term.onResize(() => handleResize)
      const disposeData = term.onData((d: string) => tunnelRef.current?.sendBinary(new TextEncoder().encode(d)))

      const cleanup = () => {
        window.removeEventListener('resize', handleResize)
        disposeResize.dispose()
        disposeData.dispose()
        tunnelRef.current?.stop()
        term.dispose()
        termRef.current = null
        fitRef.current = null
      }

      ;(cleanup as any).assigned = true
      ;(termRef as any).cleanup = cleanup
    })()

    return () => {
      isDisposed = true
      const assignedCleanup = (termRef as any).cleanup as (() => void) | undefined
      if (assignedCleanup) assignedCleanup()
    }
  }, [isOpen])

  useEffect(() => {
    if (state === 3 && shellType === 'powershell' && hasReceivedData && !powershellCommandSentRef.current && tunnelRef.current) {
      setTimeout(() => {
        if (tunnelRef.current && !powershellCommandSentRef.current) {
          tunnelRef.current.sendBinary(new TextEncoder().encode(WINDOWS_POWERSHELL_CMD + '\r'))
          powershellCommandSentRef.current = true
        }
      }, 100)
    }
  }, [state, shellType, hasReceivedData])

  useEffect(() => {
    if (!isOpen) {
      powershellCommandSentRef.current = false
      setHasReceivedData(false)
    }
  }, [isOpen])

  useEffect(() => {
    if (!isOpen) return
    let control: MeshControlClient | undefined
    ;(async () => {
      setConnecting(true)
      try {
        control = new MeshControlClient()
        const { authCookie } = await control.getAuthCookies()
        const term = termRef.current
        if (!term) throw new Error('Terminal not initialized')
        const tunnel = new MeshTunnel({
          authCookie,
          nodeId: deviceId,
          protocol: 1,
          options: { cols: term.cols, rows: term.rows },
          onData: (data) => {
            setHasReceivedData(true)
            if (typeof data === 'string') term.write(data)
            else term.write(new TextDecoder().decode(data))
          },
          onCtrlMessage: () => {},
          onConsoleMessage: (msg) => {
            toast({ title: 'Remote Shell', description: msg, variant: 'default' })
          },
          onRequestPairing: async (relayId) => {
            try {
              if (!control) return
              await control.openSession()
              control.sendRelayTunnel(deviceId, relayId, 1)
            } catch {}
          },
          onStateChange: (s) => setState(s)
        })
        tunnelRef.current = tunnel
        try {
          await control.openSession()
        } catch {}
        tunnel.start()
      } catch (e) {
        toast({ title: 'Remote Shell failed', description: (e as Error).message, variant: 'destructive' })
      } finally {
        setConnecting(false)
      }
    })()
    return () => { control?.close() }
  }, [isOpen, deviceId, toast])

  if (!isOpen) return null

  const statusText = state === 3 ? 'Connected' : state === 2 ? 'Open' : state === 1 ? 'Connecting' : 'Idle'

  return (
    <div className="absolute top-0 left-0 right-0 bottom-0 z-40 max-h-[90vh] overflow-hidden">
      <div className="absolute top-0 left-0 right-0 bottom-0 bg-ods-card flex flex-col p-4 gap-4 max-h-[90vh]">
        <div className="flex items-center justify-between">
          <div className="flex flex-col">
            <h2 className="font-['Azeret_Mono'] font-semibold text-[20px] text-ods-text-primary tracking-[-0.4px]">
              Remote Shell {shellType === 'powershell' ? '(PowerShell)' : ''} {deviceLabel ? `- ${deviceLabel}` : ''}
            </h2>
            <div className="text-ods-text-secondary text-sm">{statusText}{connecting ? '…' : ''}</div>
          </div>
          <div className="flex items-center gap-2">
            <Button
              onClick={() => tunnelRef.current?.stop()}
              variant="outline"
              className="bg-ods-card border border-ods-border text-ods-text-primary"
              disabled={state !== 3}
            >
              Disconnect
            </Button>
            <Button
              onClick={onClose}
              variant="ghost"
              className="text-ods-text-secondary hover:text-white p-1"
            >
              <X className="h-6 w-6" />
            </Button>
          </div>
        </div>
        <div className="flex-1 min-h-0 bg-black rounded overflow-hidden">
          <div ref={containerRef} className="w-full h-full" />
        </div>
      </div>
    </div>
  )
}

