function RemoteSettingsModal({
  open,
  onOpenChange,
  currentSettings,
  desktopRef,
  tunnelRef,
  connectionState,
  onSettingsChange
}: RemoteSettingsModalProps) {
  const { toast } = useToast()
  const [settings, setSettings] = useState<RemoteSettingsConfig>(currentSettings)

  useEffect(() => {
    setSettings(currentSettings)
  }, [currentSettings])

  const handleSaveSettings = () => {
    if (!tunnelRef.current || connectionState !== 3) {
      toast({
        title: 'Connection Required',
        description: 'Please wait for the remote desktop connection to establish',
        variant: 'destructive'
      })
      return
    }

    try {
      const settingsManager = new RemoteDesktopSettings(settings)
      settingsManager.setWebSocket(tunnelRef.current)
      settingsManager.applySettings(settings)

      if (desktopRef.current) {
        desktopRef.current.setSwapMouseButtons?.(settings.swapMouseButtons)
        desktopRef.current.setUseRemoteKeyboardMap?.(settings.useRemoteKeyboardMap)
      }

      onSettingsChange?.(settings)

      toast({
        title: 'Settings Applied',
        description: `Remote control settings updated. Est. bandwidth: ${settingsManager.estimateBandwidth()} KB/s`,
        variant: 'success',
        duration: 3000
      })

      onOpenChange(false)
    } catch (error) {
      toast({
        title: 'Settings Failed',
        description: 'Unable to apply remote control settings',
        variant: 'destructive'
      })
    }
  }

  const handleClose = () => {
    setSettings(currentSettings)
    onOpenChange(false)
  }

  return (
    <Modal isOpen={open} onClose={handleClose}

interface UseDeviceActionsOptions {
  onSuccess?: () => void
}

function useDeviceActions(options?: UseDeviceActionsOptions) {
  const { toast } = useToast()
  const [isArchiving, setIsArchiving] = useState(false)
  const [isDeleting, setIsDeleting] = useState(false)

  const archiveDevice = useCallback(async (deviceId: string, deviceName?: string): Promise<boolean> => {
    setIsArchiving(true)
    try {
      const response = await apiClient.patch(`/api/devices/${deviceId}`, {
        status: 'ARCHIVED'
      })

      if (!response.ok) {
        throw new Error(response.error || 'Failed to archive device')
      }

      toast({
        title: 'Device archived',
        description: `${deviceName || deviceId} has been archived`
      })

      options?.onSuccess?.()
      return true
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to archive device'
      toast({
        title: 'Archive failed',
        description: errorMessage,
        variant: 'destructive'
      })
      return false
    } finally {
      setIsArchiving(false)
    }
  }, [toast, options])

  const deleteDevice = useCallback(async (deviceId: string, deviceName?: string): Promise<boolean> => {
    setIsDeleting(true)
    try {
      const response = await apiClient.patch(`/api/devices/${deviceId}`, {
        status: 'DELETED'
      })

      if (!response.ok) {
        throw new Error(response.error || 'Failed to delete device')
      }

      toast({
        title: 'Device deleted',
        description: `${deviceName || deviceId} has been deleted`
      })

      options?.onSuccess?.()
      return true
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to delete device'
      toast({
        title: 'Delete failed',
        description: errorMessage,
        variant: 'destructive'
      })
      return false
    } finally {
      setIsDeleting(false)
    }
  }, [toast, options])

  return {
    archiveDevice,
    deleteDevice,
    isArchiving,
    isDeleting,
    isProcessing: isArchiving || isDeleting
  }
}

function createDevice(
  node: DeviceGraphQLNode,
  tacticalData: any | null,
  fleetData: FleetHost | null
): Device {
  // Transform Fleet software to unified Software type
  const software: Software[] = fleetData?.software?.map(fs => ({
    id: fs.id,
    name: fs.name,
    version: fs.version,
    source: fs.source,
    vendor: fs.vendor || undefined,  // Normalize null to undefined
    bundle_identifier: fs.bundle_identifier,
    vulnerabilities: (fs.vulnerabilities || []).map(v => ({
      cve: v.cve,
      details_link: v.details_link,
      created_at: v.created_at
    })),
    installed_paths: fs.installed_paths,
    last_opened_at: fs.last_opened_at
  })) || []

  // Transform Fleet batteries to unified Battery type
  const batteries: Battery[] = fleetData?.batteries?.map(fb => ({
    cycle_count: fb.cycle_count,
    health: fb.health
  })) || []

  // Transform Fleet users to unified User type
  const users: User[] = fleetData?.users?.map(fu => ({
    username: fu.username,
    uid: fu.uid,
    type: fu.type,
    groupname: fu.groupname,
    shell: fu.shell,
    isLoggedIn: fu.type === 'person'
  })) || []

  // Transform Fleet MDM to unified MDMInfo type
  const mdm: MDMInfo | undefined = fleetData?.mdm ? {
    enrollment_status: fleetData.mdm.enrollment_status,
    server_url: fleetData.mdm.server_url,
    name: fleetData.mdm.name,
    encryption_key_available: fleetData.mdm.encryption_key_available,
    device_status: fleetData.mdm.device_status,
    pending_action: fleetData.mdm.pending_action,
    connected_to_fleet: fleetData.mdm.connected_to_fleet
  } : undefined

  // Helper to check if IP is private
  const isPrivateIP = (ip: string): boolean => {
    if (!ip) return false
    if (ip.startsWith('10.')) return true
    if (ip.startsWith('172.')) {
      const second = parseInt(ip.split('.')[1])
      if (second >= 16 && second <= 31) return true
    }
    if (ip.startsWith('192.168.')) return true
    if (ip.startsWith('127.')) return true
    if (ip.startsWith('169.254.')) return true
    if (ip.startsWith('fe80:')) return true
    if (ip.startsWith('fc00:') || ip.startsWith('fd00:')) return true
    if (ip === '::1') return true
    return false
  }

  // Determine actual public IP (filter private IPs)
  let actualPublicIP = ''
  if (fleetData?.public_ip && !isPrivateIP(fleetData.public_ip)) {
    actualPublicIP = fleetData.public_ip
  } else if (tacticalData?.public_ip && !isPrivateIP(tacticalData.public_ip)) {
    actualPublicIP = tacticalData.public_ip
  }

  // Merge ALL IPs from Fleet and Tactical into unified array
  const local_ips: string[] = []
  const seenIps = new Set<string>()

  // Add Fleet primary_ip first (local IP)
  if (fleetData?.primary_ip && !seenIps.has(fleetData.primary_ip)) {
    local_ips.push(fleetData.primary_ip)
    seenIps.add(fleetData.primary_ip)
  }

  // Add Fleet public_ip if actually public
  if (fleetData?.public_ip && !isPrivateIP(fleetData.public_ip) && !seenIps.has(fleetData.public_ip)) {
    local_ips.push(fleetData.public_ip)
    seenIps.add(fleetData.public_ip)
  }

  // Add Node IP
  if (node.ip && !seenIps.has(node.ip)) {
    local_ips.push(node.ip)
    seenIps.add(node.ip)
  }

  // Add Tactical IPs
  if (tacticalData?.wmi_detail?.local_ips) {
    tacticalData.wmi_detail.local_ips.forEach((ip: string) => {
      if (!seenIps.has(ip)) {
        local_ips.push(ip)
        seenIps.add(ip)
      }
    })
  }
  if (tacticalData?.local_ips) {
    tacticalData.local_ips.split(',').map((ip: string) => ip.trim()).filter(Boolean).forEach((ip: string) => {
      if (!seenIps.has(ip)) {
        local_ips.push(ip)
        seenIps.add(ip)
      }
    })
  }
  if (tacticalData?.public_ip && !seenIps.has(tacticalData.public_ip)) {
    local_ips.push(tacticalData.public_ip)
    seenIps.add(tacticalData.public_ip)
  }

  // Extract logged in user
  const loggedUser = users.find(u => u.isLoggedIn) || users[0]

  return {
    // Core Identifiers
    id: node.id,
    machineId: node.machineId,
    hostname: fleetData?.hostname || node.hostname || tacticalData?.hostname,
    displayName: node.displayName || fleetData?.display_name || node.hostname || tacticalData?.description,

    // Hardware - CPU
    cpu_brand: fleetData?.cpu_brand,
    cpu_type: fleetData?.cpu_type,
    cpu_subtype: fleetData?.cpu_subtype,
    cpu_physical_cores: fleetData?.cpu_physical_cores,
    cpu_logical_cores: fleetData?.cpu_logical_cores,

    // Hardware - Memory
    memory: fleetData?.memory,
    totalRam: fleetData?.memory ? `${(fleetData.memory / (1024 ** 3)).toFixed(2)} GB` : tacticalData?.total_ram,
    total_ram: fleetData?.memory ? `${(fleetData.memory / (1024 ** 3)).toFixed(2)} GB` : tacticalData?.total_ram,

    // Hardware - Identifiers
    hardware_serial: fleetData?.hardware_serial,
    hardware_vendor: fleetData?.hardware_vendor,
    hardware_model: fleetData?.hardware_model,
    hardware_version: fleetData?.hardware_version,
    serial_number: fleetData?.hardware_serial || node.serialNumber || tacticalData?.serial_number,
    manufacturer: fleetData?.hardware_vendor || node.manufacturer || tacticalData?.make_model?.split('\n')[0],
    model: fleetData?.hardware_model || node.model || tacticalData?.make_model?.trim(),
    make_model: fleetData?.hardware_model || tacticalData?.make_model || [node.manufacturer, node.model].filter(Boolean).join(' '),

    // Storage
    gigs_disk_space_available: fleetData?.gigs_disk_space_available,
    percent_disk_space_available: fleetData?.percent_disk_space_available,
    gigs_total_disk_space: fleetData?.gigs_total_disk_space,
    disk_encryption_enabled: fleetData?.disk_encryption_enabled,
    disks: tacticalData?.disks,
    physical_disks: tacticalData?.physical_disks,

    // Network
    primary_ip: fleetData?.primary_ip,
    primary_mac: fleetData?.primary_mac,
    public_ip: actualPublicIP,
    local_ips,
    ip: fleetData?.primary_ip || node.ip || local_ips[0],
    macAddress: fleetData?.primary_mac || node.macAddress,

    // System Status
    status: node.status || fleetData?.status || tacticalData?.status || 'UNKNOWN',
    uptime: fleetData?.uptime,
    last_seen: fleetData?.seen_time || node.lastSeen || tacticalData?.last_seen,
    lastSeen: fleetData?.seen_time || node.lastSeen || tacticalData?.last_seen,
    last_restarted_at: fleetData?.last_restarted_at,
    last_enrolled_at: fleetData?.last_enrolled_at,
    boot_time: fleetData?.last_restarted_at ? new Date(fleetData.last_restarted_at).getTime() / 1000 : (tacticalData?.boot_time || 0),

    // Operating System
    platform: fleetData?.platform,
    platform_like: fleetData?.platform_like,
    os_version: fleetData?.os_version,
    build: fleetData?.build,
    code_name: fleetData?.code_name,
    operating_system: fleetData?.platform || node.osType || tacticalData?.operating_system,
    osType: fleetData?.platform || node.osType || tacticalData?.operating_system,
    osVersion: fleetData?.os_version || node.osVersion || tacticalData?.version,
    osBuild: fleetData?.build || node.osBuild,

    // Software & Versions
    osquery_version: fleetData?.osquery_version,
    orbit_version: fleetData?.orbit_version,
    fleet_desktop_version: fleetData?.fleet_desktop_version,
    scripts_enabled: fleetData?.scripts_enabled,
    agentVersion: node.agentVersion || tacticalData?.version || fleetData?.osquery_version,
    version: node.agentVersion || tacticalData?.version || fleetData?.osquery_version,

    // Unified Arrays (NO NESTING)
    software,
    batteries,
    users,

    // MDM Info
    mdm,

    // Organization
    organizationId: node.organization?.organizationId,
    organization: node.organization?.name || tacticalData?.client_name,
    organizationImageUrl: node.organization?.image?.imageUrl || null,

    // Tags
    tags: node.tags || tacticalData?.custom_fields || [],

    // Tool Connections
    toolConnections: node.toolConnections,
    installedAgents: node.installedAgents,

    // Misc
    type: node.type || tacticalData?.monitoring_type,
    registeredAt: fleetData?.last_enrolled_at || node.registeredAt,
    updatedAt: fleetData?.detail_updated_at || fleetData?.seen_time || node.updatedAt || node.lastSeen || tacticalData?.last_seen,
    osUuid: fleetData?.uuid || node.osUuid,

    // Reference IDs
    fleetId: fleetData?.id,
    tacticalAgentId: tacticalData?.agent_id,
    agent_id: tacticalData?.agent_id || node.machineId || node.id,

    // Graphics
    graphics: tacticalData?.graphics,

    // Legacy fields
    serialNumber: fleetData?.hardware_serial || node.serialNumber || tacticalData?.serial_number,
    description: node.displayName || fleetData?.hostname || tacticalData?.description || node.hostname,
    plat: fleetData?.platform || node.osType || tacticalData?.operating_system,
    logged_in_username: loggedUser?.username || tacticalData?.logged_username,
    logged_username: loggedUser?.username || tacticalData?.logged_username,

    // Legacy tactical fields for compatibility
    cpu_model: fleetData?.cpu_brand ? [fleetData.cpu_brand] : (tacticalData?.cpu_model || []),
    site_name: tacticalData?.site_name || '',
    client_name: node.organization?.name || tacticalData?.client_name || '',
    monitoring_type: node.type || tacticalData?.monitoring_type || '',
    needs_reboot: tacticalData?.needs_reboot || false,
    pending_actions_count: tacticalData?.pending_actions_count || 0,
    overdue_text_alert: tacticalData?.overdue_text_alert || false,
    overdue_email_alert: tacticalData?.overdue_email_alert || false,
    overdue_dashboard_alert: tacticalData?.overdue_dashboard_alert || false,
    checks: tacticalData?.checks || { total: 0, passing: 0, failing: 0, warning: 0, info: 0, has_failing_checks: false },
    maintenance_mode: tacticalData?.maintenance_mode || false,
    italic: tacticalData?.italic || false,
    block_policy_inheritance: tacticalData?.block_policy_inheritance || false,
    goarch: tacticalData?.goarch || '',
    has_patches_pending: tacticalData?.has_patches_pending || false,
    custom_fields: tacticalData?.custom_fields || []
  }
}

function useDeviceDetails() {
  const { toast } = useToast()
  const [deviceDetails, setDeviceDetails] = useState<Device | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [lastUpdated, setLastUpdated] = useState<number | null>(null)
  const isPollingRef = useRef(false)

  const fetchDeviceById = useCallback(async (machineId: string, silent = false) => {
    if (!machineId) {
      setError('machineId is required')
      return
    }

    // Only show loading state for initial (non-silent) fetches
    if (!silent) {
      setIsLoading(true)
    }
    setError(null)

    try {
      // 1) Fetch primary device from GraphQL
      const response = await apiClient.post<GraphQLResponse<{ device: DeviceGraphQLNode }>>('/api/graphql', {
        query: GET_DEVICE_QUERY,
        variables: { machineId }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const graphqlResponse = response.data
      if (!graphqlResponse?.data?.device) {
        setDeviceDetails(null)
        setError('Device not found')
        return
      }
      if (graphqlResponse.errors && graphqlResponse.errors.length > 0) {
        throw new Error(graphqlResponse.errors[0].message || 'GraphQL error occurred')
      }

      const node = graphqlResponse.data.device

      // 2) Use toolConnections to fetch Tactical details if present
      const tactical = node.toolConnections?.find(tc => tc.toolType === 'TACTICAL_RMM')
      let tacticalData: any | null = null
      if (tactical?.agentToolId) {
        const tResponse = await tacticalApiClient.getAgent(tactical.agentToolId)
        if (tResponse.ok) {
          tacticalData = tResponse.data
        }
      }

      // 2.5) Fetch Fleet MDM details if present
      const fleet = node.toolConnections?.find(tc => tc.toolType === 'FLEET_MDM')
      let fleetData: any | null = null
      if (fleet?.agentToolId) {
        // Validate that agentToolId is a valid numeric string before calling Fleet API
        const fleetHostId = Number(fleet.agentToolId)
        if (Number.isInteger(fleetHostId) && fleetHostId > 0) {
          const fResponse = await fleetApiClient.getHost(fleetHostId)
          if (fResponse.ok && fResponse.data?.host) {
            fleetData = fResponse.data.host
          }
        } else {
          console.warn(`Invalid Fleet host ID format: "${fleet.agentToolId}" - expected numeric ID`)
        }
      }

      // 3) Create Device object directly - no normalization
      const merged: Device = createDevice(node, tacticalData, fleetData)

      setDeviceDetails(merged)
      setLastUpdated(Date.now())

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch device details'
      setError(errorMessage)

      // Only show toast for initial (non-silent) fetches
      if (!silent) {
        toast({
          title: "Failed to Load Device Details",
          description: errorMessage,
          variant: "destructive"
        })
      }
    } finally {
      if (!silent) {
        setIsLoading(false)
      }
    }
  }, [toast])

  const clearDeviceDetails = useCallback(() => {
    setDeviceDetails(null)
    setError(null)
    setLastUpdated(null)
  }, [])

  // Polling logic with adaptive intervals
  useEffect(() => {
    if (!deviceDetails?.machineId) return

    // Extract agent IDs from toolConnections
    const tacticalAgentId = deviceDetails.toolConnections?.find(tc => tc.toolType === 'TACTICAL_RMM')?.agentToolId
    const meshcentralAgentId = deviceDetails.toolConnections?.find(tc => tc.toolType === 'MESHCENTRAL')?.agentToolId

    // Adaptive interval based on agent connection status
    // Fast polling (5s) when agents are missing, slow polling (10s) when all connected
    const hasAllAgents = Boolean(tacticalAgentId && meshcentralAgentId)
    const pollingInterval = hasAllAgents ? 10000 : 5000 // 10s or 5s

    isPollingRef.current = true

    const intervalId = setInterval(() => {
      if (isPollingRef.current) {
        // Silent refresh - no loading states or error toasts
        fetchDeviceById(deviceDetails.machineId, true)
      }
    }, pollingInterval)

    return () => {
      clearInterval(intervalId)
      isPollingRef.current = false
    }
  }, [deviceDetails?.machineId, deviceDetails?.toolConnections, fetchDeviceById])

  return {
    deviceDetails,
    isLoading,
    error,
    fetchDeviceById,
    clearDeviceDetails,
    lastUpdated
  }
}

function useDevices(filters: DeviceFilterInput = {}) {
  const { toast } = useToast()
  const [devices, setDevices] = useState<Device[]>([])
  const [deviceFilters, setDeviceFilters] = useState<DeviceFilters | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [pageInfo, setPageInfo] = useState<any>(null)
  const [filteredCount, setFilteredCount] = useState(0)
  const [hasLoadedBeyondFirst, setHasLoadedBeyondFirst] = useState(false)

  // Stabilize filters to prevent infinite loops while still detecting changes
  const filtersKey = JSON.stringify(filters)
  const stableFilters = useMemo(() => filters, [filtersKey])
  const filtersRef = useRef(stableFilters)
  filtersRef.current = stableFilters

  const fetchDevices = useCallback(async (searchTerm?: string, cursor?: string | null) => {
    setIsLoading(true)
    setError(null)

    try {
      const response = await apiClient.post<GraphQLResponse<{ devices: {
        edges: Array<{ node: DevicesGraphQLNode, cursor: string }>
        pageInfo: { hasNextPage: boolean, hasPreviousPage: boolean, startCursor?: string, endCursor?: string }
        filteredCount: number
      }}>>('/api/graphql', {
        query: GET_DEVICES_QUERY,
        variables: {
          filter: filtersRef.current,
          pagination: { limit: 10, cursor: cursor || null },
          search: searchTerm || ''
        }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const graphqlResponse = response.data
      if (!graphqlResponse?.data) {
        throw new Error('No data received from server')
      }
      if (graphqlResponse.errors && graphqlResponse.errors.length > 0) {
        throw new Error(graphqlResponse.errors[0].message || 'GraphQL error occurred')
      }

      const nodes = graphqlResponse.data.devices.edges.map(e => e.node)

      // Create Device objects directly
      const transformedDevices: Device[] = nodes.map(createDeviceListItem)

      setDevices(transformedDevices)
      setPageInfo(graphqlResponse.data.devices.pageInfo)
      setFilteredCount(graphqlResponse.data.devices.filteredCount)
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch devices'
      setError(errorMessage)

      toast({
        title: "Failed to Load Devices",
        description: errorMessage,
        variant: "destructive"
      })
    } finally {
      setIsLoading(false)
    }
  }, [toast])

  const fetchDeviceFilters = useCallback(async () => {
    try {
      const response = await apiClient.post<GraphQLResponse<{ deviceFilters: DeviceFilters }>>('/api/graphql', {
        query: GET_DEVICE_FILTERS_QUERY,
        variables: {
          filter: filtersRef.current
        }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const graphqlResponse = response.data
      if (!graphqlResponse?.data) return
      if (graphqlResponse.errors && graphqlResponse.errors.length > 0) {
        throw new Error(graphqlResponse.errors[0].message || 'GraphQL error occurred')
      }

      setDeviceFilters(graphqlResponse.data.deviceFilters)

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch device filters'
      console.error('Device filters error:', errorMessage)
    }
  }, [])

  const searchDevices = useCallback((searchTerm: string) => {
    setHasLoadedBeyondFirst(false) // Reset pagination state on new search
    fetchDevices(searchTerm)
  }, [fetchDevices])

  const refreshDevices = useCallback(() => {
    fetchDevices()
    fetchDeviceFilters()
  }, [fetchDevices, fetchDeviceFilters])

  // Note: Initial fetch is controlled by the view component, not the hook
  // This allows views to pass cursor from URL on initial load
  // Track if first fetch has been done (set by view component)
  const initialLoadDone = useRef(false)
  // Track previous filters to detect actual changes vs initial render
  const prevFiltersKey = useRef<string | null>(null)

  // Function to mark initial load as done (called by view component after first fetch)
  const markInitialLoadDone = useCallback(() => {
    initialLoadDone.current = true
    // Also set the initial filters key so we don't refetch on first render
    prevFiltersKey.current = filtersKey
  }, [filtersKey])

  const fetchNextPage = useCallback(async (searchTerm: string) => {
    if (!pageInfo?.hasNextPage || !pageInfo?.endCursor) {
      return
    }
    setHasLoadedBeyondFirst(true)
    return fetchDevices(searchTerm, pageInfo.endCursor)
  }, [pageInfo, fetchDevices])

  const fetchFirstPage = useCallback(async (searchTerm: string) => {
    setHasLoadedBeyondFirst(false)
    return fetchDevices(searchTerm)
  }, [fetchDevices])

  // Refetch when filters change (after initial load, and only when filters ACTUALLY changed)
  useEffect(() => {
    // Only refetch if:
    // 1. Initial load is done
    // 2. Previous filters key was set (not first render after initial load)
    // 3. Filters actually changed
    if (initialLoadDone.current && prevFiltersKey.current !== null && prevFiltersKey.current !== filtersKey) {
      const refetch = async () => {
        await fetchDevices()
        await fetchDeviceFilters()
      }
      refetch()
    }
    // Update previous filters key (but only after initial load)
    if (initialLoadDone.current) {
      prevFiltersKey.current = filtersKey
    }
  }, [filtersKey, fetchDevices, fetchDeviceFilters])

  return {
    devices,
    deviceFilters,
    isLoading,
    error,
    searchDevices,
    refreshDevices,
    fetchDevices,
    fetchDeviceFilters,
    pageInfo,
    filteredCount,
    fetchNextPage,
    fetchFirstPage,
    hasLoadedBeyondFirst,
    setHasLoadedBeyondFirst,
    markInitialLoadDone
  }
}

interface ClipboardItem {
  fileIds: string[]
  sourcePath: string
  operation: 'copy' | 'cut'
}

interface UseMeshFileManagerOptions {
  meshcentralAgentId: string
  isRemote?: boolean
  onError?: (error: Error) => void
}

function getDirectoryFromFileIds(fileIds: string[]): string {
  if (fileIds.length === 0) return '/'

  const firstFilePath = fileIds[0]
  const pathParts = firstFilePath.split('/')
  pathParts.pop()
  return pathParts.length > 0 ? pathParts.join('/') : '/'
}

function useMeshFileManager({
  meshcentralAgentId,
  isRemote = true,
  onError
}: UseMeshFileManagerOptions): UseMeshFileManagerReturn {
  const { toast } = useToast()
  const [files, setFiles] = useState<FileItem[]>([])
  const [currentPath, setCurrentPath] = useState<string>('')
  const [selectedFiles, setSelectedFiles] = useState<string[]>([])
  const [connectionState, setConnectionState] = useState<FileConnectionState>('disconnected')
  const [loading, setLoading] = useState<boolean>(false)
  const [uploadProgress, setUploadProgress] = useState<FileTransferProgress | null>(null)
  const [downloadProgress, setDownloadProgress] = useState<FileTransferProgress | null>(null)
  const [clipboard, setClipboard] = useState<ClipboardItem | null>(null)
  const [isSearching, setIsSearching] = useState<boolean>(false)

  const fileManagerRef = useRef<MeshCentralFileManager | null>(null)
  const controlClientRef = useRef<MeshControlClient | null>(null)
  const initializingRef = useRef<boolean>(false)
  const initTokenRef = useRef<{ cancelled: boolean } | null>(null)
  const toastRef = useRef(toast)
  const onErrorRef = useRef(onError)

  useEffect(() => {
    toastRef.current = toast
  }, [toast])

  useEffect(() => {
    onErrorRef.current = onError
  }, [onError])

  useEffect(() => {
    if (!meshcentralAgentId) {
      return
    }

    let mounted = true
    let isInitializing = false

    const initFileManager = async () => {
      const token = { cancelled: false }
      initTokenRef.current = token

      const deviceKey = `${meshcentralAgentId}-${isRemote ? 'remote' : 'server'}`

      if (fileManagerRef.current || activeFileManagers.get(deviceKey)) {
        return
      }

      activeFileManagers.set(deviceKey, true)

      isInitializing = true
      initializingRef.current = true

      let initSucceeded = false

      try {
        setLoading(true)
        setConnectionState('connecting')

        const controlClient = new MeshControlClient()
        controlClientRef.current = controlClient

        if (token.cancelled) {
          controlClient.close()
          controlClientRef.current = null
          activeFileManagers.delete(deviceKey)
          return
        }

        const fileManager = new MeshCentralFileManager({
          nodeId: meshcentralAgentId,
          isRemote,
          consent: 0, // No consent required for file operations
          controlClient,
          onStateChange: (state) => {
            if (mounted) {
              setConnectionState(state)

              if (state === 'connected_end_to_end') {
                toastRef.current?.({
                  title: 'Connected',
                  description: 'File manager connected successfully',
                  variant: 'success',
                  duration: 2000
                })
              } else if (state === 'failed') {
                toastRef.current?.({
                  title: 'Connection Failed',
                  description: 'Failed to establish connection to file system',
                  variant: 'destructive',
                  duration: 5000
                })
              }
            }
          },
          onDirectoryChange: (entries: FileEntry[]) => {
            if (mounted) {
              const items = convertFileEntriesToItems(entries, fileManager.getCurrentPath())
              setFiles(items)
              setCurrentPath(fileManager.getCurrentPath())

              if (!fileManager.isSearchActive()) {
                setIsSearching(false)
              }
            }
          },
          onSearchStart: () => {
            if (mounted) {
              setFiles([])
              setIsSearching(true)
            }
          },
          onSearchResult: (result: FileEntry, allResults: FileEntry[]) => {
            if (mounted) {
              const items = convertFileEntriesToItems(allResults, fileManager.getCurrentPath())
              setFiles(items)
            }
          },
          onSearchComplete: (results: FileEntry[], cancelled?: boolean) => {
            if (mounted) {
              const items = convertFileEntriesToItems(results, fileManager.getCurrentPath())
              setFiles(items)

              if (!cancelled) {
                setIsSearching(false)
              }
            }
          },
          onTransferProgress: (progress: FileTransferProgress) => {
            if (mounted) {
              if (progress.type === 'upload') {
                setUploadProgress(progress)
                if (progress.progress === 100) {
                  setTimeout(() => setUploadProgress(null), 2000)
                }
              } else {
                setDownloadProgress(progress)
                if (progress.progress === 100) {
                  setTimeout(() => setDownloadProgress(null), 2000)
                }
              }
            }
          },
          onServerCancelDownload: (fileName: string, reason?: string) => {
            if (mounted) {
              setDownloadProgress(null)
              toastRef.current?.({
                title: 'Download Cancelled by Server',
                description: reason 
                  ? `${fileName} download was cancelled: ${reason}`
                  : `${fileName} download was cancelled by the server`,
                variant: 'destructive',
                duration: 5000
              })
            }
          },
          onError: (error: Error) => {
            if (mounted) {
              toastRef.current?.({
                title: 'File Manager Error',
                description: error.message,
                variant: 'destructive',
                duration: 5000
              })
              onErrorRef.current?.(error)
            }
          }
        })

        fileManagerRef.current = fileManager

        if (token.cancelled) {
          fileManager.disconnect()
          controlClient.close()
          controlClientRef.current = null
          fileManagerRef.current = null
          activeFileManagers.delete(deviceKey)
          return
        }

        await fileManager.connect()
        if (token.cancelled) {
          fileManager.disconnect()
          controlClient.close()
          controlClientRef.current = null
          fileManagerRef.current = null
          activeFileManagers.delete(deviceKey)
          return
        }
        initSucceeded = true

      } catch (error) {
        const err = error as Error
        toastRef.current?.({
          title: 'Connection Failed',
          description: err.message || 'Failed to connect to file manager',
          variant: 'destructive',
          duration: 5000
        })
        onErrorRef.current?.(err)
      } finally {
        if (mounted) {
          setLoading(false)
        }
        if (initTokenRef.current === token) {
          initTokenRef.current = null
        }
        const deviceKey = `${meshcentralAgentId}-${isRemote ? 'remote' : 'server'}`
        if (!initSucceeded) {
          activeFileManagers.delete(deviceKey)
        }
        isInitializing = false
        initializingRef.current = false
      }
    }

    initFileManager()

    return () => {
      if (initTokenRef.current) {
        initTokenRef.current.cancelled = true
      }
      const deviceKey = `${meshcentralAgentId}-${isRemote ? 'remote' : 'server'}`

      mounted = false
      isInitializing = false
      initializingRef.current = false
      activeFileManagers.delete(deviceKey)

      if (fileManagerRef.current) {
        fileManagerRef.current.disconnect()
        fileManagerRef.current = null
      }

      if (controlClientRef.current) {
        controlClientRef.current.close()
        controlClientRef.current = null
      }
    }
  }, [meshcentralAgentId, isRemote])

  const refreshCurrentDirectory = useCallback(async () => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      await fileManager.loadDirectory(fileManager.getCurrentPath())
    } catch {
      /* noop */
    }
  }, [])

  const navigateToPath = useCallback(async (path: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      setLoading(true)
      const sanitized = sanitizePath(path)
      await fileManager.navigateToPath(sanitized)
      setSelectedFiles([])
    } catch (error) {
      toast({
        title: 'Navigation Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    } finally {
      setLoading(false)
    }
  }, [toast])

  const navigateUp = useCallback(async () => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      setLoading(true)
      await fileManager.navigateUp()
      setSelectedFiles([])
    } catch (error) {
      toast({
        title: 'Navigation Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    } finally {
      setLoading(false)
    }
  }, [toast])

  const navigateInto = useCallback(async (folderName: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      setLoading(true)
      await fileManager.navigateInto(folderName)
      setSelectedFiles([])
    } catch (error) {
      toast({
        title: 'Navigation Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    } finally {
      setLoading(false)
    }
  }, [toast])

  const createFolder = useCallback(async (name: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      await fileManager.createFolder(name)
    } catch (error) {
      toast({
        title: 'Create Folder Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    } finally {
      refreshCurrentDirectory()
    }
  }, [toast, refreshCurrentDirectory])

  const deleteItems = useCallback(async (fileIds: string[]) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      const names = fileIds.map(id => id.split('/').pop() || '')
      await fileManager.deleteItems(names, true)
    } catch (error) {
      toast({
        title: 'Delete Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
      return
    }

    setSelectedFiles([])
    refreshCurrentDirectory()
  }, [toast, refreshCurrentDirectory])

  const renameItem = useCallback(async (oldName: string, newName: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      await fileManager.rename(oldName, newName)
    } catch (error) {
      toast({
        title: 'Rename Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    } finally {
      refreshCurrentDirectory()
    }
  }, [toast, refreshCurrentDirectory])

  const uploadFile = useCallback(async (file: File) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      await fileManager.uploadFile(file)
    } catch (error) {
      toast({
        title: 'Upload Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    }
  }, [toast])

  const downloadFile = useCallback((fileName: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      fileManager.downloadFile(fileName)
    } catch (error) {
      toast({
        title: 'Download Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
    }
  }, [toast])

  const copyFiles = useCallback(async (fileIds: string[], destinationPath: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      const names = fileIds.map(id => id.split('/').pop() || '')
      await fileManager.copyFiles(names, destinationPath)
    } catch (error) {
      toast({
        title: 'Copy Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
      return
    }

    refreshCurrentDirectory()
  }, [toast, refreshCurrentDirectory])

  const moveFiles = useCallback(async (fileIds: string[], destinationPath: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      const names = fileIds.map(id => id.split('/').pop() || '')
      await fileManager.moveFiles(names, destinationPath)
    } catch (error) {
      toast({
        title: 'Move Failed',
        description: (error as Error).message,
        variant: 'destructive'
      })
      return
    }

    setSelectedFiles([])
    refreshCurrentDirectory()
  }, [toast, refreshCurrentDirectory])

  const searchFiles = useCallback(async (query: string) => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      await fileManager.searchFiles(query)
    } catch (error) {
      const errorMessage = (error as Error).message
      if (!errorMessage.includes('Cancelled for new search')) {
        toast({
          title: 'Search Failed',
          description: errorMessage,
          variant: 'destructive'
        })
        setIsSearching(false)
      }
    }
  }, [toast])

  const cancelSearch = useCallback(async () => {
    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) return

    try {
      await fileManager.cancelSearch()
    } catch {
      /* noop */
    } finally {
      setIsSearching(false)
    }
  }, [])

  const selectFile = useCallback((fileId: string, selected: boolean) => {
    setSelectedFiles(prev => {
      if (selected) {
        return [...prev, fileId]
      } else {
        return prev.filter(id => id !== fileId)
      }
    })
  }, [])

  const selectAll = useCallback((selected: boolean) => {
    if (selected) {
      setSelectedFiles(files.map(f => f.id))
    } else {
      setSelectedFiles([])
    }
  }, [files])

  const copyToClipboard = useCallback((fileIds?: string[]) => {
    const targetFiles = fileIds || selectedFiles
    if (targetFiles.length === 0) {
      toast({
        title: 'No Files Selected',
        description: 'Please select files to copy',
        variant: 'default'
      })
      return
    }

    const sourcePath = getDirectoryFromFileIds(targetFiles)

    setClipboard({
      fileIds: targetFiles,
      sourcePath,
      operation: 'copy'
    })
  }, [selectedFiles, toast])

  const cutFiles = useCallback((fileIds?: string[]) => {
    const targetFiles = fileIds || selectedFiles
    if (targetFiles.length === 0) {
      toast({
        title: 'No Files Selected',
        description: 'Please select files to cut',
        variant: 'default'
      })
      return
    }

    const sourcePath = getDirectoryFromFileIds(targetFiles)

    setClipboard({
      fileIds: targetFiles,
      sourcePath,
      operation: 'cut'
    })
  }, [selectedFiles, toast])

  const pasteFiles = useCallback(async () => {
    if (!clipboard) {
      toast({
        title: 'Clipboard Empty',
        description: 'No files in clipboard to paste',
        variant: 'default'
      })
      return
    }

    const fileManager = fileManagerRef.current
    if (!fileManager || !fileManager.isConnected()) {
      toast({
        title: 'Not Connected',
        description: 'File manager not connected',
        variant: 'destructive'
      })
      return
    }

    if (clipboard.sourcePath === currentPath) {
      toast({
        title: 'Same Location',
        description: 'Cannot paste to the same location',
        variant: 'default'
      })
      return
    }

    const fileNames = clipboard.fileIds.map(id => id.split('/').pop() || '')

    try {
      if (clipboard.operation === 'copy') {
        await fileManager.copyFromSource(clipboard.sourcePath, fileNames)
      } else {
        await fileManager.moveFromSource(clipboard.sourcePath, fileNames)
        setClipboard(null)
        setSelectedFiles([])
      }
    } catch (error) {
      const operation = clipboard.operation === 'copy' ? 'Copy' : 'Move'
      toast({
        title: `${operation} Failed`,
        description: (error as Error).message,
        variant: 'destructive'
      })
      return
    }

    refreshCurrentDirectory()
  }, [clipboard, currentPath, toast, refreshCurrentDirectory])

  const clearClipboard = useCallback(() => {
    setClipboard(null)
    toast({
      title: 'Clipboard Cleared',
      description: 'Clipboard has been cleared',
      variant: 'default',
      duration: 2000
    })
  }, [toast])

  const cancelDownload = useCallback(() => {
    const fileManager = fileManagerRef.current
    if (!fileManager) return

    const downloader = fileManager.getDownloader()
    if (downloader.hasActiveDownload()) {
      const activeDownloadId = (downloader as any).activeDownloadId
      if (activeDownloadId) {
        downloader.cancelDownload(activeDownloadId)
        setDownloadProgress(null)
        toast({
          title: 'Download Cancelled',
          description: 'File download has been cancelled',
          variant: 'default'
        })
      }
    }
  }, [toast])

  const cancelUpload = useCallback(() => {
    const fileManager = fileManagerRef.current
    if (!fileManager) return

    const uploader = fileManager.getUploader()
    if (uploader.hasActiveUpload()) {
      const activeUploadId = uploader.getActiveUploadId()
      if (activeUploadId) {
        uploader.cancelUpload(activeUploadId)
        setUploadProgress(null)
        toast({
          title: 'Upload Cancelled',
          description: 'File upload has been cancelled',
          variant: 'default'
        })
      }
    }
  }, [toast])

  const handleFileAction = useCallback(async (action: FileAction, fileId?: string) => {
    const targetFiles = fileId ? [fileId] : selectedFiles

    switch (action) {
      case 'download':
        if (targetFiles.length === 1) {
          const fileName = targetFiles[0].split('/').pop() || ''
          downloadFile(fileName)
        }
        break

      case 'delete':
        if (targetFiles.length > 0) {
          await deleteItems(targetFiles)
        }
        break

      case 'new-folder':
        const folderName = prompt('Enter folder name:')
        if (folderName) {
          await createFolder(folderName)
        }
        break

      case 'rename':
        if (targetFiles.length === 1) {
          const oldName = targetFiles[0].split('/').pop() || ''
          const newName = prompt('Enter new name:', oldName)
          if (newName && newName !== oldName) {
            await renameItem(oldName, newName)
          }
        }
        break

      case 'upload':
        // This will be handled by the container component with file input
        break

      case 'copy':
        copyToClipboard(targetFiles)
        break

      case 'cut':
        cutFiles(targetFiles)
        break

      case 'paste':
        await pasteFiles()
        break

      default:
        break
    }
  }, [selectedFiles, downloadFile, deleteItems, createFolder, renameItem, copyToClipboard, cutFiles, pasteFiles])

  const isSearchActive = useCallback(() => {
    return fileManagerRef.current?.isSearchActive() ?? false
  }, [])

  return {
    files,
    currentPath,
    selectedFiles,
    connectionState,
    loading,
    isSearching,
    isSearchActive,
    uploadProgress,
    downloadProgress,
    clipboard,
    navigateToPath,
    navigateUp,
    navigateInto,
    createFolder,
    deleteItems,
    renameItem,
    uploadFile,
    downloadFile,
    cancelDownload,
    cancelUpload,
    copyFiles,
    moveFiles,
    searchFiles,
    cancelSearch,
    copyToClipboard,
    cutFiles,
    pasteFiles,
    clearClipboard,
    selectFile,
    selectAll,
    handleFileAction
  }
}

function useRegistrationSecret() {
  const { toast } = useToast()
  const [initialKey, setInitialKey] = useState<string>('')
  const [isLoading, setIsLoading] = useState<boolean>(false)
  const [error, setError] = useState<string | null>(null)

  const fetchActiveSecret = useCallback(async () => {
    setIsLoading(true)
    setError(null)
    try {
      const response = await apiClient.get('/api/agent/registration-secret/active')
      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }
      const { key } = response.data
      if (!key) {
        throw new Error('Active registration secret not found in response')
      }
      setInitialKey(key)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch registration secret'
      setError(message)
      toast({
        title: 'Failed to load registration secret',
        description: message,
        variant: 'destructive',
      })
    } finally {
      setIsLoading(false)
    }
  }, [toast])

  useEffect(() => {
    // Auto-fetch on mount
    fetchActiveSecret()
  }, [fetchActiveSecret])

  return {
    initialKey,
    isLoading,
    error,
    refetch: fetchActiveSecret,
  }
}

type ReleaseVersionResponse = {
  releaseVersion?: string
}

interface UseReleaseVersionOptions {
  /**
   * When false, the query is disabled until manually enabled.
   */
  enabled?: boolean
}

async function fetchReleaseVersion(): Promise<string> {
  const response = await apiClient.get<ReleaseVersionResponse>('/api/release-version')

  if (!response.ok) {
    throw new Error(response.error || `Request failed with status ${response.status}`)
  }

  return response.data?.releaseVersion?.trim() || 'latest'
}

function useReleaseVersion(options: UseReleaseVersionOptions = {}) {
  const { toast } = useToast()
  const { enabled = true } = options

  const query = useQuery({
    queryKey: releaseVersionQueryKeys.detail(),
    queryFn: fetchReleaseVersion,
    enabled,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    retry: 2,
    retryDelay: 1000,
  })

  if (query.error && enabled) {
    toast({
      title: 'Failed to load release version',
      description: query.error.message,
      variant: 'destructive',
    })
  }

  return {
    releaseVersion: query.data ?? 'latest',
    isLoading: query.isLoading,
    error: query.error?.message ?? null,
    refetch: query.refetch,

    isSuccess: query.isSuccess,
    isFetching: query.isFetching,

    query,
  }
}

