interface Battery {
  cycle_count: number
  health: string  // e.g., "Normal (99%)"
}

interface DeviceFilterTag {
  value: string
  label: string
  count: number
  __typename?: string
}

interface DeviceFilterValue {
  value: string
  count: number
  __typename?: string
}

