function toActionsMenuItem(
  config: DeviceActionButtonConfig,
  deviceId: string,
  handlers?: {
    onClick?: () => void
    onShellSelect?: (type: 'cmd' | 'powershell' | 'bash') => void
  }
) {
  if (config.type === 'submenu' && config.submenu) {
    return {
      id: config.id,
      label: config.label,
      icon: config.icon,
      type: 'submenu' as const,
      disabled: config.disabled,
      submenu: config.submenu.map(item => ({
        id: item.id,
        label: item.label,
        icon: item.icon,
        href: `/devices/details/${deviceId}?action=remoteShell&shellType=${item.id}`,
        showExternalLinkOnHover: true,
        onClick: () => handlers?.onShellSelect?.(item.id)
      }))
    }
  }

  return {
    id: config.id,
    label: config.label,
    icon: config.icon,
    disabled: config.disabled,
    href: config.href,
    showExternalLinkOnHover: config.showExternalLinkOnHover,
    onClick: handlers?.onClick
  }
}

interface DeviceActionAvailability {
  // Action enabled states
  remoteShellEnabled: boolean
  remoteControlEnabled: boolean
  manageFilesEnabled: boolean
  runScriptEnabled: boolean
  archiveEnabled: boolean
  deleteEnabled: boolean

  // Tool IDs (for handlers)
  meshcentralAgentId: string | undefined
  tacticalAgentId: string | undefined

  // Device state
  isOnline: boolean
}

function canArchiveDevice(status: string | undefined): boolean {
  const upperStatus = status?.toUpperCase()
  return upperStatus !== 'ARCHIVED' && upperStatus !== 'DELETED'
}

function canDeleteDevice(status: string | undefined): boolean {
  return status?.toUpperCase() !== 'DELETED'
}

function getDeviceActionAvailability(device: Device): DeviceActionAvailability {
  const meshcentralAgentId = getMeshCentralAgentId(device)
  const tacticalAgentId = getTacticalAgentId(device)
  const isOnline = isDeviceOnline(device.status)

  return {
    // Remote Shell: requires MeshCentral agent AND device must be online
    remoteShellEnabled: Boolean(meshcentralAgentId) && isOnline,

    // Remote Control: requires MeshCentral agent AND device must be online
    remoteControlEnabled: Boolean(meshcentralAgentId) && isOnline,

    // Manage Files: requires MeshCentral agent AND device must be online
    // (Currently same as remoteControlEnabled, but separate for future flexibility)
    manageFilesEnabled: Boolean(meshcentralAgentId) && isOnline,

    // Run Script: requires Tactical RMM agent AND device must be online
    runScriptEnabled: Boolean(tacticalAgentId) && isOnline,

    // Archive: device must not be already archived or deleted
    archiveEnabled: canArchiveDevice(device.status),

    // Delete: device must not be already deleted
    deleteEnabled: canDeleteDevice(device.status),

    // Pass through tool IDs for handlers
    meshcentralAgentId,
    tacticalAgentId,

    // Device state
    isOnline,
  }
}

function getMeshCentralAgentId(device: Device): string | undefined {
  return getToolConnection(device.toolConnections, 'MESHCENTRAL')?.agentToolId
}

function getTacticalAgentId(device: Device): string | undefined {
  return getToolConnection(device.toolConnections, 'TACTICAL_RMM')?.agentToolId
}

function getToolConnection(
  toolConnections: ToolConnection[] | undefined,
  toolType: 'MESHCENTRAL' | 'TACTICAL_RMM' | 'FLEET_MDM'
): ToolConnection | undefined {
  return toolConnections?.find(tc => tc.toolType === toolType)
}

function isDeviceOnline(status: string | undefined): boolean {
  return status?.toUpperCase() === 'ONLINE'
}

interface UninstallCommandOptions {
  platform: OSPlatformId
  releaseVersion: string
}

function buildBinaryUrl(version: string, assetName: string): string {
  if (!version) {
    return `${RELEASES_BASE_URL}/latest/download/${assetName}`
  }
  return `${RELEASES_BASE_URL}/download/${version}/${assetName}`
}

function buildInstallCommand(options: InstallCommandOptions): string {
  const { platform, serverUrl, initialKey, orgId, releaseVersion, additionalArgs = [] } = options

  const baseArgs = `install --serverUrl ${serverUrl} --initialKey ${initialKey} --orgId ${orgId}`
  const extras = additionalArgs.length ? ' ' + additionalArgs.join(' ') : ''

  if (platform === 'windows') {
    const windowsBinaryUrl = getWindowsBinaryUrl(releaseVersion)
    const argString = `${baseArgs}${extras}`
    return `Set-Location ~; Remove-Item -Path 'openframe-client.zip','openframe-client.exe' -Force -ErrorAction SilentlyContinue; Invoke-WebRequest -Uri '${windowsBinaryUrl}' -OutFile 'openframe-client.zip'; Expand-Archive -Path 'openframe-client.zip' -DestinationPath '.' -Force; Start-Process -FilePath '.\\openframe-client.exe' -ArgumentList '${argString}' -Verb RunAs -Wait`
  }

  // macOS / darwin
  const macBinaryUrl = getMacBinaryUrl(releaseVersion)
  return `cd ~ && rm -f openframe-client_macos.tar.gz openframe-client 2>/dev/null; curl -L -o openframe-client_macos.tar.gz '${macBinaryUrl}' && tar -xzf openframe-client_macos.tar.gz && sudo chmod +x ./openframe-client && sudo ./openframe-client ${baseArgs}${extras}`
}

function buildUninstallCommand(options: UninstallCommandOptions): string {
  const { platform, releaseVersion } = options

  if (platform === 'windows') {
    const windowsBinaryUrl = getWindowsBinaryUrl(releaseVersion)
    return `Set-Location ~; Remove-Item -Path 'openframe-client.zip','openframe-client.exe' -Force -ErrorAction SilentlyContinue; Invoke-WebRequest -Uri '${windowsBinaryUrl}' -OutFile 'openframe-client.zip'; Expand-Archive -Path 'openframe-client.zip' -DestinationPath '.' -Force; Start-Process -FilePath '.\\openframe-client.exe' -ArgumentList 'uninstall' -Verb RunAs -Wait`
  }

  // macOS / darwin
  const macBinaryUrl = getMacBinaryUrl(releaseVersion)
  return `cd ~ && rm -f openframe-client_macos.tar.gz openframe-client 2>/dev/null; curl -L -o openframe-client_macos.tar.gz '${macBinaryUrl}' && tar -xzf openframe-client_macos.tar.gz && sudo chmod +x ./openframe-client && sudo ./openframe-client uninstall`
}

function getMacBinaryUrl(version: string): string {
  return buildBinaryUrl(version, MACOS_BINARY_NAME)
}

function getWindowsBinaryUrl(version: string): string {
  return buildBinaryUrl(version, WINDOWS_BINARY_NAME)
}

function normalizeDevicePlatform(
  platform?: string,
  osType?: string,
  operatingSystem?: string
): OSPlatformId {
  const osValue = (platform || osType || operatingSystem || '').toLowerCase()

  if (osValue.includes('windows') || osValue === 'win' || osValue === 'win32' || osValue === 'win64') {
    return 'windows'
  }

  if (osValue.includes('darwin') || osValue.includes('mac') || osValue.includes('osx')) {
    return 'darwin'
  }

  if (osValue.includes('linux')) {
    return 'linux'
  }

  // Default to darwin if unknown
  return 'darwin'
}

