  switch(status.toUpperCase()) {
    case 'ONLINE':
      return { 
        label: 'ONLINE', 
        variant: 'success',
        cardStatus: 'active'
      }
    case 'PENDING':
    case 'ACTIVE':
      return {
        label: 'PENDING',
        variant: 'warning',
        cardStatus: 'warning'
      }
    case 'OFFLINE':
      return { 
        label: 'OFFLINE', 
        variant: 'error',
        cardStatus: 'offline'
      }
    case 'DECOMMISSIONED':
      return { 
        label: 'DECOMMISSIONED', 
        variant: 'error',
        cardStatus: 'offline'
      }
    case 'IDLE':
    case 'INACTIVE':
      return { 
        label: 'INACTIVE', 
        variant: 'info',
        cardStatus: 'inactive'
      }
    case 'MAINTENANCE':
      return {
        label: 'MAINTENANCE',
        variant: 'warning',
        cardStatus: 'warning'
      }
    case 'ARCHIVED':
      return {
