interface ApprovalHandlers {
  handleApprove: (requestId?: string) => void
  handleReject: (requestId?: string) => void
  approvalStatuses: Record<string, any>
}

interface UseMingoChat {
  // Messages
  messages: ProcessedMessage[]
  isLoading: boolean

  // Actions
  createDialog: () => Promise<string | null>
  sendMessage: (content: string) => Promise<boolean>

  // Approval system
  approvals: MessageSegment[]

  // Real-time processing
  processChunk: (targetDialogId: string, chunk: ChunkData, messageType: NatsMessageType) => void

  // State
  isCreatingDialog: boolean
  isTyping: boolean
  assistantType: 'mingo'
}

function useMingoChat(
  dialogId: string | null, 
  approvalHandlers?: ApprovalHandlers
): UseMingoChat {
  const { toast } = useToast()
  const queryClient = useQueryClient()

  const {
    messagesByDialog,
    typingStates,
    getMessages,
    addMessage,
    updateMessage,
    setStreamingMessage,
    getStreamingMessage,
    updateStreamingMessageSegments,
    getOrCreateAccumulator,
    getTyping,
    setTyping,
    removeWelcomeMessages,
    isCreatingDialog,
    setCreatingDialog,
  } = useMingoMessagesStore()

  const isTyping = useMemo(() => {
    if (!dialogId) return false
    return getTyping(dialogId)
  }, [dialogId, typingStates, getTyping])

  const createDialogMutation = MingoApiService.createDialogMutation()
  const sendMessageMutation = MingoApiService.sendMessageMutation()

  // Initialize accumulator with approval handlers when dialog or handlers change
  useEffect(() => {
    if (dialogId && approvalHandlers) {
      getOrCreateAccumulator(dialogId, {
        onApprove: approvalHandlers.handleApprove,
        onReject: approvalHandlers.handleReject
      })
    }
  }, [dialogId, approvalHandlers, getOrCreateAccumulator])

  const ensureAssistantMessage = useCallback((targetDialogId?: string) => {
    const effectiveDialogId = targetDialogId || dialogId
    if (!effectiveDialogId) return

    const currentStreaming = getStreamingMessage(effectiveDialogId)
    if (currentStreaming) return

    const assistantMessage: CoreMessage = {
      id: `assistant-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      role: 'assistant',
      content: [],
      name: 'Mingo',
      assistantType: 'mingo',
      timestamp: new Date()
    }

    setStreamingMessage(effectiveDialogId, assistantMessage)
    addMessage(effectiveDialogId, assistantMessage)
  }, [dialogId, getStreamingMessage, setStreamingMessage, addMessage])

  const updateStreamingMessageWithSegments = useCallback((segments: MessageSegment[], targetDialogId?: string) => {
    const effectiveDialogId = targetDialogId || dialogId
    if (!effectiveDialogId) return

    const currentStreaming = getStreamingMessage(effectiveDialogId)
    if (!currentStreaming) {
      return
    }

    updateStreamingMessageSegments(effectiveDialogId, segments)
  }, [dialogId, getStreamingMessage, updateStreamingMessageSegments])

  // Add welcome message for empty dialogs
  const addWelcomeMessage = useCallback(() => {
    if (!dialogId) return

    const currentMessages = getMessages(dialogId)

    if (currentMessages.length === 0) {
      const welcomeMessage: CoreMessage = {
        id: `welcome-${dialogId}`,
        role: 'assistant',
        name: 'Mingo',
        timestamp: new Date(),
        content: "Hi! I'm Mingo AI, ready to help with your technical tasks. What can I do for you?",
        assistantType: 'mingo'
      }

      addMessage(dialogId, welcomeMessage)
    }
  }, [dialogId, getMessages, addMessage])

  const addErrorMessage = useCallback((errorText: string, targetDialogId?: string) => {
    const effectiveDialogId = targetDialogId || dialogId
    if (!effectiveDialogId) return

    const errorMessage: CoreMessage = {
      id: `error-${Date.now()}`,
      role: 'error',
      name: 'Mingo',
      timestamp: new Date(),
      content: errorText,
    }

    const currentMessages = getMessages(effectiveDialogId)
    const lastMessage = currentMessages[currentMessages.length - 1]

    if (lastMessage?.role === 'assistant' && 
        (lastMessage.content === '' || 
         (Array.isArray(lastMessage.content) && lastMessage.content.length === 0))) {
      updateMessage(effectiveDialogId, lastMessage.id, errorMessage)
    } else {
      addMessage(effectiveDialogId, errorMessage)
    }
  }, [dialogId, getMessages, updateMessage, addMessage])

  useEffect(() => {
    if (dialogId) {
      addWelcomeMessage()
    }
  }, [dialogId, messagesByDialog, addWelcomeMessage])

  const messages = useMemo((): ProcessedMessage[] => {
    if (!dialogId) return []

    const currentMessages = getMessages(dialogId)
    const filteredMessages = currentMessages.filter(msg => 
      !msg.id.startsWith('pending-approvals-')
    )

    return filteredMessages.map(msg => {
      let filteredContent = msg.content

      if (Array.isArray(msg.content)) {
        filteredContent = (msg.content as MessageSegment[]).filter(segment => 
          !(segment.type === 'approval_request' && segment.status === 'pending')
        )
      }

      return {
        id: msg.id,
        content: filteredContent,
        role: msg.role,
        name: msg.name || 'Unknown',
        assistantType: msg.assistantType as 'fae' | 'mingo' | undefined,
        timestamp: msg.timestamp || new Date()
      }
    })
  }, [dialogId, messagesByDialog, getMessages])

  // Extract incomplete state from complete last assistant message
  const incompleteState = useMemo(() => {
    if (!dialogId) return undefined

    const currentMessages = getMessages(dialogId)
    const assistantSegments: MessageSegment[] = []
    let lastAssistantId = ''
    let lastAssistantTimestamp = new Date()

    for (let i = currentMessages.length - 1; i >= 0; i--) {
      const msg = currentMessages[i]
      if (msg.role === 'assistant') {
        if (!lastAssistantId) {
          lastAssistantId = msg.id
          lastAssistantTimestamp = msg.timestamp || new Date()
        }

        if (Array.isArray(msg.content)) {
          assistantSegments.unshift(...msg.content)
        } else if (typeof msg.content === 'string' && msg.content) {
          assistantSegments.unshift({
            type: 'text',
            text: msg.content,
            id: `${msg.id}-text`
          } as MessageSegment)
        }
      } else {
        break
      }
    }

    if (assistantSegments.length > 0 && lastAssistantId) {
      const completeAssistantMessage = {
        id: lastAssistantId,
        role: 'assistant' as const,
        content: assistantSegments,
        name: 'Mingo',
        timestamp: lastAssistantTimestamp
      }

      return extractIncompleteMessageState(completeAssistantMessage)
    }

    return undefined
  }, [dialogId, messagesByDialog, getMessages])

  // Real-time processing callbacks
  const realtimeCallbacks = useMemo(() => ({
    onStreamStart: () => {
      if (!dialogId) return

      ensureAssistantMessage()
      setTyping(dialogId, true)
    },

    onStreamEnd: () => {
      if (!dialogId) return
      setTyping(dialogId, false)
      setStreamingMessage(dialogId, null)
    },

    onSegmentsUpdate: (segments: MessageSegment[]) => {
      if (!dialogId) return

      setTyping(dialogId, true)
      ensureAssistantMessage(dialogId)
      updateStreamingMessageWithSegments(segments, dialogId)
    },

    onError: (error: string) => {
      if (!dialogId) return

      console.error('[MingoChat] Stream error:', error)
      setTyping(dialogId, false)
      setStreamingMessage(dialogId, null)
      addErrorMessage(error, dialogId)
    },
    onApprove: approvalHandlers?.handleApprove,
    onReject: approvalHandlers?.handleReject
  }), [dialogId, ensureAssistantMessage, setTyping, setStreamingMessage, updateStreamingMessageWithSegments, addErrorMessage, approvalHandlers])

  // Restore typing state from incomplete messages on dialog load
  useEffect(() => {
    if (!dialogId || !incompleteState) return

    const hasIncompleteContent = 
      (incompleteState.existingSegments && incompleteState.existingSegments.length > 0) ||
      (incompleteState.pendingApprovals && incompleteState.pendingApprovals.size > 0) ||
      (incompleteState.executingTools && incompleteState.executingTools.size > 0)

    if (hasIncompleteContent && !getTyping(dialogId)) {
      setTyping(dialogId, true)
    }
  }, [dialogId, incompleteState, getTyping, setTyping])

  const { processChunk: baseProcessChunk } = useRealtimeChunkProcessor({
    callbacks: realtimeCallbacks,
    displayApprovalTypes: ['CLIENT', 'ADMIN'],
    approvalStatuses: approvalHandlers?.approvalStatuses || {},
    initialState: incompleteState
  })

  const processChunk = useCallback((targetDialogId: string, chunk: ChunkData, _messageType: NatsMessageType) => {
    if (targetDialogId === dialogId) {
      baseProcessChunk(chunk)
    }
  }, [dialogId, baseProcessChunk])

  // Extract pending approvals from messages
  const approvals = useMemo(() => {
    if (!dialogId) return []

    const currentMessages = getMessages(dialogId)
    const pendingApprovalSegments: MessageSegment[] = []

    currentMessages.forEach(msg => {
      if (Array.isArray(msg.content)) {
        msg.content.forEach(segment => {
          if (segment.type === 'approval_request' && segment.status === 'pending') {
            pendingApprovalSegments.push(segment as MessageSegment)
          }
        })
      }
    })

    return pendingApprovalSegments
  }, [dialogId, messagesByDialog, getMessages])

  const createDialog = useCallback(async (): Promise<string | null> => {
    if (isCreatingDialog) return null

    try {
      setCreatingDialog(true)

      const result = await createDialogMutation.mutateAsync()

      toast({
        title: "Chat Created",
        description: "New chat session started successfully",
        variant: "success",
        duration: 3000
      })

      queryClient.invalidateQueries({ queryKey: ['mingo-dialogs'] })

      return result.id
    } catch (error) {
      console.error('[MingoChat] Failed to create dialog:', error)
      return null
    } finally {
      setCreatingDialog(false)
    }
  }, [isCreatingDialog, setCreatingDialog, createDialogMutation, toast, queryClient])

  const sendMessage = useCallback(async (content: string): Promise<boolean> => {
    if (!dialogId || !content.trim()) return false
    if (isTyping) return false

    try {
      setTyping(dialogId, true)
      removeWelcomeMessages(dialogId)

      const optimisticMessage: CoreMessage = {
        id: `optimistic-${Date.now()}-${Math.random().toString(16).slice(2)}`,
        role: 'user',
        content: content.trim(),
        name: 'You',
        timestamp: new Date()
      }

      addMessage(dialogId, optimisticMessage)
      await sendMessageMutation.mutateAsync({ dialogId, content: content.trim() })

      return true
    } catch (error) {
      console.error('[MingoChat] Failed to send message:', error)

      setTyping(dialogId, false)

      toast({
        title: "Send Failed",
        description: error instanceof Error ? error.message : 'Failed to send message',
        variant: "destructive",
        duration: 5000
      })

      return false
    }
  }, [dialogId, isTyping, setTyping, removeWelcomeMessages, addMessage, sendMessageMutation, toast])


  return {
    // Messages
    messages,
    isLoading: false,

    // Actions
    createDialog,
    sendMessage,

    // Approval system
    approvals,

    // Real-time processing
    processChunk,

    // State
    isCreatingDialog,
    isTyping,
    assistantType: 'mingo' as const
  }
}

interface UseMingoChunkCatchupOptions {
  dialogId: string | null
  onChunkReceived: (chunk: ChunkData, messageType: NatsMessageType) => void
}

function useMingoChunkCatchup({ dialogId, onChunkReceived }: UseMingoChunkCatchupOptions): UseChunkCatchupReturn {
  const fetchChunks = useCallback(async (
    dialogId: string,
    chatType: ChatType,
    fromSequenceId?: number | null
  ): Promise<ChunkData[]> => {
    try {
      let url = `/chat/api/v1/dialogs/${dialogId}/chunks?chatType=${chatType}`
      if (fromSequenceId !== null && fromSequenceId !== undefined) {
        url += `&fromSequenceId=${fromSequenceId}`
      }

      const response = await apiClient.get<ChunkData[]>(url)

      if (!response.ok) {
        console.error(`Failed to fetch ${chatType} chunks:`, response.error)
        return []
      }

      return response.data || []
    } catch (error) {
      console.error(`Error fetching ${chatType} chunks:`, error)
      return []
    }
  }, [])

  const options = useMemo<CoreChunkCatchupOptions>(() => ({
    dialogId,
    onChunkReceived,
    chatTypes: [CHAT_TYPE.ADMIN],
    fetchChunks,
  }), [dialogId, onChunkReceived, fetchChunks])

  return useChunkCatchupCore(options)
}

function useMingoDialogSelection() {
  const { toast } = useToast()
  const [approvalStatuses, setApprovalStatuses] = useState<Record<string, ApprovalStatus>>({})

  const {
    activeDialogId,
    setActiveDialogId,
    setMessages,
    setLoadingDialog,
    setLoadingMessages,
    setPagination,
    updateApprovalStatusInMessages
  } = useMingoMessagesStore()

  const approveRequestMutation = MingoApiService.approveRequestMutation()
  const rejectRequestMutation = MingoApiService.rejectRequestMutation()

  const handleApprove = useCallback((requestId?: string) => {
    if (!requestId || !activeDialogId) return

    approveRequestMutation.mutate(requestId, {
      onSuccess: () => {
        setApprovalStatuses(prev => ({
          ...prev,
          [requestId]: APPROVAL_STATUS.APPROVED
        }))

        updateApprovalStatusInMessages(activeDialogId, requestId, APPROVAL_STATUS.APPROVED)
      },
      onError: (error) => {
        toast({
          title: "Approval Failed",
          description: error instanceof Error ? error.message : "Unable to approve request",
          variant: "destructive",
          duration: 5000
        })
      }
    })
  }, [approveRequestMutation, toast, activeDialogId, updateApprovalStatusInMessages])

  const handleReject = useCallback((requestId?: string) => {
    if (!requestId || !activeDialogId) return

    rejectRequestMutation.mutate(requestId, {
      onSuccess: () => {
        setApprovalStatuses(prev => ({
          ...prev,
          [requestId]: APPROVAL_STATUS.REJECTED
        }))

        updateApprovalStatusInMessages(activeDialogId, requestId, APPROVAL_STATUS.REJECTED)
      },
      onError: (error) => {
        toast({
          title: "Rejection Failed",
          description: error instanceof Error ? error.message : "Unable to reject request",
          variant: "destructive",
          duration: 5000
        })
      }
    })
  }, [rejectRequestMutation, toast, activeDialogId, updateApprovalStatusInMessages])

  const dialogQuery = useQuery({
    queryKey: ['mingo-dialog', activeDialogId],
    queryFn: async () => {
      if (!activeDialogId) return null

      const response = await apiClient.post<DialogResponse>('/chat/graphql', {
        query: GET_MINGO_DIALOG_QUERY,
        variables: { id: activeDialogId }
      })

      if (!response.ok || !response.data?.data?.dialog) {
        throw new Error(response.error || 'Failed to fetch dialog')
      }

      return response.data.data.dialog
    },
    enabled: !!activeDialogId,
    staleTime: 30 * 1000,
  })

  const messagesQuery = useInfiniteQuery({
    queryKey: ['mingo-dialog-messages', activeDialogId],
    queryFn: async ({ pageParam }: { pageParam: string | undefined }): Promise<MessagePage> => {
      if (!activeDialogId) return { messages: [], pageInfo: { hasNextPage: false, hasPreviousPage: false } }

      const response = await apiClient.post<MessagesResponse>('/chat/graphql', {
        query: GET_DIALOG_MESSAGES_QUERY,
        variables: { 
          dialogId: activeDialogId, 
          cursor: pageParam,
          limit: 100
        }
      })

      if (!response.ok || !response.data?.data?.messages) {
        throw new Error(response.error || 'Failed to fetch messages')
      }

      const { edges, pageInfo } = response.data.data.messages
      const allMessages = edges.map(edge => edge.node)
      const adminMessages = allMessages.filter(msg => msg.chatType === CHAT_TYPE.ADMIN)

      return { messages: adminMessages, pageInfo }
    },
    getNextPageParam: (lastPage: MessagePage) => {
      return lastPage.pageInfo.hasNextPage ? lastPage.pageInfo.endCursor : undefined
    },
    initialPageParam: undefined as string | undefined,
    enabled: !!activeDialogId,
    staleTime: 30 * 1000,
  })

  const selectDialogMutation = useMutation({
    mutationFn: async (dialogId: string) => {
      // Don't clear messages - let them persist for fast switching
      // Only clear pagination state for new queries
      setPagination(false, null, null)

      setLoadingDialog(true)
      setLoadingMessages(true)

      setActiveDialogId(dialogId)

      return dialogId
    }
  })

  useEffect(() => {
    if (messagesQuery.hasNextPage && !messagesQuery.isFetchingNextPage && !messagesQuery.isLoading) {
      messagesQuery.fetchNextPage()
    }
  }, [messagesQuery.hasNextPage, messagesQuery.isFetchingNextPage, messagesQuery.isLoading, messagesQuery.fetchNextPage])

  useEffect(() => {
    if (messagesQuery.data?.pages && activeDialogId) {
      const allGraphQLMessages = messagesQuery.data.pages.flatMap(page => page.messages)

      // Extract approval statuses from GraphQL messages
      const extractedStatuses = allGraphQLMessages.reduce<Record<string, ApprovalStatus>>((acc, msg) => {
        const messageDataArray = Array.isArray(msg.messageData) ? msg.messageData : [msg.messageData]

        messageDataArray.forEach((data: any) => {
          if (data?.type === MESSAGE_TYPE.APPROVAL_RESULT && data.approvalRequestId) {
            acc[data.approvalRequestId] = data.approved ? APPROVAL_STATUS.APPROVED : APPROVAL_STATUS.REJECTED
          }
        })

        return acc
      }, {})

      if (Object.keys(extractedStatuses).length > 0) {
        setApprovalStatuses(prev => ({ ...prev, ...extractedStatuses }))
      }
    }
  }, [messagesQuery.data?.pages, activeDialogId])

  useEffect(() => {
    if (messagesQuery.data?.pages && activeDialogId) {
      const allGraphQLMessages = messagesQuery.data.pages.flatMap(page => page.messages)

      // Convert GraphQL messages to HistoricalMessage format
      const historicalMessages: HistoricalMessage[] = allGraphQLMessages
        .filter(msg => msg.chatType === CHAT_TYPE.ADMIN)
        .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime())
        .map(msg => ({
          id: msg.id,
          dialogId: msg.dialogId,
          chatType: msg.chatType,
          createdAt: msg.createdAt,
          owner: msg.owner,
          messageData: msg.messageData,
        }))

      const assistantConfig = ASSISTANT_CONFIG.MINGO
      const { messages: coreMessages } = processHistoricalMessagesWithErrors(historicalMessages, {
        assistantName: assistantConfig.name,
        assistantType: assistantConfig.type,
        chatTypeFilter: CHAT_TYPE.ADMIN,
        onApprove: handleApprove,
        onReject: handleReject,
        approvalStatuses: Object.fromEntries(
          Object.entries(approvalStatuses).map(([k, v]) => [k, v as any])
        )
      })

      if (messagesQuery.isFetched && coreMessages.length > 0) {
        setMessages(activeDialogId, coreMessages)
      }

      const lastPage = messagesQuery.data.pages[messagesQuery.data.pages.length - 1]
      if (lastPage) {
        setPagination(
          lastPage.pageInfo.hasPreviousPage,
          messagesQuery.data.pages[0]?.pageInfo.startCursor || null,
          lastPage.pageInfo.endCursor || null
        )
      }
    }
  }, [messagesQuery.data?.pages, activeDialogId])

  return {
    selectDialog: selectDialogMutation.mutate,
    isSelectingDialog: selectDialogMutation.isPending,
    isLoadingDialog: dialogQuery.isLoading,
    isLoadingMessages: messagesQuery.isLoading,
    rawMessagesCount: messagesQuery.data?.pages.reduce((total, page) => total + page.messages.length, 0) || 0,
    dialogError: dialogQuery.error?.message || null,
    messagesError: messagesQuery.error?.message || null,
    refetchDialog: dialogQuery.refetch,
    refetchMessages: messagesQuery.refetch,
    // Approval handlers for real-time processing
    handleApprove,
    handleReject,
    approvalStatuses
  }
}

interface CreateDialogRequest {
  agentType: 'ADMIN'
}

interface SendMessageRequest {
  dialogId: string
  content: string
  chatType: typeof CHAT_TYPE.ADMIN
}

function useMingoDialog() {
  const { toast } = useToast()
  const queryClient = useQueryClient()
  const [currentDialogId, setCurrentDialogId] = useState<string | null>(null)
  const dialogIdRef = useRef<string | null>(null)

  const getActiveDialogId = useCallback((preferredDialogId?: string | null) => {
    return preferredDialogId || currentDialogId || dialogIdRef.current
  }, [currentDialogId])

  const createDialogMutation = useMutation({
    mutationFn: async (): Promise<CreateDialogResponse> => {
      const response = await apiClient.post<CreateDialogResponse>('/chat/api/v1/dialogs', {
        agentType: 'ADMIN'
      } as CreateDialogRequest)

      if (!response.ok) {
        throw new Error(response.error || `Failed to create dialog with status ${response.status}`)
      }

      if (!response.data?.id) {
        throw new Error('Invalid response: dialog id not found')
      }

      return response.data
    },
    onSuccess: (data) => {
      setCurrentDialogId(data.id)
      dialogIdRef.current = data.id
      queryClient.invalidateQueries({ queryKey: ['mingo-dialogs'] })
    },
    onError: (error) => {
      const errorMessage = error instanceof Error ? error.message : 'Failed to create new chat'

      toast({
        title: "Failed to Create Chat",
        description: errorMessage,
        variant: "destructive",
        duration: 5000
      })

      console.error('Failed to create dialog:', error)
    }
  })

  const sendMessageMutation = useMutation({
    mutationFn: async ({ dialogId, content }: { dialogId: string; content: string }) => {
      const response = await apiClient.post('/chat/api/v1/messages', {
        dialogId,
        content,
        chatType: CHAT_TYPE.ADMIN
      } as SendMessageRequest)

      if (!response.ok) {
        throw new Error(response.error || `Failed to send message with status ${response.status}`)
      }

      return response.data
    },
    onError: (error) => {
      const errorMessage = error instanceof Error ? error.message : 'Failed to send message'

      toast({
        title: "Send Failed",
        description: errorMessage,
        variant: "destructive",
        duration: 5000
      })

      console.error('Failed to send message:', error)
    }
  })

  const createDialog = useCallback(async (): Promise<string | null> => {
    if (createDialogMutation.isPending) {
      return currentDialogId
    }

    try {
      const result = await createDialogMutation.mutateAsync()
      return result.id
    } catch (error) {
      return null
    }
  }, [createDialogMutation, currentDialogId])

  const sendMessage = useCallback(async (content: string, selectedDialogId?: string | null): Promise<boolean> => {
    const trimmedContent = content.trim()
    if (!trimmedContent) {
      toast({
        title: "Empty Message",
        description: "Please enter a message to send",
        variant: "destructive",
        duration: 3000
      })
      return false
    }

    let dialogId = getActiveDialogId(selectedDialogId)
    if (!dialogId) {
      dialogId = await createDialog()
      if (!dialogId) {
        return false
      }
    }

    try {
      await sendMessageMutation.mutateAsync({ dialogId, content: trimmedContent })
      return true
    } catch (error) {
      return false
    }
  }, [getActiveDialogId, createDialog, sendMessageMutation, toast])

  const resetDialog = useCallback(() => {
    setCurrentDialogId(null)
    dialogIdRef.current = null
    createDialogMutation.reset()
    sendMessageMutation.reset()
  }, [createDialogMutation, sendMessageMutation])

  return {
    currentDialogId,
    isCreatingDialog: createDialogMutation.isPending,
    isSendingMessage: sendMessageMutation.isPending,
    error: createDialogMutation.error || sendMessageMutation.error,
    createDialog,
    sendMessage,
    resetDialog,
    hasDialog: !!currentDialogId
  }
}

function transformToDialogItem(dialog: DialogNode, unreadCount: number = 0): DialogItem {
  return {
    id: dialog.id,
    title: dialog.title || 'Untitled Dialog',
    timestamp: new Date(dialog.createdAt),
    unreadMessagesCount: unreadCount
  }
}

function useMingoDialogs(options: UseMingoDialogsOptions = {}) {
  const { enabled = true, search, limit = 20 } = options
  const { getUnread } = useMingoMessagesStore()

  const query = useInfiniteQuery({
    queryKey: ['mingo-dialogs', { search, limit }],
    queryFn: async ({ pageParam }): Promise<{ dialogs: DialogNode[], pageInfo: { hasNextPage: boolean, endCursor?: string } }> => {
      const variables = {
        filter: {
          agentTypes: ["ADMIN"]
        },
        pagination: {
          limit,
          cursor: pageParam
        },
        search
      }

      const response = await apiClient.post<DialogsResponse>('/chat/graphql', {
        query: GET_MINGO_DIALOGS_QUERY,
        variables
      })

      if (!response.ok || !response.data) {
        throw new Error(response.error || 'Failed to fetch dialogs')
      }

      const { edges, pageInfo } = response.data.data.dialogs
      return {
        dialogs: edges.map(edge => edge.node),
        pageInfo
      }
    },
    getNextPageParam: (lastPage) => {
      return lastPage.pageInfo.hasNextPage ? lastPage.pageInfo.endCursor : undefined
    },
    initialPageParam: undefined as string | undefined,
    enabled,
    staleTime: 30 * 1000,
    refetchInterval: 60 * 1000,
  })

  const dialogsWithUnread = useMemo(() => {
    if (!query.data?.pages) return []

    const allDialogs = query.data.pages.flatMap(page => page.dialogs)
    return allDialogs.map(dialog => 
      transformToDialogItem(dialog, getUnread(dialog.id))
    )
  }, [query.data?.pages, getUnread])

  return {
    dialogs: dialogsWithUnread,
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error?.message,
    refetch: query.refetch,
    hasNextPage: query.hasNextPage,
    fetchNextPage: query.fetchNextPage,
    isFetchingNextPage: query.isFetchingNextPage,
  }
}

function DialogSubscription({
  dialogId,
  processChunk
}: DialogSubscriptionProps) {
  const [apiBaseUrl] = useState<string | null>(getApiBaseUrl)
  const [hasCaughtUp, setHasCaughtUp] = useState(false)
  const isDevTicketEnabled = runtimeEnv.enableDevTicketObserver()
  const [token] = useState<string | null>(
    isDevTicketEnabled ? getAccessToken() : null
  )

  const { 
    catchUpChunks, 
    resetChunkTracking,
    startInitialBuffering,
    processChunk: coreProcessChunk
  } = useMingoChunkCatchup({
    dialogId,
    onChunkReceived: (chunk, messageType) => {
      processChunk(dialogId, chunk, messageType)
    }
  })

  // NATS WebSocket URL
  const getNatsWsUrl = useMemo(() => {
    return (): string | null => {
      if (!apiBaseUrl) return null
      if (isDevTicketEnabled && !token) return null
      return buildNatsWsUrl(apiBaseUrl, {
        token: token || undefined,
        includeAuthParam: isDevTicketEnabled,
      })
    }
  }, [apiBaseUrl, token, isDevTicketEnabled])

  const clientConfig = useMemo(() => ({
    name: `openframe-frontend-mingo-${dialogId}`,
    user: 'machine',
    pass: '',
  }), [dialogId])

  useEffect(() => {
    resetChunkTracking()
    startInitialBuffering()
    setHasCaughtUp(false)

    return () => {
      resetChunkTracking()
    }
  }, [dialogId, resetChunkTracking, startInitialBuffering])

  const handleNatsEvent = useCallback((payload: unknown, messageType: NatsMessageType) => {
    coreProcessChunk(payload as ChunkData, messageType)
  }, [coreProcessChunk])

  const handleSubscribed = useCallback(async () => {
    if (!hasCaughtUp) {
      setHasCaughtUp(true)
      await catchUpChunks()
    }
  }, [hasCaughtUp, catchUpChunks])

  useNatsDialogSubscription({
    enabled: true,
    dialogId,
    topics: MINGO_TOPICS,
    onEvent: handleNatsEvent,
    onConnect: () => {},
    onDisconnect: () => {},
    onSubscribed: handleSubscribed,
    getNatsWsUrl,
    clientConfig,
  })

  return null
}

interface DialogSubscriptionProps {
  dialogId: string
  isActive: boolean
  processChunk: (targetDialogId: string, chunk: ChunkData, messageType: NatsMessageType) => void
}

interface DialogSubscriptionState {
  isSubscribed: boolean
  isConnected: boolean
  hasCaughtUp: boolean
}

interface UseMingoRealtimeSubscriptionOptions {
  onChunkReceived?: (dialogId: string, chunk: ChunkData, messageType: NatsMessageType) => void
}

function getAccessToken(): string | null {
  if (typeof window === 'undefined') return null
  try {
    return localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN) || null
  } catch {
    return null
  }
}

function getApiBaseUrl(): string | null {
  const envBase = runtimeEnv.tenantHostUrl()
  if (envBase) return envBase
  if (typeof window !== 'undefined' && window.location?.origin) return window.location.origin
  return null
}

function useMingoRealtimeSubscription(
  activeDialogId: string | null,
  options: UseMingoRealtimeSubscriptionOptions = {}
): UseMingoRealtimeSubscription {
  const { onChunkReceived } = options

  const [subscribedDialogs, setSubscribedDialogs] = useState<Set<string>>(new Set())
  const [dialogStates, setDialogStates] = useState<Map<string, DialogSubscriptionState>>(new Map())
  const [connectionState, setConnectionState] = useState<'connected' | 'disconnected' | 'connecting'>('disconnected')

  const onChunkReceivedRef = useRef(onChunkReceived)
  const catchupRefs = useRef<Map<string, any>>(new Map())

  const isDevTicketEnabled = runtimeEnv.enableDevTicketObserver()
  const [token, setToken] = useState<string | null>(
    isDevTicketEnabled ? getAccessToken() : null
  )

  const { 
    activeDialogId: storeActiveDialogId,
    resetUnread 
  } = useMingoMessagesStore()

  useEffect(() => {
    onChunkReceivedRef.current = onChunkReceived
  }, [onChunkReceived])

  useEffect(() => {
    if (!isDevTicketEnabled) return

    const handler = (e: StorageEvent) => {
      if (e.key === STORAGE_KEYS.ACCESS_TOKEN) {
        setToken(getAccessToken())
      }
    }
    window.addEventListener('storage', handler)
    return () => window.removeEventListener('storage', handler)
  }, [isDevTicketEnabled])

  // NATS client configuration
  const clientConfig = useMemo(() => ({
    name: 'openframe-frontend-mingo',
    user: 'machine',
    pass: '',
  }), [])

  const getSubscriptionState = useCallback((dialogId: string): DialogSubscriptionState => {
    return dialogStates.get(dialogId) || {
      isSubscribed: false,
      isConnected: false,
      hasCaughtUp: false
    }
  }, [dialogStates])

  const subscribeToDialog = useCallback((dialogId: string) => {
    if (subscribedDialogs.has(dialogId)) return

    setSubscribedDialogs(prev => new Set(prev).add(dialogId))
    setDialogStates(prev => {
      const newMap = new Map(prev)
      newMap.set(dialogId, {
        isSubscribed: true,
        isConnected: false,
        hasCaughtUp: false
      })
      return newMap
    })

    if (dialogId === activeDialogId) {
      resetUnread(dialogId)
    }
  }, [subscribedDialogs, activeDialogId, resetUnread])

  const unsubscribeFromDialog = useCallback((dialogId: string) => {
    setSubscribedDialogs(prev => {
      const newSet = new Set(prev)
      newSet.delete(dialogId)
      return newSet
    })

    setDialogStates(prev => {
      const newMap = new Map(prev)
      newMap.delete(dialogId)
      return newMap
    })

    catchupRefs.current.delete(dialogId)
  }, [])

  useEffect(() => {
    if (activeDialogId && !subscribedDialogs.has(activeDialogId)) {
      subscribeToDialog(activeDialogId)
    }
  }, [activeDialogId, subscribedDialogs, subscribeToDialog])

  return {
    subscribeToDialog,
    unsubscribeFromDialog,
    getSubscriptionState,
    subscribedDialogs,
    connectionState
  }
}

