function useOrganizationDetails() {
  const { toast } = useToast()
  const [organization, setOrganization] = useState<OrganizationDetails | null>(null)
  const [isLoading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchOrganizationById = useCallback(async (id: string) => {
    setLoading(true)
    setError(null)
    try {
      const response = await apiClient.post<any>('/api/graphql', {
        query: GET_ORGANIZATION_BY_ID_QUERY,
        variables: { id }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const org = (response.data as any)?.data?.organization
      if (!org) {
        setOrganization(null)
        return null
      }

      const contacts = Array.isArray(org.contactInformation?.contacts) ? org.contactInformation.contacts : []
      const primary = contacts[0] || {}
      const billing = contacts[1] || {}
      const technical = contacts[2] || {}

      const mapped: OrganizationDetails = {
        id: org.id,
        organizationId: org.organizationId,
        name: org.name || '-',
        industry: org.category || '-',
        website: org.websiteUrl || '-',
        employees: typeof org.numberOfEmployees === 'number' ? org.numberOfEmployees : null,
        updatedAt: org.updatedAt || org.createdAt || new Date().toISOString(),
        physicalAddress: formatAddress(org.contactInformation?.physicalAddress),
        mailingAddress: formatAddress(org.contactInformation?.mailingAddress),
        primary: { name: primary.contactName || '', title: primary.title || '', email: primary.email || '', phone: primary.phone || '' },
        billing: { name: billing.contactName || '', title: billing.title || '', email: billing.email || '', phone: billing.phone || '' },
        technical: { name: technical.contactName || '', title: technical.title || '', email: technical.email || '', phone: technical.phone || '' },
        mrrUsd: typeof org.monthlyRevenue === 'number' ? org.monthlyRevenue : null,
        contractStart: org.contractStartDate || null,
        contractEnd: org.contractEndDate || null,
        notes: (org.notes ? [org.notes] : []),
        isDefault: org.isDefault || false,
        imageUrl: org.image?.imageUrl
      }

      setOrganization(mapped)
      return mapped
    } catch (e) {
      const message = e instanceof Error ? e.message : 'Failed to load organization'
      setError(message)
      toast({ title: 'Error', description: message, variant: 'destructive' })
      throw e
    } finally {
      setLoading(false)
    }
  }, [toast])

  return { organization, isLoading, error, fetchOrganizationById }
}

interface OrganizationLookupState {
  lookup: Record<string, string>
  isLoading: boolean
  hasFetched: boolean
}

function useOrganizationLookup() {
  const [state, setState] = useState<OrganizationLookupState>({
    lookup: {},
    isLoading: false,
    hasFetched: false
  })

  const pendingFetchRef = useRef<Promise<void> | null>(null)

  /**
   * Lazily fetch organization names.
   * Only fetches once, caches results.
   * Non-blocking - returns immediately, updates state when done.
   */
  const fetchOrganizationNames = useCallback(async (_organizationIds?: string[]) => {
    // Already fetched - no need to refetch
    if (state.hasFetched) {
      return
    }

    // Already fetching - wait for it
    if (pendingFetchRef.current) {
      await pendingFetchRef.current
      return
    }

    setState(prev => ({ ...prev, isLoading: true }))

    const fetchPromise = (async () => {
      try {
        const response = await apiClient.post<any>('/api/graphql', {
          query: GET_ORGANIZATIONS_MIN_QUERY
        })

        if (!response.ok) {
          console.error('Failed to fetch organizations for lookup')
          return
        }

        const edges = response.data?.data?.organizations?.edges || []
        const newLookup: Record<string, string> = {}

        for (const edge of edges) {
          const node = edge.node
          if (node?.organizationId && node?.name) {
            newLookup[node.organizationId] = node.name
          }
        }

        setState({
          lookup: newLookup,
          isLoading: false,
          hasFetched: true
        })
      } catch (error) {
        console.error('Error fetching organization lookup:', error)
        setState(prev => ({ ...prev, isLoading: false }))
      }
    })()

    pendingFetchRef.current = fetchPromise
    await fetchPromise
    pendingFetchRef.current = null
  }, [state.hasFetched])

  /**
   * Get organization name by ID.
   * Returns undefined if not yet loaded.
   */
  const getOrganizationName = useCallback((organizationId: string | undefined): string | undefined => {
    if (!organizationId) return undefined
    return state.lookup[organizationId]
  }, [state.lookup])

  return {
    lookup: state.lookup,
    isLoading: state.isLoading,
    hasFetched: state.hasFetched,
    fetchOrganizationNames,
    getOrganizationName
  }
}

function useOrganizationsMin(limit: number = 10) {
  const [items, setItems] = useState<OrganizationMin[]>([])
  const [isLoading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetch = useCallback(async (search: string = '') => {
    setLoading(true)
    setError(null)
    try {
      const response = await apiClient.post<any>('/api/graphql', {
        query: GET_ORGANIZATIONS_MIN_QUERY,
        variables: { search, pagination: { limit, cursor: null } }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const payload = (response.data as any)?.data?.organizations
      const list = Array.isArray(payload?.edges) ? payload.edges : []
      const mapped: OrganizationMin[] = list.map(({node}: any) => ({ id: node.id, organizationId: node.organizationId, name: node.name, isDefault: node.isDefault, imageUrl: node.image?.imageUrl }))
      setItems(mapped)
      return mapped
    } catch (e) {
      const msg = e instanceof Error ? e.message : 'Failed to fetch organizations'
      setError(msg)
      throw e
    } finally {
      setLoading(false)
    }
  }, [])

  return { items, isLoading, error, fetch }
}

interface OrganizationsFilterInput {
  tiers?: LooseString<OrganizationEntry['tier']>[]
  industries?: string[]
}

interface PageInfo {
  hasNextPage: boolean
  hasPreviousPage: boolean
  startCursor: string | null
  endCursor: string | null
}

function useOrganizations(activeFilters: OrganizationsFilterInput = {}) {
  const { toast } = useToast()
  const {
    organizations,
    search,
    error,
    setOrganizations,
    setSearch,
    setError,
    clearOrganizations,
    reset
  } = useOrganizationsStore()

  // Use LOCAL state for isLoading with initial=true to show skeleton immediately on mount
  // (before useEffect triggers fetch). This prevents the flash of empty state.
  const [isLoading, setIsLoading] = useState(true)

  // Pagination state (local to hook, not persisted)
  const [pageInfo, setPageInfo] = useState<PageInfo | null>(null)
  const [hasLoadedBeyondFirst, setHasLoadedBeyondFirst] = useState(false)

  // Stabilize filters to prevent infinite loops while still detecting changes
  const filtersKey = JSON.stringify(activeFilters)
  const stableFilters = useMemo(() => activeFilters, [filtersKey])
  const filtersRef = useRef(stableFilters)
  filtersRef.current = stableFilters

  // Track if first fetch has been done (set by view component)
  const initialLoadDone = useRef(false)
  // Track previous filters to detect actual changes vs initial render
  const prevFiltersKey = useRef<string | null>(null)

  const fetchOrganizations = useCallback(async (
    searchTerm: string,
    cursor?: string | null,
    filters: OrganizationsFilterInput = {},
  ) => {
    setIsLoading(true)
    setError(null)

    try {
      const response = await apiClient.post<any>('/api/graphql', {
        query: GET_ORGANIZATIONS_QUERY,
        variables: {
          search: searchTerm || '',
          pagination: {
            limit: 10,
            cursor: cursor || null
          }
        }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const payload = (response.data as any)?.data?.organizations

      // Handle paginated response structure
      const edges = Array.isArray(payload?.edges) ? payload.edges : []
      const items = edges.map((edge: any) => edge.node)

      const mapped: OrganizationEntry[] = items.map((o: any): OrganizationEntry => ({
        id: o.id,
        organizationId: o.organizationId,
        name: o.name ?? '-',
        websiteUrl: o.websiteUrl ?? '-',
        contact: { name: '', email: '' },
        tier: 'Basic',
        industry: o.category ?? '-',
        mrrUsd: o.monthlyRevenue ?? 0,
        contractDue: o.contractEndDate ?? '',
        lastActivity: new Date().toISOString(),
        imageUrl: o.image?.imageUrl || null,
      }))

      setOrganizations(mapped)

      // Update pagination info
      if (payload?.pageInfo) {
        setPageInfo({
          hasNextPage: payload.pageInfo.hasNextPage ?? false,
          hasPreviousPage: payload.pageInfo.hasPreviousPage ?? false,
          startCursor: payload.pageInfo.startCursor ?? null,
          endCursor: payload.pageInfo.endCursor ?? null
        })
      }

      return mapped
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch organizations'
      console.error('Failed to fetch organizations:', error)
      setError(errorMessage)
      toast({
        title: 'Error fetching organizations',
        description: errorMessage,
        variant: 'destructive'
      })
      throw error
    } finally {
      setIsLoading(false)
    }
  }, [setOrganizations, setError, toast])

  // Function to mark initial load as done (called by view component after first fetch)
  const markInitialLoadDone = useCallback(() => {
    initialLoadDone.current = true
    // Also set the initial filters key so we don't refetch on first render
    prevFiltersKey.current = filtersKey
  }, [filtersKey])

  const fetchNextPage = useCallback(async (searchTerm: string) => {
    if (!pageInfo?.hasNextPage || !pageInfo?.endCursor) {
      return
    }
    setHasLoadedBeyondFirst(true)
    return fetchOrganizations(searchTerm, pageInfo.endCursor, filtersRef.current)
  }, [pageInfo, fetchOrganizations])

  const fetchFirstPage = useCallback(async (searchTerm: string) => {
    setHasLoadedBeyondFirst(false)
    return fetchOrganizations(searchTerm, null, filtersRef.current)
  }, [fetchOrganizations])

  const searchOrganizations = useCallback(async (searchTerm: string) => {
    setSearch(searchTerm)
    setHasLoadedBeyondFirst(false)
    return fetchOrganizations(searchTerm, null, filtersRef.current)
  }, [setSearch, fetchOrganizations])

  const refreshOrganizations = useCallback(async () => {
    return fetchOrganizations(search, null, filtersRef.current)
  }, [fetchOrganizations, search])

  // Refetch when filters change (after initial load, and only when filters ACTUALLY changed)
  useEffect(() => {
    // Only refetch if:
    // 1. Initial load is done
    // 2. Previous filters key was set (not first render after initial load)
    // 3. Filters actually changed
    if (initialLoadDone.current && prevFiltersKey.current !== null && prevFiltersKey.current !== filtersKey) {
      const refetch = async () => {
        await fetchOrganizations(search, null, filtersRef.current)
      }
      refetch()
    }
    // Update previous filters key (but only after initial load)
    if (initialLoadDone.current) {
      prevFiltersKey.current = filtersKey
    }
  }, [filtersKey, fetchOrganizations, search])

  return {
    organizations,
    search,
    isLoading,
    error,
    pageInfo,
    hasLoadedBeyondFirst,
    setHasLoadedBeyondFirst,
    fetchOrganizations,
    fetchNextPage,
    fetchFirstPage,
    searchOrganizations,
    refreshOrganizations,
    clearOrganizations,
    reset,
    markInitialLoadDone
  }
}

