function useRunScriptData({ scriptId }: UseRunScriptDataOptions) {
  const { toast } = useToast()

  // Script state
  const [scriptDetails, setScriptDetails] = useState<ScriptDetails | null>(null)
  const [isLoadingScript, setIsLoadingScript] = useState(true)
  const [scriptError, setScriptError] = useState<string | null>(null)

  // Devices state
  const [devices, setDevices] = useState<Device[]>([])
  const [isLoadingDevices, setIsLoadingDevices] = useState(false)
  const [devicesError, setDevicesError] = useState<string | null>(null)
  const [pageInfo, setPageInfo] = useState<any>(null)
  const [filteredCount, setFilteredCount] = useState(0)

  // Fetch script details
  const fetchScriptDetails = useCallback(async () => {
    if (!scriptId) {
      setScriptError('Script ID is required')
      setIsLoadingScript(false)
      return
    }

    try {
      setIsLoadingScript(true)
      setScriptError(null)

      const response = await tacticalApiClient.getScript(scriptId)

      if (response.ok && response.data) {
        setScriptDetails(response.data)
      } else {
        setScriptError(response.error || 'Failed to fetch script details')
      }
    } catch (err) {
      console.error('Error fetching script details:', err)
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred'
      setScriptError(errorMessage)
    } finally {
      setIsLoadingScript(false)
    }
  }, [scriptId])

  // Fetch devices with filters based on script's supported_platforms
  const fetchDevices = useCallback(async (searchTerm?: string, cursor?: string | null) => {
    if (!scriptDetails) return

    setIsLoadingDevices(true)
    setDevicesError(null)

    try {
      // Build filter based on script's supported_platforms
      const osTypes = mapPlatformsToOsTypes(scriptDetails.supported_platforms || [])

      const filter = {
        statuses: [DEVICE_STATUS.ONLINE, DEVICE_STATUS.OFFLINE],
        ...(osTypes.length > 0 && { osTypes })
      }

      const response = await apiClient.post<GraphQLResponse<{ devices: {
        edges: Array<{ node: DevicesGraphQLNode, cursor: string }>
        pageInfo: { hasNextPage: boolean, hasPreviousPage: boolean, startCursor?: string, endCursor?: string }
        filteredCount: number
      }}>>('/api/graphql', {
        query: GET_DEVICES_QUERY,
        variables: {
          filter,
          pagination: { limit: 100, cursor: cursor || null },
          search: searchTerm || ''
        }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const graphqlResponse = response.data

      if (!graphqlResponse?.data) {
        throw new Error('No data received from server')
      }
      if (graphqlResponse.errors && graphqlResponse.errors.length > 0) {
        throw new Error(graphqlResponse.errors[0].message || 'GraphQL error occurred')
      }

      const nodes = graphqlResponse.data.devices.edges.map(e => e.node)
      const transformedDevices: Device[] = nodes.map(createDeviceListItem)

      setDevices(transformedDevices)
      setPageInfo(graphqlResponse.data.devices.pageInfo)
      setFilteredCount(graphqlResponse.data.devices.filteredCount)
    } catch (error) {
      console.error('Error fetching devices:', error)
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch devices'
      setDevicesError(errorMessage)

      toast({
        title: 'Failed to Load Devices',
        description: errorMessage,
        variant: 'destructive'
      })
    } finally {
      setIsLoadingDevices(false)
    }
  }, [scriptDetails, toast])

  const searchDevices = useCallback((searchTerm: string) => {
    fetchDevices(searchTerm)
  }, [fetchDevices])

  // Initial load: fetch script first
  useEffect(() => {
    fetchScriptDetails()
  }, [fetchScriptDetails])

  // When script is loaded, fetch devices
  useEffect(() => {
    if (scriptDetails && !isLoadingScript) {
      fetchDevices()
    }
  }, [scriptDetails, isLoadingScript, fetchDevices])

  return {
    // Script
    scriptDetails,
    isLoadingScript,
    scriptError,

    // Devices
    devices,
    isLoadingDevices,
    devicesError,
    pageInfo,
    filteredCount,

    // Actions
    searchDevices,
    fetchDevices,
    refetchScript: fetchScriptDetails
  }
}

async function deleteScheduledTaskApi(taskId: string): Promise<void> {
  const res = await tacticalApiClient.deleteScheduledTask(taskId)
  if (!res.ok) {
    throw new Error(res.error || `Failed to delete scheduled task (${res.status})`)
  }
}

async function fetchScheduledTasksByScript(scriptId: string): Promise<ScheduledTask[]> {
  const res = await tacticalApiClient.getScheduledTasks()

  if (!res.ok) {
    throw new Error(res.error || `Failed to load scheduled tasks (${res.status})`)
  }

  const allTasks: ScheduledTask[] = res.data || []
  const scriptIdNum = parseInt(scriptId, 10)

  // Filter tasks that have at least one action referencing this script
  return allTasks.filter((task) =>
    task.actions.some((action) => action.type === 'script' && action.script === scriptIdNum)
  )
}

function useScheduledTasks(scriptId: string) {
  const queryClient = useQueryClient()

  const scheduledTasksQuery = useQuery({
    queryKey: scheduledTasksQueryKeys.byScript(scriptId),
    queryFn: () => fetchScheduledTasksByScript(scriptId),
    enabled: !!scriptId,
  })

  const deleteTaskMutation = useMutation({
    mutationFn: deleteScheduledTaskApi,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: scheduledTasksQueryKeys.byScript(scriptId) })
    },
  })

  const deleteTask = (
    taskId: string,
    options?: {
      onSuccess?: () => void
      onError?: (error: Error) => void
    }
  ) => {
    deleteTaskMutation.mutate(taskId, {
      onSuccess: () => {
        options?.onSuccess?.()
      },
      onError: (error) => {
        options?.onError?.(error as Error)
      },
    })
  }

  return {
    // Data
    scheduledTasks: scheduledTasksQuery.data ?? [],

    // Loading & error states
    isLoading: scheduledTasksQuery.isLoading,
    error: scheduledTasksQuery.error?.message ?? null,

    // Refetch
    refetch: scheduledTasksQuery.refetch,

    // Mutations
    deleteTask,
    isDeleting: deleteTaskMutation.isPending,

    // Raw query for advanced use cases
    scheduledTasksQuery,
  }
}

function useScriptDetails(scriptId: string) {
  const [scriptDetails, setScriptDetails] = useState<ScriptDetails | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchScriptDetails = useCallback(async (id: string) => {
    if (!id) {
      setError('Script ID is required')
      setIsLoading(false)
      return
    }

    try {
      setIsLoading(true)
      setError(null)

      const response = await tacticalApiClient.getScript(id)

      console.log('Response:', response)

      if (response.ok && response.data) {
        setScriptDetails(response.data)
      } else {
        setError(response.error || 'Failed to fetch script details')
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred'
      setError(errorMessage)
      console.error('Error fetching script details:', err)
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => {
    fetchScriptDetails(scriptId)
  }, [scriptId, fetchScriptDetails])

  return {
    scriptDetails,
    isLoading,
    error,
    refetch: () => fetchScriptDetails(scriptId)
  }
}

interface ScriptsFilterInput {
  shellType?: string[]
  addedBy?: string[]
  category?: string[]
}

function useScripts(activeFilters: ScriptsFilterInput = {}) {
  const { toast } = useToast()
  const {
    scripts,
    search,
    error,
    setScripts,
    setSearch,
    setError,
    clearScripts,
    reset
  } = useScriptsStore()

  // Use LOCAL state for isLoading with initial=true to show skeleton immediately on mount
  // (before useEffect triggers fetch). This prevents the flash of empty state.
  const [isLoading, setIsLoading] = useState(false)

  // Track if first fetch has been done (set by view component)
  const initialLoadDone = useRef(false)

  // Stabilize filters to prevent infinite loops while still detecting changes
  const filtersKey = JSON.stringify(activeFilters)
  const stableFilters = useMemo(() => activeFilters, [filtersKey])
  const filtersRef = useRef(stableFilters)
  filtersRef.current = stableFilters

  // Track previous filters to detect actual changes vs initial render
  const prevFiltersKey = useRef<string | null>(null)

  const fetchScripts = useCallback(async (
    searchTerm: string,
    filters: ScriptsFilterInput = {},
  ) => {
    setIsLoading(true)
    setError(null)

    try {
      const response = await tacticalApiClient.getScripts()

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const data = response.data;

      data && setScripts(data)
      return data;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch scripts'
      console.error('Failed to fetch scripts:', error)
      setError(errorMessage)

      toast({
        title: 'Error fetching scripts',
        description: errorMessage,
        variant: 'destructive'
      })

      throw error
    } finally {
      setIsLoading(false)
    }
  }, [toast, setScripts, setError])

  // Function to mark initial load as done (called by view component after first fetch)
  const markInitialLoadDone = useCallback(() => {
    initialLoadDone.current = true
    // Also set the initial filters key so we don't refetch on first render
    prevFiltersKey.current = filtersKey
  }, [filtersKey])

  const searchScripts = useCallback(async (searchTerm: string) => {
    setSearch(searchTerm)
    return fetchScripts(searchTerm, filtersRef.current)
  }, [setSearch, fetchScripts])

  const refreshScripts = useCallback(async () => {
    return fetchScripts(search, filtersRef.current)
  }, [fetchScripts, search])

  // Refetch when filters change (after initial load, and only when filters ACTUALLY changed)
  useEffect(() => {
    // Only refetch if:
    // 1. Initial load is done
    // 2. Previous filters key was set (not first render after initial load)
    // 3. Filters actually changed
    if (initialLoadDone.current && prevFiltersKey.current !== null && prevFiltersKey.current !== filtersKey) {
      const refetch = async () => {
        await fetchScripts(search, filtersRef.current)
      }
      refetch()
    }
    // Update previous filters key (but only after initial load)
    if (initialLoadDone.current) {
      prevFiltersKey.current = filtersKey
    }
  }, [filtersKey, fetchScripts, search])

  return {
    // State
    scripts,
    search,
    isLoading,
    error,

    // Actions
    fetchScripts,
    searchScripts,
    refreshScripts,
    clearScripts,
    reset,
    markInitialLoadDone
  }
}

