function mapPlatformsForDisplay(platforms: string[]): string[] {
  const mapping: Record<string, string> = {
    windows: 'Windows',
    darwin: 'macOS',
    linux: 'Linux'
  }

  return platforms
    .map(p => mapping[p.toLowerCase()])
    .filter((v): v is string => !!v)
}

function mapPlatformsToOsTypes(platforms: string[]): string[] {
  const mapping: Record<string, string> = {
    windows: 'WINDOWS',
    darwin: 'MAC_OS'
  }

  return platforms
    .map(p => mapping[p.toLowerCase()])
    .filter((v): v is string => !!v)
}

