interface UpdateAIConfigurationParams {
  provider: string
  modelName: string
  apiKey?: string
}

function useAIConfiguration() {
  const [configuration, setConfiguration] = useState<AIConfiguration | null>(null)
  const [supportedModels, setSupportedModels] = useState<SupportedModels>({})
  const [isLoading, setIsLoading] = useState(true)
  const [isSaving, setIsSaving] = useState(false)
  const { toast } = useToast()

  const fetchConfiguration = useCallback(async () => {
    try {
      const response = await apiClient.get<AIConfiguration>('/chat/api/v1/ai-configuration')

      if (!response.ok) {
        throw new Error(response.error || 'Failed to fetch AI configuration')
      }

      if (response.data) {
        setConfiguration(response.data)
        return response.data
      }
    } catch (error) {
      toast({
        title: "Failed to Load Configuration",
        description: error instanceof Error ? error.message : "Unable to load AI settings",
        variant: "destructive",
        duration: 5000
      })
      throw error
    } finally {
      setIsLoading(false)
    }
  }, [toast])

  const fetchSupportedModels = useCallback(async () => {
    try {
      const response = await apiClient.get<SupportedModels>('/chat/api/v1/ai-configuration/supported-models')

      if (!response.ok) {
        throw new Error(response.error || 'Failed to fetch supported models')
      }

      if (response.data) {
        setSupportedModels(response.data)
        return response.data
      }
    } catch (error) {
      toast({
        title: "Failed to Load Models",
        description: "Unable to fetch supported AI models",
        variant: "destructive",
        duration: 5000
      })
      throw error
    }
  }, [toast])

  const updateConfiguration = useCallback(async (params: UpdateAIConfigurationParams) => {
    setIsSaving(true)

    try {
      const body: any = {
        provider: params.provider,
        modelName: params.modelName
      }

      if (params.apiKey?.trim()) {
        body.apiKey = params.apiKey
      }

      const response = await apiClient.post<AIConfiguration>('/chat/api/v1/ai-configuration', body)

      if (!response.ok) {
        throw new Error(response.error || 'Failed to save AI configuration')
      }

      toast({
        title: "Settings Saved",
        description: "AI configuration updated successfully",
        variant: "success",
        duration: 4000
      })

      const updatedConfig = await fetchConfiguration()
      return updatedConfig
    } catch (error) {
      toast({
        title: "Save Failed",
        description: error instanceof Error ? error.message : "Unable to save AI settings",
        variant: "destructive",
        duration: 5000
      })
      throw error
    } finally {
      setIsSaving(false)
    }
  }, [toast, fetchConfiguration])

  useEffect(() => {
    fetchConfiguration()
    fetchSupportedModels()
  }, [fetchConfiguration, fetchSupportedModels])

  return {
    configuration,
    supportedModels,
    isLoading,
    isSaving,
    fetchConfiguration,
    fetchSupportedModels,
    updateConfiguration
  }
}

function getErrorMessage(error: unknown, fallback: string) {
  return error instanceof Error ? error.message : fallback
}

function useAIPolicies() {
  const { toast } = useToast()

  const [templates, setTemplates] = useState<PolicyTemplateSummary[]>([])
  const [activeTemplateId, setActiveTemplateId] = useState<string | null>(null)
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null)
  const [selectedTemplate, setSelectedTemplate] = useState<PolicyTemplateDetail | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [isLoadingTemplate, setIsLoadingTemplate] = useState(false)
  const [isActivating, setIsActivating] = useState(false)

  const fetchTemplates = useCallback(async () => {
    try {
      const res = await apiClient.get<PolicyTemplateSummary[]>('/chat/api/v1/policies')
      if (!res.ok) throw new Error(res.error || 'Failed to fetch policy templates')

      const list = res.data || []
      setTemplates(list)

      const active = list.find(t => t.isActive)?.id || null
      setActiveTemplateId(active)

      setSelectedTemplateId((prev) => {
        if (prev && list.some(t => t.id === prev)) return prev
        if (active) return active
        return list[0]?.id || null
      })
    } catch (error) {
      toast({
        title: 'Failed to Load AI Policies',
        description: getErrorMessage(error, 'Unable to load policy templates'),
        variant: 'destructive',
        duration: 5000,
      })
      throw error
    }
  }, [toast])

  const fetchTemplate = useCallback(
    async (policyId: string) => {
      setIsLoadingTemplate(true)
      try {
        const res = await apiClient.get<PolicyTemplateDetail>(`/chat/api/v1/policies/${encodeURIComponent(policyId)}`)
        if (!res.ok) throw new Error(res.error || 'Failed to fetch policy template')
        setSelectedTemplate(res.data || null)
        return res.data || null
      } catch (error) {
        toast({
          title: 'Failed to Load Policy',
          description: getErrorMessage(error, 'Unable to load policy'),
          variant: 'destructive',
          duration: 5000,
        })
        throw error
      } finally {
        setIsLoadingTemplate(false)
      }
    },
    [toast]
  )

  const activateTemplate = useCallback(
    async (policyId: string) => {
      setIsActivating(true)
      try {
        const res = await apiClient.post(`/chat/api/v1/policies/${encodeURIComponent(policyId)}/activate`)
        if (!res.ok) throw new Error(res.error || 'Failed to activate policy template')

        toast({
          title: 'Guardrails Saved',
          description: 'Policy template activated successfully',
          variant: 'success',
          duration: 4000,
        })

        await fetchTemplates()
        await fetchTemplate(policyId)
      } catch (error) {
        toast({
          title: 'Save Failed',
          description: getErrorMessage(error, 'Unable to activate policy template'),
          variant: 'destructive',
          duration: 5000,
        })
        throw error
      } finally {
        setIsActivating(false)
      }
    },
    [toast, fetchTemplates, fetchTemplate]
  )

  useEffect(() => {
    ;(async () => {
      try {
        await fetchTemplates()
      } finally {
        setIsLoading(false)
      }
    })()
  }, [fetchTemplates])

  useEffect(() => {
    if (!selectedTemplateId) {
      setSelectedTemplate(null)
      return
    }
    if (selectedTemplateId === CUSTOM_CREATION_TEMPLATE_ID) return

    fetchTemplate(selectedTemplateId).catch(() => {
      // toasts handled in hook
    })
  }, [selectedTemplateId, fetchTemplate])

  const templateOptions = useMemo(
    () =>
      templates.map(t => ({
        id: t.id,
        label: t.displayName,
        description: t.description,
        isActive: t.isActive,
        type: t.type
      })),
    [templates]
  )

  const refetchSelectedTemplate = useCallback(() => {
    if (selectedTemplateId && selectedTemplateId !== CUSTOM_CREATION_TEMPLATE_ID) {
      return fetchTemplate(selectedTemplateId)
    }
    return Promise.resolve()
  }, [selectedTemplateId, fetchTemplate])

  const createOrUpdateCustomPolicy = useCallback(
    async (baseTemplateId: string, overrides: Record<string, ApprovalLevel>) => {
      try {
        const requestBody: CustomPolicyRequest = {
          templateId: baseTemplateId,
          overrides,
        }

        const res = await apiClient.put('/chat/api/v1/policies/custom', requestBody)
        if (!res.ok) throw new Error(res.error || 'Failed to save custom policy')

        toast({
          title: 'Custom Policy Saved',
          description: 'Your custom policy has been created successfully',
          variant: 'success',
          duration: 4000,
        })

        await fetchTemplates()

        return 'custom'
      } catch (error) {
        toast({
          title: 'Save Failed',
          description: getErrorMessage(error, 'Unable to save custom policy'),
          variant: 'destructive',
          duration: 5000,
        })
        throw error
      }
    },
    [toast, fetchTemplates]
  )

  return {
    templates,
    templateOptions,
    activeTemplateId,
    selectedTemplateId,
    setSelectedTemplateId,
    selectedTemplate,
    isLoading,
    isLoadingTemplate,
    isActivating,
    activateTemplate,
    createOrUpdateCustomPolicy,
    refetchTemplates: fetchTemplates,
    refetchSelectedTemplate,
  }
}

function useApiKeys() {
  const [items, setItems] = useState<ApiKeyRecord[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchApiKeys = useCallback(async () => {
    setIsLoading(true)
    setError(null)
    try {
      const res = await apiClient.get<ApiKeyRecord[]>('api/api-keys')
      if (!res.ok || !Array.isArray(res.data)) {
        throw new Error(res.error || `Failed to load API keys (${res.status})`)
      }
      setItems(res.data)
      return res.data
    } catch (e) {
      const msg = e instanceof Error ? e.message : 'Failed to load API keys'
      setError(msg)
      throw e
    } finally {
      setIsLoading(false)
    }
  }, [])

  const createApiKey = useCallback(async (data: { name: string; description?: string; expiresAt?: string | null }) => {
    const payload: any = {
      name: data.name,
      description: data.description || undefined,
      expiresAt: data.expiresAt ?? null,
    }
    const res = await apiClient.post<{ apiKey: ApiKeyRecord; fullKey: string }>('api/api-keys', payload)
    if (!res.ok || !res.data) {
      throw new Error(res.error || `Failed to create API key (${res.status})`)
    }
    return res.data
  }, [])

  const updateApiKey = useCallback(async (id: string, data: { name: string; description?: string; expiresAt?: string | null }) => {
    const payload: any = {
      name: data.name,
      description: data.description || undefined,
      expiresAt: data.expiresAt ?? null,
    }
    const res = await apiClient.put<ApiKeyRecord>(`api/api-keys/${encodeURIComponent(id)}`, payload)
    if (!res.ok || !res.data) {
      throw new Error(res.error || `Failed to update API key (${res.status})`)
    }
    return res.data
  }, [])

  const regenerateApiKey = useCallback(async (id: string) => {
    const res = await apiClient.post<{ apiKey: ApiKeyRecord; fullKey: string }>(`api/api-keys/${encodeURIComponent(id)}/regenerate`)
    if (!res.ok || !res.data) {
      throw new Error(res.error || `Failed to regenerate API key (${res.status})`)
    }
    return res.data
  }, [])

  const setApiKeyEnabled = useCallback(async (id: string, enabled: boolean) => {
    const res = await apiClient.put<ApiKeyRecord>(`api/api-keys/${encodeURIComponent(id)}`, { enabled })
    if (!res.ok || !res.data) {
      throw new Error(res.error || `Failed to ${enabled ? 'enable' : 'disable'} API key (${res.status})`)
    }
    return res.data
  }, [])

  return { items, isLoading, error, fetchApiKeys, createApiKey, updateApiKey, regenerateApiKey, setApiKeyEnabled }
}

interface GraphQLResponse<T> {
  data?: T
  errors?: Array<{ message: string }>
}

type IntegratedToolsResponse = {
  integratedTools: { tools: IntegratedTool[] }
}

function useIntegratedTools() {
  const { toast } = useToast()
  const [tools, setTools] = useState<IntegratedTool[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchIntegratedTools = useCallback(async (filter: Record<string, any> = { enabled: true, category: null }, search: string = '') => {
    setIsLoading(true)
    setError(null)
    try {
      const response = await apiClient.post<GraphQLResponse<IntegratedToolsResponse>>('/api/graphql', {
        query: GET_INTEGRATED_TOOLS_QUERY,
        variables: { filter, search }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const graphql = response.data
      if (graphql?.errors && graphql.errors.length) {
        throw new Error(graphql.errors[0].message)
      }

      const result = graphql?.data?.integratedTools?.tools ?? []
      setTools(result)
      return result
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch integrated tools'
      setError(message)
      toast({ title: 'Error fetching tools', description: message, variant: 'destructive' })
      throw err
    } finally {
      setIsLoading(false)
    }
  }, [toast])

  return { tools, isLoading, error, fetchIntegratedTools }
}

