type ApprovalRequestAction = {
  requestId: string
  approve: boolean
}

async function approveRequest(requestId: string, approve: boolean): Promise<void> {
  const res = await apiClient.post(`${API_ENDPOINTS.APPROVAL_REQUEST}/${requestId}/approve`, {
    approve
  })
  if (!res.ok) {
    throw new Error(res.error || `Failed to ${approve ? 'approve' : 'reject'} request (${res.status})`)
  }
}

function useApprovalRequests() {

  const approvalMutation = useMutation({
    mutationFn: ({ requestId, approve }: ApprovalRequestAction) => 
      approveRequest(requestId, approve),
  })

  const handleApproveRequest = (
    requestId: string,
    options?: {
      onSuccess?: (status: ApprovalStatus) => void
      onError?: (error: Error) => void
    }
  ) => {
    approvalMutation.mutate(
      { requestId, approve: true },
      {
        onSuccess: () => {
          options?.onSuccess?.(APPROVAL_STATUS.APPROVED)
        },
        onError: (error) => {
          options?.onError?.(error as Error)
        },
      }
    )
  }

  const handleRejectRequest = (
    requestId: string,
    options?: {
      onSuccess?: (status: ApprovalStatus) => void
      onError?: (error: Error) => void
    }
  ) => {
    approvalMutation.mutate(
      { requestId, approve: false },
      {
        onSuccess: () => {
          options?.onSuccess?.(APPROVAL_STATUS.REJECTED)
        },
        onError: (error) => {
          options?.onError?.(error as Error)
        },
      }
    )
  }

  return {
    // Actions
    handleApproveRequest,
    handleRejectRequest,

    // Status
    isLoading: approvalMutation.isPending,
    error: approvalMutation.error?.message ?? null,

    // Raw mutation
    approvalMutation,
  }
}

function useArchiveResolved() {
  const { toast } = useToast()
  const [isArchiving, setIsArchiving] = useState(false)

  const archiveResolvedDialogs = useCallback(async (dialogs: Dialog[]): Promise<boolean> => {
    const resolvedDialogs = dialogs.filter(d => d.status === 'RESOLVED')

    if (resolvedDialogs.length === 0) {
      toast({
        title: 'No Resolved Dialogs',
        description: 'There are no resolved dialogs to archive',
        variant: 'info',
        duration: 3000
      })
      return false
    }

    setIsArchiving(true)

    try {
      const archivePromises = resolvedDialogs.map(dialog => 
        apiClient.patch(`/chat/api/v1/dialogs/${dialog.id}/status`, { status: 'ARCHIVED' })
      )

      const results = await Promise.allSettled(archivePromises)

      const successCount = results.filter(r => r.status === 'fulfilled' && r.value.ok).length
      const failCount = results.length - successCount

      if (successCount > 0) {
        toast({
          title: 'Success',
          description: `${successCount} dialog${successCount > 1 ? 's' : ''} archived successfully${failCount > 0 ? ` (${failCount} failed)` : ''}`,
          variant: 'success',
          duration: 4000
        })
      }

      if (failCount > 0 && successCount === 0) {
        toast({
          title: 'Error',
          description: `Failed to archive ${failCount} dialog${failCount > 1 ? 's' : ''}`,
          variant: 'destructive',
          duration: 5000
        })
        return false
      }

      return successCount > 0
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to archive resolved dialogs'
      console.error('Failed to archive resolved dialogs:', error)

      toast({
        title: 'Error',
        description: errorMessage,
        variant: 'destructive',
        duration: 5000
      })

      return false
    } finally {
      setIsArchiving(false)
    }
  }, [toast])

  return {
    archiveResolvedDialogs,
    isArchiving
  }
}

interface UseChunkCatchupOptions {
  dialogId: string | null
  onChunkReceived: (chunk: ChunkData, messageType: NatsMessageType) => void
}

function useChunkCatchup({ dialogId, onChunkReceived }: UseChunkCatchupOptions): UseChunkCatchupReturn {
  const fetchChunks = useCallback(async (
    dialogId: string,
    chatType: typeof CHAT_TYPE[keyof typeof CHAT_TYPE],
    fromSequenceId?: number | null
  ): Promise<ChunkData[]> => {
    let url = `${API_ENDPOINTS.DIALOG_CHUNKS}/${dialogId}/chunks?chatType=${chatType}`
    if (fromSequenceId !== null && fromSequenceId !== undefined) {
      url += `&fromSequenceId=${fromSequenceId}`
    }

    const response = await apiClient.get<ChunkData[]>(url)

    if (!response.ok) {
      console.error(`Failed to fetch ${chatType} chunks:`, response.status)
      return []
    }

    return response.data || []
  }, [])

  const options = useMemo<CoreChunkCatchupOptions>(() => ({
    dialogId,
    onChunkReceived,
    chatTypes: [CHAT_TYPE.CLIENT, CHAT_TYPE.ADMIN],
    fetchChunks,
  }), [dialogId, onChunkReceived, fetchChunks])

  return useChunkCatchupCore(options)
}

