interface MessagesResponse {
  messages: MessageConnection
}

function useDialogMessages(dialogId: string) {
  const { toast } = useToast()
  const [messages, setMessages] = useState<Message[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [hasMore, setHasMore] = useState(false)
  const [cursor, setCursor] = useState<string | null>(null)

  const fetchMessages = useCallback(async (append: boolean = false) => {
    if (!dialogId) return

    setIsLoading(true)
    setError(null)

    try {
      let allMessages: Message[] = []
      let currentCursor: string | null = append ? cursor : null
      let hasNextPage = true

      while (hasNextPage) {
        const response = await apiClient.post<GraphQLResponse<MessagesResponse>>('/chat/graphql', {
          query: GET_DIALOG_MESSAGES_QUERY,
          variables: {
            dialogId,
            cursor: currentCursor,
            limit: 100
          }
        })

        if (!response.ok) {
          throw new Error(response.error || `Request failed with status ${response.status}`)
        }

        const graphqlResponse = response.data

        if (graphqlResponse?.errors && graphqlResponse.errors.length > 0) {
          throw new Error(graphqlResponse.errors[0].message || 'GraphQL error occurred')
        }

        if (!graphqlResponse?.data) {
          throw new Error('No data received from server')
        }

        const connection = graphqlResponse.data.messages
        const batchMessages = (connection?.edges || []).map(edge => edge.node)

        allMessages = [...allMessages, ...batchMessages]
        hasNextPage = connection?.pageInfo?.hasNextPage || false
        currentCursor = connection?.pageInfo?.endCursor || null
      }

      if (append) {
        setMessages(prev => [...prev, ...allMessages])
      } else {
        setMessages(allMessages)
      }

      setHasMore(false)
      setCursor(null)

      return allMessages
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch messages'
      console.error('Failed to fetch messages:', error)
      setError(errorMessage)

      toast({
        title: 'Error',
        description: `Failed to load messages: ${errorMessage}`,
        variant: 'destructive',
        duration: 5000
      })

      throw error
    } finally {
      setIsLoading(false)
    }
  }, [dialogId, cursor, toast])

  const loadMore = useCallback(() => {
    if (!isLoading && hasMore) {
      return fetchMessages(true)
    }
  }, [fetchMessages, isLoading, hasMore])

  const refresh = useCallback(async () => {
    setCursor(null)
    return fetchMessages(false)
  }, [fetchMessages])

  useEffect(() => {
    if (dialogId) {
      fetchMessages(false).catch(() => {})
    }
  }, [dialogId])

  return {
    messages,
    isLoading,
    error,
    hasMore,
    loadMore,
    refresh
  }
}

function useDialogRealtimeProcessor(options: UseDialogRealtimeProcessorOptions) {
  const {
    dialogId,
    onStreamStart,
    onStreamEnd,
    onMessageAdd,
    onError
  } = options

  const processChunk = useCallback((payload: unknown, messageType: NatsMessageType = 'message') => {
    if (!dialogId) return

    const asAny = payload as any
    const nowIso = new Date().toISOString()
    const isAdmin = messageType === 'admin-message'
    const chatType = isAdmin ? 'ADMIN_AI_CHAT' : 'CLIENT_CHAT'

    const ADMIN_CHAT_TYPE = CHAT_TYPE.ADMIN

    const isMessageObject =
      asAny &&
      typeof asAny === 'object' &&
      typeof asAny.id === 'string' &&
      typeof asAny.dialogId === 'string' &&
      asAny.messageData != null &&
      asAny.owner != null

    if (isMessageObject) {
      const message = asAny as Message
      if (message.dialogId !== dialogId) return

      const isAdminMessage = message.chatType === ADMIN_CHAT_TYPE
      onMessageAdd(message, isAdminMessage)
      return
    }

    const action = parseChunkToAction(payload)
    if (!action) return

    if (action.action === 'message_start') {
      onStreamStart(isAdmin)
      return
    }

    if (action.action === 'message_end') {
      onStreamEnd(isAdmin)
      return
    }

    if (action.action === 'error') {
      onError(action.error, isAdmin)
      return
    }

    const id = `nats-${Date.now()}-${Math.random().toString(16).slice(2)}`
    const createBaseMessage = (isUserMessage: boolean): Message => {
      let owner: any
      if (isUserMessage) {
        owner = isAdmin 
          ? { type: 'ADMIN' as const, userId: '' } 
          : { type: 'CLIENT' as const, machineId: '' }
      } else {
        owner = { type: 'ASSISTANT' as const, model: '' }
      }

      return {
        id,
        dialogId: dialogId || '',
        chatType: chatType as any,
        dialogMode: 'DEFAULT',
        createdAt: nowIso,
        owner: owner as any,
        messageData: { type: 'TEXT', text: '' } as any,
      }
    }

    let message: Message | null = null

    switch (action.action) {
      case 'message_request':
        message = { 
          ...createBaseMessage(true), 
          messageData: { type: 'TEXT', text: action.text } as any 
        }
        break

      case 'text':
        message = { 
          ...createBaseMessage(false), 
          messageData: { type: 'TEXT', text: action.text } as any 
        }
        break

      case 'tool_execution': {
        const toolData = action.segment.data
        message = {
          ...createBaseMessage(false),
          messageData: {
            type: toolData.type,
            integratedToolType: toolData.integratedToolType,
            toolFunction: toolData.toolFunction,
            parameters: toolData.parameters,
            result: toolData.result,
            success: toolData.success,
          } as any,
        }
        break
      }

      case 'approval_request':
        message = {
          ...createBaseMessage(false),
          messageData: {
            type: 'APPROVAL_REQUEST',
            approvalType: action.approvalType,
            command: action.command,
            approvalRequestId: action.requestId,
            explanation: action.explanation,
          } as any,
        }
        break

      case 'approval_result':
        message = {
          ...createBaseMessage(false),
          messageData: {
            type: 'APPROVAL_RESULT',
            approvalRequestId: action.requestId,
            approved: action.approved,
            approvalType: action.approvalType,
          } as any,
        }
        break

      default:
        // Ignore metadata and other non-content actions
        return
    }

    if (message) {
      onMessageAdd(message, isAdmin)
    }
  }, [dialogId, onStreamStart, onStreamEnd, onMessageAdd, onError])

  return {
    processChunk
  }
}

interface UpdateStatusResponse {
  success: boolean
  dialog?: {
    id: string
    status: DialogStatus
  }
  error?: string
}

function useDialogStatus() {
  const { toast } = useToast()
  const [isUpdating, setIsUpdating] = useState(false)

  const updateDialogStatus = useCallback(async (dialogId: string, status: DialogStatus): Promise<boolean> => {
    if (isUpdating) return false

    setIsUpdating(true)

    try {
      const response = await apiClient.patch<UpdateStatusResponse>(
        `/chat/api/v1/dialogs/${dialogId}/status`,
        { status }
      )

      if (!response.ok) {
        throw new Error(response.error || `Failed to update dialog status`)
      }

      toast({
        title: 'Success',
        description: `Dialog ${status === 'ON_HOLD' ? 'put on hold' : status === 'RESOLVED' ? 'resolved' : 'status updated'} successfully`,
        variant: 'success',
        duration: 3000
      })

      return true
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to update dialog status'
      console.error('Failed to update dialog status:', error)

      toast({
        title: 'Error',
        description: errorMessage,
        variant: 'destructive',
        duration: 5000
      })

      return false
    } finally {
      setIsUpdating(false)
    }
  }, [isUpdating, toast])

  const putOnHold = useCallback(async (dialogId: string) => {
    return updateDialogStatus(dialogId, 'ON_HOLD')
  }, [updateDialogStatus])

  const resolve = useCallback(async (dialogId: string) => {
    return updateDialogStatus(dialogId, 'RESOLVED')
  }, [updateDialogStatus])

  const activate = useCallback(async (dialogId: string) => {
    return updateDialogStatus(dialogId, 'ACTIVE')
  }, [updateDialogStatus])

  return {
    updateDialogStatus,
    putOnHold,
    resolve,
    activate,
    isUpdating
  }
}

