function useDialogs(archived: boolean = false) {
  const { toast } = useToast()
  const [searchTerm, setSearchTerm] = useState('')
  const [dialogs, setDialogs] = useState<Dialog[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchDialogs = useCallback(async (searchParam?: string) => {
    setIsLoading(true)
    setError(null)

    try {
      const response = await apiClient.post<GraphQLResponse<DialogsResponse>>('/chat/graphql', {
        query: GET_DIALOGS_QUERY,
        variables: {
          filter: archived ? { statuses: ['ARCHIVED'] } : undefined,
          pagination: { limit: 50 },
          search: searchParam || undefined,
          slaSort: 'ASC'
        }
      })

      if (!response.ok) {
        throw new Error(response.error || `Request failed with status ${response.status}`)
      }

      const graphqlResponse = response.data

      if (graphqlResponse?.errors && graphqlResponse.errors.length > 0) {
        throw new Error(graphqlResponse.errors[0].message || 'GraphQL error occurred')
      }

      if (!graphqlResponse?.data) {
        throw new Error('No data received from server')
      }

      const connection = graphqlResponse.data.dialogs
      const nodes = (connection?.edges || []).map(edge => edge.node)
      setDialogs(nodes)
      return graphqlResponse.data
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to fetch dialogs'
      console.error('Failed to fetch dialogs:', error)
      setError(errorMessage)

      toast({
        title: 'Error',
        description: `Failed to fetch ${archived ? 'archived' : 'current'} chats: ${errorMessage}`,
        variant: 'destructive'
      })

      throw error
    } finally {
      setIsLoading(false)
    }
  }, [archived, toast])

  const searchDialogs = useCallback(async (term: string) => {
    setSearchTerm(term)
    return fetchDialogs(term)
  }, [fetchDialogs])

  const refreshDialogs = useCallback(async () => {
    try {
      await fetchDialogs(searchTerm)
      toast({
        title: 'Success',
        description: `${archived ? 'Archived' : 'Current'} chats refreshed successfully`,
        variant: 'success'
      })
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to refresh dialogs'
      toast({
        title: 'Error',
        description: `Failed to refresh ${archived ? 'archived' : 'current'} chats: ${errorMessage}`,
        variant: 'destructive'
      })
    }
  }, [fetchDialogs, archived, toast, searchTerm])

  return {
    dialogs,
    isLoading,
    error,
    searchDialogs,
    refreshDialogs,
    fetchDialogs
  }
}

function getAccessToken(): string | null {
  if (typeof window === 'undefined') return null
  try {
    return localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN) || null
  } catch {
    return null
  }
}

function getApiBaseUrl(): string | null {
  const envBase = runtimeEnv.tenantHostUrl()
  if (envBase) return envBase
  if (typeof window !== 'undefined' && window.location?.origin) return window.location.origin
  return null
}

function useNatsDialogSubscription({
  enabled,
  dialogId,
  onEvent,
  onConnect,
  onDisconnect,
  onSubscribed,
}: UseNatsDialogSubscriptionArgs): UseNatsDialogSubscriptionReturn {
  const [apiBaseUrl, setApiBaseUrl] = useState<string | null>(getApiBaseUrl)
  const isDevTicketEnabled = runtimeEnv.enableDevTicketObserver()
  const [token, setToken] = useState<string | null>(
    isDevTicketEnabled ? getAccessToken() : null
  )

  useEffect(() => {
    if (!isDevTicketEnabled) return

    const handler = (e: StorageEvent) => {
      if (e.key === STORAGE_KEYS.ACCESS_TOKEN) {
        setToken(getAccessToken())
      }
    }
    window.addEventListener('storage', handler)
    return () => window.removeEventListener('storage', handler)
  }, [isDevTicketEnabled])

  useEffect(() => {
    setApiBaseUrl(getApiBaseUrl())
  }, [])

  const getNatsWsUrl = useMemo(() => {
    return (): string | null => {
      if (!apiBaseUrl) return null

      if (isDevTicketEnabled && !token) return null

      return buildNatsWsUrl(apiBaseUrl, {
        token: token || undefined,
        includeAuthParam: isDevTicketEnabled,
      })
    }
  }, [apiBaseUrl, token, isDevTicketEnabled])

  const clientConfig = useMemo(() => ({
    name: 'openframe-frontend-mingo',
    user: 'machine',
    pass: '',
  }), [])

  return useNatsDialogSubscriptionCore({
    enabled,
    dialogId,
    topics: ADMIN_TOPICS,
    onEvent,
    onConnect,
    onDisconnect,
    onSubscribed,
    getNatsWsUrl,
    clientConfig,
  })
}

function Tickets() {
  const router = useRouter()

  useEffect(() => {
    if (!isSaasTenantMode()) {
      router.replace('/dashboard')
      return
    }
  }, [router])

  // Don't render anything if not in saas-tenant mode
