function isCurrentApp(appType: AppType): boolean {
  return getCurrentAppType() === appType
}

function isRouteAllowed(pathname: string): boolean {
  const config = getAppConfig()

  // Check if route is explicitly restricted
  if (config.navigation.restrictedRoutes.includes('*')) {
    return config.navigation.allowedRoutes.includes(pathname)
  }

  if (config.navigation.restrictedRoutes.some(route => pathname.startsWith(route))) {
    return false
  }

  // Check if route is in allowed routes (if specified)
  if (config.navigation.allowedRoutes.length > 0) {
    return config.navigation.allowedRoutes.some(route => 
      pathname === route || pathname.startsWith(route + '/')
    )
  }

  return true
}

function shouldShowAdminMenu(userRole?: string): boolean {
  const config = getAppConfig()
  return config.navigation.showAdminMenuInHeader && userRole === 'super_admin'
}

function getAppMode(): AppMode {
  const mode = runtimeEnv.appMode() as AppMode
  return (mode as AppMode) || 'oss-tenant'
}

function getDefaultRedirectPath(isAuthenticated: boolean): string {
  const mode = getAppMode()

  if (mode === 'saas-shared') {
    return '/auth'
  }

  if (mode === 'saas-tenant') {
    // App-only: send users to the app landing (no auth pages)
    return '/dashboard'
  }

  // oss-tenant: auth + app
  return isAuthenticated ? '/dashboard' : '/auth'
}

function isAppEnabled(): boolean {
  return isOssTenantMode() || isSaasTenantMode()
}

function isAuthEnabled(): boolean {
  return isOssTenantMode() || isSaasSharedMode()
}

function isAuthOnlyMode(): boolean {
  // Backward-compatible alias for auth-only behavior
  return getAppMode() === 'saas-shared'
}

function isFullAppMode(): boolean {
  // Kept for compatibility: means app pages are enabled
  return isOssTenantMode() || isSaasTenantMode()
}

function isOssTenantMode(): boolean {
  return getAppMode() === 'oss-tenant'
}

function isRouteAllowedInCurrentMode(pathname: string): boolean {
  const mode = getAppMode()

  // Always allow Next.js internals and static assets
  if (
    pathname.startsWith('/_next') ||
    pathname.startsWith('/static') ||
    pathname.startsWith('/favicon') ||
    pathname.startsWith('/assets') ||
    pathname.startsWith('/icons')
  ) {
    return true
  }

  if (mode === 'saas-shared') {
    // Auth-only mode: only auth routes and root
    return pathname.startsWith('/auth') || pathname === '/'
  }

  if (mode === 'saas-tenant') {
    // App-only mode: block all auth routes
    return !pathname.startsWith('/auth')
  }

  if (mode === 'oss-tenant') {
    if (pathname.startsWith('/mingo')) {
      return false
    }
  }

  return true
}

function isSaasSharedMode(): boolean {
  return getAppMode() === 'saas-shared'
}

function isSaasTenantMode(): boolean {
  return getAppMode() === 'saas-tenant'
}

function shouldShowAppPages(): boolean {
  return isAppEnabled()
}

function shouldShowNavigationSidebar(): boolean {
  return isAppEnabled()
}

class AuthApiClient {
  private isRefreshing: boolean = false
  private refreshPromise: Promise<boolean> | null = null

  private async refreshAccessToken(): Promise<boolean> {
    if (this.isRefreshing && this.refreshPromise) {
      return this.refreshPromise
    }

    this.isRefreshing = true

    this.refreshPromise = (async () => {
      try {
        let tenantId: string | undefined
        try {
          const { useAuthStore } = await import('../app/auth/stores/auth-store')
          const authState = useAuthStore.getState()
          tenantId = authState.tenantId || (authState.user as any)?.organizationId || (authState.user as any)?.tenantId
        } catch {}

        const refreshResponse = await this.refresh(tenantId || '')

        if (refreshResponse.status === 401) {
          clearStoredTokens()
          return false
        }

        if (refreshResponse.ok) {
          if (runtimeEnv.enableDevTicketObserver()) {
            let newAccessToken: string | null = null
            let newRefreshToken: string | null = null

            if (refreshResponse.data) {
              newAccessToken = refreshResponse.data?.access_token || refreshResponse.data?.accessToken || null
              newRefreshToken = refreshResponse.data?.refresh_token || refreshResponse.data?.refreshToken || null
            }

            if (newAccessToken) {
              localStorage.setItem(ACCESS_TOKEN_KEY, newAccessToken)
              if (newRefreshToken) {
                localStorage.setItem(REFRESH_TOKEN_KEY, newRefreshToken)
              }
              return true
            } else {
              return true
            }
          }
          return true
        } else {
          clearStoredTokens()
          return false
        }
      } catch (error) {
        return false
      } finally {
        this.isRefreshing = false
        this.refreshPromise = null
      }
    })()

    return this.refreshPromise
  }

  private async forceLogout(): Promise<void> {
    await forceLogout({
      reason: 'Auth API Client - Token refresh failed'
    })
  }

  async handleUnauthorized<T>(
    url: string,
    headers: Record<string, string>,
    init: RequestInit
  ): Promise<AuthApiResponse<T> | null> {
    const refreshSuccess = await this.refreshAccessToken()

    if (refreshSuccess) {
      if (runtimeEnv.enableDevTicketObserver()) {
        const newToken = localStorage.getItem('of_access_token')
        if (newToken) {
          headers['Authorization'] = `Bearer ${newToken}`
        }
      }

      const retryRes = await fetch(url, {
        credentials: 'include',
        headers,
        ...init,
      })

      let retryData: T | undefined
      const retryContentType = retryRes.headers.get('content-type') || ''
      if (retryContentType.includes('application/json')) {
        try { retryData = await retryRes.json() } catch {}
      }

      return {
        data: retryData,
        error: retryRes.ok ? undefined : `Request failed with status ${retryRes.status}`,
        status: retryRes.status,
        ok: retryRes.ok,
      }
    } else {
      await this.forceLogout()
      return null
    }
  }

  refresh<T = any>(tenantId?: string) {
    const query = tenantId ? `?tenantId=${encodeURIComponent(tenantId)}` : ''
    return requestRefresh<T>(`/oauth/refresh${query}`, { method: 'POST' })
