    }

    const url = buildAuthUrl(`/sas/invitations/accept/sso?${params.toString()}`)
    window.location.href = url

    return Promise.resolve({ ok: true, status: 302, data: null, error: null })
  }

  confirmPasswordReset<T = any>(payload: {
