interface ForceLogoutOptions {
  reason?: string
  shouldRedirect?: boolean
  redirectPath?: string
}

function clearStoredTokens(): void {
  if (typeof window === 'undefined') {
    return
  }

  try {
    localStorage.removeItem(ACCESS_TOKEN_KEY)
    localStorage.removeItem(REFRESH_TOKEN_KEY)
  } catch (error) {
    console.error('[Token Clear] Failed to clear tokens:', error)
  }
}

async function forceLogout(options: ForceLogoutOptions = {}): Promise<void> {
  const { 
    reason = 'authentication failure', 
    shouldRedirect = true,
    redirectPath
  } = options

  if (typeof window === 'undefined') {
    return
  }

  const currentPath = window.location.pathname
  const isAuthPage = currentPath.startsWith('/auth')

  try {
    localStorage.removeItem(ACCESS_TOKEN_KEY)
    localStorage.removeItem(REFRESH_TOKEN_KEY)
  } catch (error) {
    console.error('[Force Logout] Failed to clear tokens from localStorage:', error)
  }

  try {
    const { useAuthStore } = await import('../app/auth/stores/auth-store')
    const { logout } = useAuthStore.getState()
    logout()
  } catch (error) {
    console.error('[Force Logout] Failed to clear auth store:', error)
  }

  if (shouldRedirect && !isAuthPage) {
    if (isSaasTenantMode()) {
      return
    }
    try {
      const targetPath = redirectPath || getDefaultRedirectPath(false)
      window.location.href = targetPath
    } catch (error) {
      window.location.href = '/auth'
    }
  }
}

function hasStoredTokens(): boolean {
  if (typeof window === 'undefined') {
    return false
  }

  try {
    const accessToken = localStorage.getItem(ACCESS_TOKEN_KEY)
    const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY)
    return !!(accessToken || refreshToken)
  } catch {
    return false
  }
}

function clearGraphQLCache(): void {
  introspector.clearCache()
  console.log('[GraphQL] Schema cache cleared')
}

async function initializeGraphQLIntrospection(force = false): Promise<void> {
  try {
    // Skip if already loaded (unless forced)
    if (!force && introspector.isLoaded()) {
      console.log('[GraphQL] Schema already loaded from cache')
      return
    }

    console.log('[GraphQL] Initializing schema introspection...')

    // Get auth headers (for DevTicket mode)
    const headers: Record<string, string> = {}

    if (runtimeEnv.enableDevTicketObserver()) {
      try {
        const accessToken = localStorage.getItem('of_access_token')
        if (accessToken) {
          headers['Authorization'] = `Bearer ${accessToken}`
        }
      } catch (error) {
        console.warn('[GraphQL] Failed to get access token:', error)
      }
    }

    // Fetch schema via introspection
    await introspector.fetchSchema(GRAPHQL_ENDPOINT, headers, force)

    console.log('[GraphQL] Schema introspection complete')
  } catch (error) {
    console.error('[GraphQL] Introspection failed:', error)
    // Don't throw - URL state hooks can still work without introspection
    // (nested types just won't be automatically flattened)
  }
}

function isGraphQLSchemaLoaded(): boolean {
  return introspector.isLoaded()
}

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message
  }

  if (typeof error === 'string') {
    return error
  }

  return 'An unexpected error occurred'
}

function handleApiError(
  error: unknown,
  toast: (options: { title: string; description: string; variant: 'destructive' }) => void,
  defaultMessage: string = 'Operation failed'
): void {
  const message = getErrorMessage(error)

  toast({
    title: defaultMessage,
    description: message,
    variant: 'destructive',
  })
}

function navigateToLogDetails(router: any, log: any): void {
  // Extract from originalLogEntry if available (logs-table pattern)
  // Otherwise use the log directly (dashboard pattern)
  const original = log.originalLogEntry || log

  // Get log ID (can be either 'id' or 'toolEventId')
  const id = log.id || log.toolEventId

  // Extract required parameters from original/raw log entry
  const ingestDay = original.ingestDay
  const toolType = original.toolType      // Raw DB value (e.g., "tacticalrmm")
  const eventType = original.eventType
  const timestamp = original.timestamp

  // Build URL with all required parameters
  const url = `/log-details?id=${id}` +
    `&ingestDay=${ingestDay}` +
    `&toolType=${toolType}` +
    `&eventType=${eventType}` +
    `&timestamp=${encodeURIComponent(timestamp || '')}`

  router.push(url)
}

class FileBinaryProtocol {
  private buffer = new Uint8Array(0)

  /**
   * Push new binary data into the accumulator and invoke callback for each full chunk.
   */
  push(data: ArrayBuffer, onChunk: (payload: Uint8Array, isFinal: boolean) => void): void {
    if (!data || (data.byteLength ?? 0) === 0) return

    const incoming = new Uint8Array(data)
    const merged = new Uint8Array(this.buffer.length + incoming.length)
    merged.set(this.buffer)
    merged.set(incoming, this.buffer.length)
    this.buffer = merged

    this.consume(onChunk)
  }

  private consume(onChunk: (payload: Uint8Array, isFinal: boolean) => void): void {
    while (this.buffer.length >= 4) {
      const headerValue = this.readHeader(this.buffer.subarray(0, 4))
      const totalLength = 4 + headerValue.length

      if (this.buffer.length < totalLength) {
        return
      }

      const payload = this.buffer.slice(4, totalLength)
      onChunk(payload, headerValue.final)
      this.buffer = this.buffer.slice(totalLength)
    }
  }

  private readHeader(headerBytes: Uint8Array): { length: number; final: boolean } {
    if (headerBytes.length < 4) {
      throw new Error('Incomplete binary header')
    }

    // Original protocol: bits 1-31 = length, bit 0 = final
    const raw =
      headerBytes[0] |
      (headerBytes[1] << 8) |
      (headerBytes[2] << 16) |
      (headerBytes[3] << 24)

    const final = (raw & 1) === 1
    const length = raw >>> 1

    return { length, final }
  }

  reset(): void {
    this.buffer = new Uint8Array(0)
  }

  /**
   * Helper to check if payload is binary
   */
  isBinaryData(data: any): boolean {
    return data instanceof ArrayBuffer ||
      data instanceof Uint8Array ||
      (data && data.constructor && data.constructor.name === 'ArrayBuffer')
  }
}

