    for (const error of this.errorHistory) {
      const count = counts.get(error.type) || 0
      counts.set(error.type, count + 1)
    }

    return counts
  }

getErrorHistory(): FileError[] {
    return [...this.errorHistory]
  }

getLastError(): FileError | undefined {
