async function deleteWithAuth(endpoint: string): Promise<void> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json'
  }

  if (runtimeEnv.enableDevTicketObserver()) {
    try {
      const accessToken = localStorage.getItem('of_access_token')
      if (accessToken) {
        headers['Authorization'] = `Bearer ${accessToken}`
      }
    } catch (error) {
      // Silently continue without token
    }
  }

  const url = endpoint.startsWith('http') 
    ? endpoint 
    : endpoint.startsWith('/api')
      ? `${runtimeEnv.tenantHostUrl()}${endpoint}`
      : `${runtimeEnv.tenantHostUrl()}/api${endpoint}`

  const response = await fetch(url, {
    method: 'DELETE',
    credentials: 'include',
    headers
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Delete failed (${response.status}): ${errorText || response.statusText}`)
  }
}

async function uploadWithAuth(
  endpoint: string,
  file: File,
  fieldName: string = 'file'
): Promise<string> {
  const formData = new FormData()
  formData.append(fieldName, file)

  const headers: Record<string, string> = {}

  if (runtimeEnv.enableDevTicketObserver()) {
    try {
      const accessToken = localStorage.getItem('of_access_token')
      if (accessToken) {
        headers['Authorization'] = `Bearer ${accessToken}`
      }
    } catch (error) {
      // Silently continue without token
    }
  }

  const url = endpoint.startsWith('http') 
    ? endpoint 
    : endpoint.startsWith('/api')
      ? `${runtimeEnv.tenantHostUrl()}${endpoint}`
      : `${runtimeEnv.tenantHostUrl()}/api${endpoint}`

  const response = await fetch(url, {
    method: 'POST',
    body: formData,
    credentials: 'include',
    headers
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Upload failed (${response.status}): ${errorText || response.statusText}`)
  }

  const data = await response.json()

  const uploadedUrl = 
    data.url || 
    data.imageUrl || 
    data.file_url || 
    (data.data && data.data.url) ||
    (data.data && data.data.imageUrl) ||
    (data.image && data.image.imageUrl)

  if (!uploadedUrl) {
    throw new Error('No URL returned in upload response')
  }

  return uploadedUrl
}

function useAuthenticatedUpload() {
  const [isUploading, setIsUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const upload = useCallback(async (
    endpoint: string,
    file: File,
    fieldName?: string
  ): Promise<string | null> => {
    setIsUploading(true)
    setError(null)

    try {
      const url = await uploadWithAuth(endpoint, file, fieldName)
      return url
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Upload failed'
      setError(message)
      return null
    } finally {
      setIsUploading(false)
    }
  }, [])

  return { upload, isUploading, error }
}

function useAuthenticatedImage(imageUrl?: string | null, refreshKey?: string | number) {
  const [fetchedImageUrl, setFetchedImageUrl] = useState<string | undefined>()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cleanup: (() => void) | undefined

    if (imageUrl) {
      setIsLoading(true)
      setError(null)

      const tenantHost = runtimeEnv.tenantHostUrl()

      let fullImageUrl: string
      if (imageUrl.startsWith('http://') || imageUrl.startsWith('https://')) {
        fullImageUrl = imageUrl
      } else if (imageUrl.startsWith('/api/')) {
        fullImageUrl = `${tenantHost}${imageUrl}`
      } else if (imageUrl.startsWith('/')) {
        fullImageUrl = `${tenantHost}/api${imageUrl}`
      } else {
        fullImageUrl = `${tenantHost}/api/${imageUrl}`
      }

      const cacheBuster = refreshKey ? `?v=${refreshKey}` : `?t=${Date.now()}`
      fullImageUrl = fullImageUrl + cacheBuster

      const headers: Record<string, string> = {
        'Accept': 'image/*',
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Pragma': 'no-cache'
      }

      if (runtimeEnv.enableDevTicketObserver()) {
        try {
          const accessToken = localStorage.getItem('of_access_token')
          if (accessToken) {
            headers['Authorization'] = `Bearer ${accessToken}`
          }
        } catch (error) {
          // Silently continue without token
        }
      }

      fetch(fullImageUrl, {
        method: 'GET',
        credentials: 'include',
        headers
      })
        .then(response => {
          if (!response.ok) {
            throw new Error(`Failed to fetch image: ${response.status}`)
          }
          return response.blob()
        })
        .then(blob => {
          const objectUrl = URL.createObjectURL(blob)
          setFetchedImageUrl(objectUrl)
          setIsLoading(false)

          cleanup = () => {
            URL.revokeObjectURL(objectUrl)
          }
        })
        .catch(error => {
          setError(error instanceof Error ? error.message : 'Failed to fetch image')
          setFetchedImageUrl(undefined)
          setIsLoading(false)
        })
    } else {
      setFetchedImageUrl(undefined)
      setIsLoading(false)
      setError(null)
    }

    return () => {
      if (cleanup) {
        cleanup()
      }
    }
  }, [imageUrl, refreshKey])

  return { imageUrl: fetchedImageUrl, isLoading, error }
}

function getAssetUrl(path: string): string {
  const baseUrl = getBaseUrl()
  return `${baseUrl}${path.startsWith('/') ? path : `/${path}`}`
}

function getBaseUrl(): string {
  // In browser, use relative URLs
  if (typeof window !== 'undefined') {
    return ''
  }

  // For non-browser contexts, prefer configured URLs
  const appUrl = runtimeEnv.appUrl()
  const devUrl = runtimeEnv.devUrl()

  return appUrl || devUrl || 'http://localhost:4000'
}

function defaultRedirect(): string {
  const mode = getMode()
  if (mode === 'saas-shared') return '/auth'
  if (mode === 'saas-tenant') return '/dashboard'
  return '/auth'
}

function getMode(): AppMode {
  const raw = process.env.NEXT_PUBLIC_APP_MODE as AppMode | undefined
  return (raw as AppMode) || 'oss-tenant'
}

function isAllowed(pathname: string): boolean {
  const mode = getMode()

  if (
    pathname.startsWith('/_next') ||
    pathname.startsWith('/static') ||
    pathname.startsWith('/favicon') ||
    pathname.startsWith('/assets') ||
    pathname.startsWith('/icons')
  ) {
    return true
  }

  if (mode === 'saas-shared') {
    return pathname.startsWith('/auth') || pathname === '/'
  }

  if (mode === 'saas-tenant') {
    return !pathname.startsWith('/auth')
  }

  return true
}

function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl

  if (!isAllowed(pathname)) {
    const url = request.nextUrl.clone()
    url.pathname = defaultRedirect()
    return NextResponse.redirect(url)
  }

  return NextResponse.next()
}

interface DeviceFilter {
  status?: Device['status'][]
  type?: Device['type'][]
  tags?: string[]
  searchQuery?: string
}

selectFilteredDevices = (state: DevicesState) => {
  let filtered = [...state.devices]

  // Apply filters
  const { status, type, tags, searchQuery } = state.filter

  if (status && status.length > 0) {
    filtered = filtered.filter((d) => status.includes(d.status))
  }

  if (type && type.length > 0) {
    filtered = filtered.filter((d) => type.includes(d.type))
  }

  if (tags && tags.length > 0) {
    filtered = filtered.filter((d) =>
      tags.some((tag) => d.tags?.includes(tag))
    )
  }

  if (searchQuery) {
    const query = searchQuery.toLowerCase()
    filtered = filtered.filter(
      (d) =>
        d.name.toLowerCase().includes(query) ||
        d.ipAddress?.toLowerCase().includes(query) ||
        d.location?.toLowerCase().includes(query)
    )
  }

  // Apply sorting
  filtered.sort((a, b) => {
    let comparison = 0

    switch (state.sortBy) {
      case 'name':
        comparison = a.name.localeCompare(b.name)
        break
      case 'lastSeen':
        comparison = new Date(a.lastSeen).getTime() - new Date(b.lastSeen).getTime()
        break
      case 'status':
        comparison = a.status.localeCompare(b.status)
        break
      case 'type':
        comparison = a.type.localeCompare(b.type)
        break
    }

    return state.sortOrder === 'asc' ? comparison : -comparison
  })

  return filtered
}

